        $("div#feedback").attr("title", "Provide feedback on this analyzer");
        $("div#feedback").find("a.blacklink").attr("href", "https://mosemp.us.oracle.com/epmos/faces/DocumentDisplay?id=2886645#feedback");

        /* Redirect links */
        $('a[href^="https://support.oracle.com/"]').each( function() {
