   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8508',
      p_sig_id                 => 'MSC_CALENDAR_START_AND_END_DATE_CHECK',
      p_sig_sql                => 'select /* MSC_CALENDAR_START_AND_END_DATE_CHECK */ min(calendar_date) "Start Date",
max(calendar_date) "End Date",
calendar_code "Calendar Code",
sr_instance_id "Instance ID"
from msc_calendar_dates
where calendar_end_date < (SYSDATE + (365*7))
or calendar_start_date > (SYSDATE - (365*2))
group by calendar_code, sr_instance_id
order by calendar_code',
      p_title                  => 'Check Calendar End and Start Dates',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'You have calendars with end dates that are less than 7 years into the future or start dates that are less than 2 years before the current date.  Not having calendars extended far enough into the past and/or the future is known to cause plan output issues as well as Memory Based Planner errors.',
      p_solution               => 'Please follow the steps outlined in: <br>
<br>
[2339771/KB402955] Incorrect Plan Output, Signal errors in Memory Based Planner, or APP-MRP-22064 MRLASS_ADD_SAFETY_STOCK error in Memory Based Planner',
      p_success_msg            => 'All calendars are extended properly.  This will help prevent calendar related errors.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
