      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '24'
      );
   l_info.delete;
debug('end add_signature: MSC_CALENDAR_START_AND_END_DATE_CHECK');



debug('begin add_signature: MISSING_0_PARTITION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5132',
      p_sig_id                 => 'MISSING_0_PARTITION',
      p_sig_sql                => 'select /* MISSING_0_PARTITION */ b.table_name,nvl(plan_id_flag,''N'') plan_id_flag
From MSC_ODS_TABLE_V B, DBA_PART_TABLES ptab
WHERE b.PARTITION_TYPE=''R'' 
and b.instance_id_flag in (''Y'')
and b.table_name = ptab.table_name
and ptab.owner=''MSC''
AND NOT EXISTS (select 1 
FROM  all_tab_partitions atp
WHERE atp.table_name = b.table_name AND
atp.table_owner = ''MSC'' AND
atp.partition_name = substr(b.table_name, 5) || ''_0'')',
      p_title                  => 'Missing _0 Partitions',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<span style="color: crimson; font-weight:bold;">You have missing _0 partitions!</span>
',
      p_solution               => 'The SQL results above show that you have one or more template (or base) partitions that have been accidentally dropped.  <BR>
