      p_sig_sql                => 'select /* PLAN_PARTITIONS_IN_ALL_TAB_PARTITIONS_NOT_IN_MSC_PLAN_PARTITIONS */ distinct substr(partition_name,instr(partition_name,''_'',-1,1)+1) "Partition Number", DECODE(INSTR(partition_name,''__''),0,''PLAN'',''INST'') "Partition Type",
table_name,
PARTITION_NAME
from all_tab_partitions
where table_name like ''MSC_%''
AND table_name not like ''MSC%F''
and table_name not like ''%ST_%''
and table_name NOT IN (''MSC_EXC_DETAILS_ALL'',''MSC_APCC_PEG_ITEM_D'',''MSC_APCC_ITEM_D'',''MSC_DEMANDS_CUSTOM'',''MSC_RESOURCE_HIERARCHY_MV'',''MSC_ITEM_HIERARCHY_MV'',''MSC_SINGLE_LVL_PEG'')
and table_name NOT LIKE (''MSC%F'')
and DECODE(INSTR(partition_name,''__''),0,''PLAN'',''INST'') = ''PLAN''
and TO_NUMBER(substr(partition_name,instr(partition_name,''_'',-1,1)+1)) != ALL(select distinct PLAN_ID from msc_plan_partitions)
and substr(partition_name,instr(partition_name,''_'',-1,1)+1) NOT IN (''0'',''999999'')',
