      p_sig_repo_id            => '24743',
      p_sig_id                 => 'EBS_MFG_VCP_MSCACA_SQL_1489347_1',
      p_sig_sql                => 'select /* EBS_MFG_VCP_MSCACA_SQL_1489347_1 */ mp.organization_code, 
       msi1.segment1 ASSEMBLY, 
       bsb.ALTERNATE_BOM_DESIGNATOR, 
       msi2.segment1 COMPONENT, 
       bcb.ITEM_NUM Item_Seq,
       bcb.component_sequence_id
from bom_components_b bcb, 
     bom_structures_b bsb, 
     mtl_system_items_b msi1,
     mtl_system_items_b msi2, 
     mtl_parameters mp
where bcb.change_notice is not null
and bcb.EFFECTIVITY_DATE is not null
and bcb.IMPLEMENTATION_DATE is null
and bcb.DISABLE_DATE is null
and bcb.BILL_SEQUENCE_ID = bsb.BILL_SEQUENCE_ID
and bcb.COMPONENT_ITEM_ID = msi2.INVENTORY_ITEM_ID
and bsb.ORGANIZATION_ID = mp.ORGANIZATION_ID
and bsb.ASSEMBLY_ITEM_ID = msi1.INVENTORY_ITEM_ID
and bsb.ORGANIZATION_ID = msi1.ORGANIZATION_ID
and bsb.ORGANIZATION_ID = msi2.ORGANIZATION_ID',
