      p_sig_sql                => 'Select   prv.rt_ovridn_flag ,
             prv.rt_ovridn_thru_dt,
             prv.rt_strt_dt,
             prv.rt_end_dt,
             prv.rt_val,
             pen.prtt_enrt_rslt_stat_cd, 
             pen.enrt_cvg_strt_dt,
             pen.enrt_cvg_thru_dt, 
             pen.effective_start_date, 
             pen.effective_end_date, 
             pen.per_in_ler_id, 
