debug('begin add_signature: MU_SLA-CST-INVALID-EVENTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23059',
      p_sig_id                 => 'MU_SLA-CST-INVALID-EVENTS',
      p_sig_sql                => 'SELECT LEDGER_ID LEDGER_ID,
LEDGER_NAME LEDGER_NAME,
PROCESS_STATUS PROCESS_STATUS,
EVENT_STATUS EVENT_STATUS,
COUNT COUNT
FROM (
SELECT XAE.LEDGER_ID LEDGER_ID,
GL.NAME LEDGER_NAME,
DECODE (XE.PROCESS_STATUS_CODE,''D'',''Draft'',''E'',''Error'',''I'',''Invalid'',''P'',''Processed'',''R'',''Related event in error'',''U'',''Unprocessed'',''F'',''Final Mode'',XE.PROCESS_STATUS_CODE) PROCESS_STATUS,
DECODE(XE.EVENT_STATUS_CODE,''I'',''Incomplete'',''N'',''No action'',''P'',''Processed'',''U'',''Unprocessed'') EVENT_STATUS,
COUNT(*) COUNT
FROM XLA_EVENTS XE, XLA_AE_HEADERS XAE, GL_LEDGERS GL
WHERE XE.APPLICATION_ID=707
AND XE.EVENT_ID=XAE.EVENT_ID
AND XAE.LEDGER_ID=GL.LEDGER_ID
AND XE.EVENT_DATE BETWEEN SYSDATE-7 AND SYSDATE
AND XE.EVENT_STATUS_CODE=''U''
AND XE.PROCESS_STATUS_CODE=''I''
GROUP BY XAE.LEDGER_ID, GL.NAME, XE.PROCESS_STATUS_CODE, XE.EVENT_STATUS_CODE)',
      p_title                  => 'Create Accounting-Cost Management Invalid Event Transactions in XLA_EVENTS',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invalid Records found after running Create accounting. Subledger Period Close Exceptions Report shows unprocessed records',
      p_solution               => 'Review[2005838/KB763584] SLA Create Accounting -Cost Management Common Error Code/Number.<br> 
 If you would like assistance for further diagnosis, please create an SR and Support will engage appropriately.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
