  (SELECT
    reg.party_tax_profile_id,
    reg.registration_number
  FROM zx_registrations reg
  ) reg
WHERE ptp.party_id               = hzcs.party_site_id
AND hzcs.party_site_id           = hzs.party_site_id
AND hzs.LOCATION_ID              = hzl.LOCATION_ID
AND ptp.party_type_code          = ''THIRD_PARTY_SITE''
AND reg.party_tax_profile_id(+)  = ptp.party_tax_profile_id
AND ptp.rep_registration_number IS NULL
AND reg.registration_number     IS NULL',
      p_title                  => 'VAT Registration Number (TRN) at Customer Site Level',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Vat Registration Number (TRN) is Null for Customer Site.',
      p_solution               => 'Review [1316316/KB731274#aref_section336] EB-Tax Data Corruption Issues & Recommended Solutions - Section 36: The VAT REGISTRATION NUMBER is Null for the following Customers and Customer Sites.',
      p_success_msg            => 'Customer Site has associated VAT Registration Number (TRN).',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: JE_NULL_VAT_REGISTRATION_CUSTOMER_SITE');



