debug('begin add_signature: LATEST_OPEN_PERIOD');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12320',
      p_sig_id                 => 'LATEST_OPEN_PERIOD',
      p_sig_sql                => 'SELECT ledger_id, ledger_name, latest_open_period_per_ledger, latest_open_period_should_be FROM
(SELECT gl.ledger_id,
       gl.name ledger_name,
       gl.latest_opened_period_name latest_open_period_per_ledger,
       gps.period_name latest_open_period_should_be
  FROM gl_ledgers gl,
       gl_period_statuses gps
 WHERE gl.ledger_id = gps.ledger_id
   AND gl.latest_opened_period_name <> gps.period_name
   AND gps.application_id = 101
   AND gps.closing_status = ''O''
   AND gps.period_num  = (SELECT MAX(gps2.period_num)
                            FROM gl_period_statuses gps2 
                           WHERE gps2.ledger_id = gl.ledger_id
                             AND gps2.closing_status = ''O''
                             AND gps2.period_year = gps.period_year
                             AND gps2.application_id = 101)
   AND gps.period_year = (SELECT MAX(gps1.period_year)
                            FROM gl_period_statuses gps1 
                           WHERE gps1.ledger_id = gl.ledger_id
                             AND gps1.closing_status = ''O''
                             AND gps1.application_id = 101))',
      p_title                  => 'LATEST_OPEN_PERIOD',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Latest open period in GL_LEDGERS is incorrect and is not same as the actual latest open period.',
      p_solution               => 'Update GL_LEDGERS table as below for each ledger with issue and perform commit:

update GL_LEDGERS
set latest_opened_period_name = ''&period_name''
where ledger_id = &ledger_id;

commit;

Solution is in line with Note: [1410184/KB784126]',
      p_success_msg            => 'Latest open period in GL_LEDGERS is correct and is same as the actual latest open period.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: LATEST_OPEN_PERIOD');



debug('begin add_signature: Duplicate GL Code Combinations');
   l_info('##MASK##ORACLE USERNAME'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3138',
      p_sig_id                 => 'Duplicate GL Code Combinations',
      p_sig_sql                => 'SELECT cck.concatenated_segments "Account Combination",
       cck.code_combination_id "Code Combination ID",
       cck.chart_of_accounts_id "Chart of Accounts ID",
       cck.template_id "Summary Template ID",
       cck.last_update_date "Last Updated on",
       ffu.user_name "Oracle Username"
  FROM gl_code_combinations_kfv cck,
       fnd_user ffu
 WHERE ffu.user_id = cck.last_updated_by
   AND (cck.concatenated_segments,
        cck.chart_of_accounts_id,
        NVL(cck.template_id, -99)) IN
     (SELECT cck.concatenated_segments,
             cck.chart_of_accounts_id,
             NVL(cck.template_id, -99)
        FROM gl_code_combinations_kfv cck
        GROUP BY cck.concatenated_segments,
             cck.chart_of_accounts_id,
             NVL(cck.template_id, -99)
      HAVING COUNT(*) >1)
 ORDER BY cck.concatenated_segments,
       cck.last_update_date',
      p_title                  => 'Duplicate GL Code Combinations',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are duplicate rows found in the GL_CODE_COMBINATIONS table.',
      p_solution               => '<ul><li>Please report this issue to Oracle Support Services providing the output of this report. </li>
<li>[1068370.6] GL: Duplicates in GL_CODE_COMBINATIONS Table.</li></ul>',
      p_success_msg            => 'No duplicate rows found in the GL_CODE_COMBINATIONS table.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: Duplicate GL Code Combinations');



debug('begin add_signature: MU_BALANCES-VER-JOURNALS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23016',
      p_sig_id                 => 'MU_BALANCES-VER-JOURNALS',
      p_sig_sql                => 'SELECT T.ledger_id,
  T.code_combination_id code_combination_id,
  T.period_name period_name,
  T.currency_code currency_code,
   SUM(NVL(T.BALANCES_CR, 0)) BALANCES_CR,
   SUM(NVL(T.balances_dr, 0)) balances_dr,
   SUM(NVL(T.lines_cr, 0)) lines_cr,
   SUM(NVL(T.lines_dr, 0)) lines_dr
FROM
  (SELECT led.ledger_id,
    l.code_combination_id code_combination_id,
    h.period_name period_name,
    led.currency_code currency_code,
    0 BALANCES_CR,
    0 balances_dr,
    SUM(NVL(l.accounted_cr, 0)) lines_cr,
    SUM(NVL(l.accounted_dr, 0)) lines_dr
  FROM gl.gl_je_headers h ,
    gl.gl_je_lines l ,
    GL_CODE_COMBINATIONS_KFV CC ,
    GL_LEDGERS LED,
    GL.GL_DATE_PERIOD_MAP gpm
  WHERE h.period_name                          =gpm.period_name
  AND to_date(gpm.accounting_date, ''DD-MON-YY'')= to_date(sysdate, ''DD-MON-YY'')
  AND gpm.period_set_name                      =led.period_set_name
  AND led.complete_flag                        =''Y''
  AND led.FIRST_LEDGER_PERIOD_NAME            IS NOT NULL
  AND l.code_combination_id                    = CC.CODE_COMBINATION_ID
  AND h.ledger_id                              =led.ledger_id
  AND h.je_header_id                           = l.je_header_id
  AND h.currency_code                         != ''STAT''
  AND H.STATUS                                 = ''P''
  AND H.ACTUAL_FLAG                            =''A''
  GROUP BY led.ledger_id,
    l.code_combination_id,
    h.period_name,
    led.currency_code
  UNION ALL
  SELECT led.ledger_id,
    b.code_combination_id code_combination_id,
    b.period_name period_name,
    b.currency_code currency_code,
    NVL(B.PERIOD_NET_CR, 0) BALANCES_CR,
    NVL(b.period_net_dr, 0) balances_dr,
    0 lines_cr,
    0 lines_dr
  FROM GL.GL_BALANCES B,
    GL_CODE_COMBINATIONS_KFV CC ,
    GL_LEDGERS LED,
    GL.GL_DATE_PERIOD_MAP gpm
  WHERE b.period_name                          =gpm.period_name
  AND to_date(gpm.accounting_date, ''DD-MON-YY'')= to_date(sysdate, ''DD-MON-YY'')
  AND gpm.period_set_name                      =led.period_set_name
  AND led.complete_flag                        =''Y''
  AND led.FIRST_LEDGER_PERIOD_NAME            IS NOT NULL
  AND b.ledger_id                              = led.ledger_id
  AND b.actual_flag                            = ''A''
  AND b.currency_code                         != ''STAT''
  AND b.currency_code                          = led.CURRENCY_CODE
  AND b.translated_flag                       IS NULL
  AND b.template_id                           IS NULL
  AND CC.CODE_COMBINATION_ID                   =B.CODE_COMBINATION_ID
   AND (NVL(B.PERIOD_NET_CR, 0)                <>0
  OR NVL(B.PERIOD_NET_DR, 0)                  <>0)
  ) T
GROUP BY T.ledger_id,
  T.code_combination_id,
 T.period_name ,
  T.currency_code   
HAVING SUM(NVL(T.balances_cr,0)) <> SUM(NVL(T.lines_cr,0))
OR SUM(NVL(T.balances_dr,0))     <> SUM(NVL(T.lines_dr,0))
',
      p_title                  => 'Balances Do Not Match Posted Journals',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Balance corruption: The sum of posted transactions in gl_je_lines is not the same as the balance stored in gl_balance.',
      p_solution               => 'Refer to MOS Notes to resolve the balances issue. <br>
 [2745665/KB771758] R12: GLBALFIX Auto Installation Script and Concurrent Program "General Ledger - Automated Balance Fix" to Rectify Balance Corruptions. <br> [11137202] GLBALFIX: GL Balances Corruption Datafix - Primary Note.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: MU_BALANCES-VER-JOURNALS');



debug('begin add_signature: MU_BALANCES_1');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23018',
      p_sig_id                 => 'MU_BALANCES_1',
      p_sig_sql                => 'select a.ledger_id ledger_id, a.period period_name, 
a.currency currency, a.end_dr total_debit, a.end_cr total_credit
 from (SELECT  gl.ledger_id ledger_id
, max(gpm.period_name) period
, gb.currency_code currency 
, sum(gb.begin_balance_dr) + sum(period_net_dr) end_dr
, sum(gb.begin_balance_cr) + sum(period_net_cr) end_cr
FROM gl_balances gb, GL.GL_DATE_PERIOD_MAP gpm, gl_ledgers gl
WHERE gb.ledger_id=gl.ledger_id 
and gb.period_name=gpm.period_name
and to_date(gpm.accounting_date, ''DD-MON-YY'')= to_date(sysdate, ''DD-MON-YY'')
AND gpm.period_set_name= gl.period_set_name and gl.complete_flag=''Y'' and gl.FIRST_LEDGER_PERIOD_NAME is not null
AND gb.actual_flag = ''A''
AND gb.template_id is null
AND (gb.translated_flag <> ''Y'' or gb.translated_flag is null)
AND gb.currency_code != ''STAT'' 
group by gl.ledger_id,  gb.translated_flag ,gb.currency_code  
having sum(gb.begin_balance_dr) + sum(period_net_dr)<>sum(gb.begin_balance_cr) + sum(period_net_cr)) a',
      p_title                  => 'Total Debit/Credit Balances Do Not Match',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The total debit balances do not match the total credit balance',
      p_solution               => 'Refer to [2745665/KB771758] GLBALFIX Auto Installation Script and Concurrent Program "General Ledger - Automated Balance Fix" to Rectify Balance Corruptions',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: MU_BALANCES_1');



debug('begin add_signature: MU_BAL_JOURN_PREV');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23020',
      p_sig_id                 => 'MU_BAL_JOURN_PREV',
      p_sig_sql                => 'SELECT T.ledger_id,
T.code_combination_id code_combination_id,
T.period_name period_name,
T.currency_code currency_code,
SUM(NVL(T.BALANCES_CR, 0)) BALANCES_CR,
SUM(NVL(T.balances_dr, 0)) balances_dr,
SUM(NVL(T.lines_cr, 0)) lines_cr,
SUM(NVL(T.lines_dr, 0)) lines_dr
FROM
(SELECT led.ledger_id,
l.code_combination_id code_combination_id,
h.period_name period_name,
led.currency_code currency_code,
0 BALANCES_CR,
0 balances_dr,
SUM(NVL(l.accounted_cr, 0)) lines_cr,
SUM(NVL(l.accounted_dr, 0)) lines_dr
FROM gl.gl_je_headers h ,
gl.gl_je_lines l ,
GL_CODE_COMBINATIONS_KFV CC ,
GL_LEDGERS LED,
GL.GL_DATE_PERIOD_MAP gpm
WHERE h.period_name =gpm.period_name
AND to_date(gpm.accounting_date, ''DD-MON-YY'')= to_date(sysdate-30, ''DD-MON-YY'')
AND gpm.period_set_name =led.period_set_name
AND led.complete_flag =''Y''
AND led.FIRST_LEDGER_PERIOD_NAME IS NOT NULL
AND l.code_combination_id = CC.CODE_COMBINATION_ID
AND h.ledger_id =led.ledger_id
AND h.je_header_id = l.je_header_id
AND h.currency_code != ''STAT''
AND H.STATUS = ''P''
AND H.ACTUAL_FLAG                            =''A''
GROUP BY led.ledger_id,
l.code_combination_id,
h.period_name,
led.currency_code
UNION ALL
SELECT led.ledger_id,
b.code_combination_id code_combination_id,
b.period_name period_name,
b.currency_code currency_code,
NVL(B.PERIOD_NET_CR, 0) BALANCES_CR,
NVL(b.period_net_dr, 0) balances_dr,
0 lines_cr,
0 lines_dr
FROM GL.GL_BALANCES B,
GL_CODE_COMBINATIONS_KFV CC ,
GL_LEDGERS LED,
GL.GL_DATE_PERIOD_MAP gpm
WHERE b.period_name =gpm.period_name
AND to_date(gpm.accounting_date, ''DD-MON-YY'')= to_date(sysdate-30, ''DD-MON-YY'')
AND gpm.period_set_name =led.period_set_name
AND led.complete_flag =''Y''
AND led.FIRST_LEDGER_PERIOD_NAME IS NOT NULL
AND b.ledger_id = led.ledger_id
AND b.actual_flag = ''A''
AND b.currency_code != ''STAT''
AND b.currency_code = led.CURRENCY_CODE
AND b.translated_flag IS NULL
AND b.template_id IS NULL
AND CC.CODE_COMBINATION_ID =B.CODE_COMBINATION_ID
AND (NVL(B.PERIOD_NET_CR, 0) <>0
OR NVL(B.PERIOD_NET_DR, 0) <>0)
) T
GROUP BY T.ledger_id,
T.code_combination_id,
T.period_name ,
T.currency_code
HAVING SUM(NVL(T.balances_cr,0)) <> SUM(NVL(T.lines_cr,0))
OR SUM(NVL(T.balances_dr,0)) <> SUM(NVL(T.lines_dr,0))
',
      p_title                  => 'Balances Do Not Match Posted Journals for Previous Period',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Balance corruption: The sum of posted transactions in gl_je_lines is not the same as the balance stored in gl_balance.',
      p_solution               => 'Refer to :
[2745665/KB771758] R12: GLBALFIX Auto Installation Script and Concurrent Program "General Ledger - Automated Balance Fix" to Rectify Balance Corruptions. <br> [11137202] GLBALFIX: GL Balances Corruption Datafix - Primary Note. ',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
