debug('begin add_signature: SUBLEDGER_LEVEL_SECONDARY_LEDGER_DUPLICATE_TRANSFER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12321',
      p_sig_id                 => 'SUBLEDGER_LEVEL_SECONDARY_LEDGER_DUPLICATE_TRANSFER',
      p_sig_sql                => 'SELECT ledger_name, relationship_type, journal_source, journal_category, user_updatable_flag, create_journal_from_primary
FROM 
(SELECT gllrs.target_ledger_name ledger_name,
       gllrs.relationship_type_code relationship_type,
       glir.je_source_name journal_source,
       glir.je_category_name journal_category,
       glir.user_updatable_flag user_updatable_flag,
       decode(glir.include_flag,''Y'',''Yes'',glir.include_flag) create_journal_from_primary
  FROM gl_je_inclusion_rules glir,
       gl_ledger_relationships gllrs
 WHERE relationship_enabled_flag = ''Y''
   AND relationship_type_code <> ''NONE''
   AND gllrs.gl_je_conversion_set_id = glir.je_rule_set_id
   AND gllrs.relationship_type_code = ''SUBLEDGER''
   AND glir.include_flag = ''Y''
   AND glir.je_source_name IN (
            ''Project Accounting'',''Inventory'',''Purchasing'',''Receivables'',''Cash Management'',''Assets'',''Payables''
        )
GROUP BY
    gllrs.target_ledger_name,
    gllrs.relationship_type_code,
    glir.je_source_name,
    glir.je_category_name,
    glir.user_updatable_flag,
    glir.include_flag)',
      p_title                  => 'Duplicate Subledger Journals Created in Subledger Level Reporting Currency',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transfer Journals to this Secondary Ledger is set to Yes for Sub ledger level secondary ledger which will duplicate the journals by creating the journal once from Sub-ledger and once from Primary ledger during posting.',
      p_solution               => 'Refer [784875/KB741952]  Duplicate Subledger Journals Created in Subledger Level Reporting Currency',
      p_success_msg            => '',
