debug('begin add_signature: MU_BATCH_STATUS_ERROR28');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22987',
      p_sig_id                 => 'MU_BATCH_STATUS_ERROR28',
      p_sig_sql                => ' ( SELECT
            gl.ledger_id ledger_id,
            gl.name ledger_name,
            segment_type_code segment_type_code,
            segment_value segment_value,
            ''Value Missing in gl_ledger_norm_seg_vals'' error_message,
            parent_record_id record_id
        FROM
            gl_ledger_segment_values glsv,
            gl_ledgers gl
        WHERE
            gl.ledger_id = glsv.ledger_id
        MINUS SELECT
            gl.ledger_id,
            gl.name ledger_name,
            segment_type_code segment_type_code,
            segment_value segment_value,
            ''Value Missing in gl_ledger_norm_seg_vals'' error_message,
            record_id record_id
        FROM
            gl_ledger_norm_seg_vals glsv,
            gl_ledgers gl
        WHERE
            gl.ledger_id = glsv.ledger_id
        ) UNION ( SELECT
            gl.ledger_id ledger_id,
            gl.name ledger_name,
            segment_type_code segment_type_code,
            segment_value segment_value,
            ''Value Missing in gl_ledger_segment_values'' error_message,
            record_id record_id
        FROM
            gl_ledger_norm_seg_vals glsv,
            gl_ledgers gl
        WHERE
            gl.ledger_id = glsv.ledger_id
        MINUS SELECT
            gl.ledger_id ledger_id,
            gl.name ledger_name,
            segment_type_code segment_type_code,
            segment_value segment_value,
            ''Value Missing in gl_ledger_segment_values'' error_message,
            parent_record_id record_id
        FROM
            gl_ledger_segment_values glsv,
            gl_ledgers gl
        WHERE
            gl.ledger_id = glsv.ledger_id
        )
        ORDER BY
    1,
    3,
    5 ASC',
      p_title                  => 'Journal Posting Failed with Error28',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Identified journal lines with invalid balancing and management segment value which causing Error28 while posting.',
      p_solution               => '<br> A data fix will be required from Oracle Support.  
Refer to [2521761/KB649400] Monitoring Services: GLPPOS:Posting Ends with "Error28 - Showing invalid balancing or management segment value for the ledger"',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
