debug('begin add_signature: MU_BATCH_STATUS_ERROR3');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22990',
      p_sig_id                 => 'MU_BATCH_STATUS_ERROR3',
      p_sig_sql                => '        SELECT DISTINCT
            ledger_id ledger_id,
            b_name batch_name,
            h_name header_name,
            b_status batch_status,
            h_status header_status,
            l_status line_status
        FROM
            (
                WITH ledger AS (
                    SELECT UNIQUE
                        gpm.period_name,
                        gps.closing_status,
                        led.ledger_id
                    FROM
                        gl_ledgers led,
                        gl.gl_date_period_map gpm,
                        gl_period_statuses gps
                    WHERE
                        EXTRACT(YEAR FROM gpm.accounting_date) = EXTRACT(YEAR FROM SYSDATE)
                    AND
                        gpm.period_set_name = led.period_set_name
                    AND
                        gpm.period_type = led.accounted_period_type
                    AND
                        led.complete_flag = ''Y''
                    AND
                        led.first_ledger_period_name IS NOT NULL
                    AND
                        gps.ledger_id = led.ledger_id
                    AND
                        gpm.period_name = gps.period_name
                    AND
                        gps.application_id = 101
                    AND
                        gps.closing_status IN (
                            ''C'',''O'',''P'',''F''
                        )
                ) SELECT
                    jel.ledger_id ledger_id,
                    jeb.name b_name,
                    jeh.name h_name,
                    jeb.status b_status,
                    jeh.status h_status,
                    jel.status l_status
                FROM
                    gl_je_lines jel,
                    gl_je_headers jeh,
                    gl_je_batches jeb,
                    ledger led
                WHERE
                    jeh.ledger_id = led.ledger_id
                AND
                    jeh.je_header_id = jel.je_header_id
                AND
                    jeb.je_batch_id = jeh.je_batch_id
                AND
                    jel.period_name = led.period_name
                AND
                    jeh.status = ''P''
                AND
                    jel.status = ''P''
                AND
                    jeb.status = ''E''
            )',
      p_title                  => 'Posting Program Is Failing for Several Batches with Error3',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Identified journals with incorrect batch status(E) where all journal lines posted successfully(Line Status = P).',
      p_solution               => 'A data fix will be required from Oracle Support.
Refer to [2481368/KB451590] GLPPOS:Posting Ends with " Error3 - Showing no journal entries" (Doc 2481368.1)',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: MU_BATCH_STATUS_ERROR3');



