debug('begin add_signature: MU_BC_PERIOD_MAP_S_ROWS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23017',
      p_sig_id                 => 'MU_BC_PERIOD_MAP_S_ROWS',
      p_sig_sql                => 'select ledger_id ledger_id ,
period_name period_name,
name name, s_rows s_rows from
(
WITH ledger AS
  (SELECT UNIQUE gpm.period_name,
    gps.closing_status,
    led.*
  FROM gl_ledgers led,
    GL.GL_DATE_PERIOD_MAP gpm,
    gl_period_statuses gps
  WHERE extract(YEAR FROM gpm.accounting_date)= extract(YEAR FROM sysdate )
  AND gpm.period_set_name                     =led.period_set_name
  AND gpm.period_type                         =led.accounted_period_type
  AND led.complete_flag                       =''Y''
  AND led.FIRST_LEDGER_PERIOD_NAME           IS NOT NULL
  AND led.enable_budgetary_control_flag=''Y''
  AND gps.ledger_id                           =led.ledger_id
  AND gpm.period_name                         =gps.period_name
  AND gps.application_id                      =101
  AND gps.closing_status                     IN (''C'', ''O'',''P'',''F'')
  )
SELECT DISTINCT led.ledger_id, led.period_name, led.name ,''No S Rows exists in gl_bc_period_map Table'' s_rows
FROM gl_period_statuses gps2,
  gl_period_statuses gps1,
  ledger led
WHERE gps1.ledger_id     = led.ledger_id
AND gps1.application_id  = 101
AND gps1.closing_status != ''N''
AND gps2.ledger_id       = led.ledger_id
AND gps2.application_id  = 101
AND gps2.period_year     = gps1.period_year
AND gps2.period_num      =
  (SELECT MIN( gps.period_num )
  FROM gl_period_statuses gps
  WHERE gps.ledger_id    = led.ledger_id
  AND gps.application_id = 101
  AND gps.period_year    = gps2.period_year
  )
AND NOT EXISTS
  (SELECT ''1''
  FROM gl_bc_period_map gbpm
  WHERE gbpm.ledger_id             = led.ledger_id
  AND gbpm.actual_flag             = ''A''
  AND gbpm.boundary_code           = ''S''
  AND gbpm.transaction_period_name = gps1.period_name
  ) )',
      p_title                  => 'Missing S Rows in GL_BC_Period_Map Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Special S rows are not inserted in gl_bc_period_map table for non federal customers resulting in inaccurate calculation of funds available. ',
      p_solution               => 'Refer to [1115496/KB712851] Budget Transactions Fail Funds Checking with ''This detail transaction causes a summary account to fail funds check'' Even Though Sufficient Funds Exist',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: MU_BC_PERIOD_MAP_S_ROWS');



debug('begin add_signature: MU_CONSOL_CONV_RATE_EC03');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23024',
      p_sig_id                 => 'MU_CONSOL_CONV_RATE_EC03',
      p_sig_sql                => 'SELECT
            gjl.ledger_id ledger_id,
            gjl.je_header_id je_header_id,
            gjl.status status,
            gjl.je_line_num je_line_num,
            gjl.code_combination_id code_combination_id,
            gjl.period_name period_name
        FROM
            gl_je_lines gjl,
            gl_ledgers gl
        WHERE
            1 = 1
            AND   gjl.ledger_id = gl.ledger_id
            AND   gl.consolidation_ledger_flag = ''Y''
            AND   (
                (
                    gjl.accounted_dr IS NULL
                    AND   gjl.entered_dr IS NOT NULL
                )
                OR    (
                    gjl.accounted_cr IS NULL
                    AND   gjl.entered_cr IS NOT NULL
                )
            )
AND rownum = 1',
      p_title                  => 'Journal Import Ends with Error EC03 While Running Consolidation',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Should not pair null entered/accounted amount with zero or non-zero corresponding entered/accounted amount.Should both be either zero/value or null. <br>
Only the first row is displayed in the output due to a maximum threshold defined. But, there could be more transactions having this problem.',
      p_solution               => 'A data fix will be required from Oracle Support.
Refer to [402563/KB777201] GLLEZL Cannot Complete Consolidation Due To EC03 Error.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
