debug('begin add_signature: MU_CONSOL_DUPLICATE_EU02');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22988',
      p_sig_id                 => 'MU_CONSOL_DUPLICATE_EU02',
      p_sig_sql                => 'SELECT
    name name,
    je_line_num je_line_num,
    ledger_id ledger_id,
    period_name period_name,
    accounted_dr accounted_dr,
    accounted_cr accounted_cr
FROM
    (
        SELECT
            gjh.name name,
            gjl.je_line_num je_line_num,
            gjl.ledger_id ledger_id,
            gjl.period_name period_name,
            gjl.accounted_dr accounted_dr,
            gjl.accounted_cr accounted_cr,
            COUNT(*) OVER(
                PARTITION BY gjl.je_line_num,
                gjl.ledger_id,
                gjl.period_name,
                gjl.accounted_dr,
                gjl.accounted_cr
            ) c_count
        FROM
            gl_je_lines gjl,
            gl_ledgers gl,
            gl_je_headers gjh
        WHERE
            1 = 1
            AND   gjl.ledger_id = gl.ledger_id
            AND   gl.consolidation_ledger_flag = ''Y''
            AND   gjh.je_header_id = gjl.je_header_id
            AND   gjh.default_effective_date > sysdate - 30
    ) a
WHERE
    a.c_count > 1
ORDER BY
    name',
      p_title                  => 'Journal Import Failed with Error EU02 While Running Consolidation',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Identified the Duplicate data in the table gl_cons_segment_map for Consolidation ledger',
      p_solution               => 'Please note that changing the value set of a Chart of Accounts which is already assigned to a Set of Books is strictly not supported.
<br> 
Refer to [1068100/KB740871] Duplicate Data In Consolidation, EU02 in Journal Import ',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_CONSOL_DUPLICATE_EU02');



