debug('begin add_signature: MU_FAHRCS_SPECIAL_CHARACTERS_SEG_DESCRIPTION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22997',
      p_sig_id                 => 'MU_FAHRCS_SPECIAL_CHARACTERS_SEG_DESCRIPTION',
      p_sig_sql                => 'SELECT
    ledger_name ledger_name,
    value_set_name value_set_name,
    flex_value flex_value,
    description description,
    error_message  error_message
FROM
    ( 
        SELECT
            lgr.name ledger_name,
            fvs.flex_value_set_name value_set_name,
            val.flex_value flex_value,
            val.description description,
            ''Leading Space detected'' error_message
        FROM
            gl_ledgers lgr,
            fnd_id_flex_segments flex_seg,
            fnd_flex_value_sets fvs,
            fnd_flex_values_vl val
        WHERE
            lgr.chart_of_accounts_id = flex_seg.id_flex_num
        AND
            flex_seg.application_id = 101
        AND
            flex_seg.id_flex_code = ''GL#''
        AND
            flex_seg.flex_value_set_id = fvs.flex_value_set_id
        AND
            fvs.flex_value_set_id = val.flex_value_set_id
        AND
            val.description LIKE '' %''
        UNION SELECT
            lgr.name ledger_name,
            fvs.flex_value_set_name value_set_name,
            val.flex_value flex_value,
            val.description description,
            ''Trailing Space detected'' error_message
        FROM
            gl_ledgers lgr,
            fnd_id_flex_segments flex_seg,
            fnd_flex_value_sets fvs,
            fnd_flex_values_vl val
        WHERE
            lgr.chart_of_accounts_id = flex_seg.id_flex_num
        AND
            flex_seg.application_id = 101
        AND
            flex_seg.id_flex_code = ''GL#''
        AND
            flex_seg.flex_value_set_id = fvs.flex_value_set_id
        AND
            fvs.flex_value_set_id = val.flex_value_set_id
        AND
            val.description LIKE ''% ''
        UNION SELECT
            lgr.name ledger_name,
            fvs.flex_value_set_name value_set_name,
            val.flex_value flex_value,
            val.description description,
            ''Contains a CHARACTER NOT Allowed'' error_message
        FROM
            gl_ledgers lgr,
            fnd_id_flex_segments flex_seg,
            fnd_flex_value_sets fvs,
            fnd_flex_values_vl val
        WHERE
            lgr.chart_of_accounts_id = flex_seg.id_flex_num
        AND
            flex_seg.application_id = 101
        AND
            flex_seg.id_flex_code = ''GL#''
        AND
            flex_seg.flex_value_set_id = fvs.flex_value_set_id
        AND
            fvs.flex_value_set_id = val.flex_value_set_id
        AND (
                val.description LIKE ''%"%''
            OR
                val.description LIKE ''%[%''
            OR
                val.description LIKE ''%]%''
        ) UNION SELECT
            lgr.name ledger_name,
            fvs.flex_value_set_name value_set_name,
            val.flex_value flex_value,
            val.description description,
            ''New Line CHARACTER detected'' error_message
        FROM
            gl_ledgers lgr,
            fnd_id_flex_segments flex_seg,
            fnd_flex_value_sets fvs,
            fnd_flex_values_vl val
        WHERE
            lgr.chart_of_accounts_id = flex_seg.id_flex_num
        AND
            flex_seg.application_id = 101
        AND
            flex_seg.id_flex_code = ''GL#''
        AND
            flex_seg.flex_value_set_id = fvs.flex_value_set_id
        AND
            fvs.flex_value_set_id = val.flex_value_set_id
        AND
            val.description LIKE ''%''
             ||  CHR(9)
             ||  ''%''
     
)
WHERE
    1 <= (
        SELECT
            COUNT(1)
        FROM
            ad_applied_patches
        WHERE
            patch_name = ''19795559''
    )
and rownum = 1',
      p_title                  => 'FAHRCS Special Characters in Segment Descriptions',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Only the first row is displayed in the output due to a maximum threshold defined. But, there could be more transactions having this problem. <br>
A correction to these invalid row(s) is required to use  Fusion Accounting Hub.',
      p_solution               => 'Refer to [2076459/KB76480] FAHRCS: Transfer EBS Setups and Balances to Accounting Hub Reporting Cloud Service Errors Reporting Special Characters in Segment Descriptions',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_FAHRCS_SPECIAL_CHARACTERS_SEG_DESCRIPTION');



debug('begin add_signature: MU_GL_DUPLICATE_SEGMENT_VALUES_V2');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23023',
      p_sig_id                 => 'MU_GL_DUPLICATE_SEGMENT_VALUES_V2',
      p_sig_sql                => 'SELECT
    gl.name ledger_name,
    gnv.segment_value,
    COUNT(1)  duplicate_segment_values
FROM
    gl_ledger_segment_values   gnv,
    gl_ledgers                 gl
WHERE
    gnv.ledger_id = gl.ledger_id
GROUP BY
    gl.name,
    gnv.segment_value
HAVING
    COUNT(1) > 1
Union all
SELECT
    gl.name ledger_name,
    gnvs.segment_value,
    COUNT(1)  duplicate_segment_values
FROM
    gl_ledger_norm_seg_vals  gnvs,
    gl_ledgers                 gl
WHERE
    gnvs.ledger_id = gl.ledger_id
GROUP BY
    gl.name,
    gnvs.segment_value
HAVING
    COUNT(1) > 1',
      p_title                  => 'Duplicate Segment Values Assigned to the Ledger',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Rows returned by the query indicate duplicate assignments.  A data fix may be required to remove the duplicate records.',
