  add_signature(
      p_sig_repo_id            => '23022',
      p_sig_id                 => 'MU_JE_DIFF_PERIOD',
      p_sig_sql                => 'SELECT DISTINCT jh.ledger_id,
jb.name batch_name,
jb.je_batch_id,
