debug('begin add_signature: MU_JE_DIFF_STATUS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22985',
      p_sig_id                 => 'MU_JE_DIFF_STATUS',
      p_sig_sql                => 'WITH ledger AS
  (SELECT UNIQUE gpm.period_name,
    gps.closing_status,
    led.*
  FROM gl_ledgers led,
    GL.GL_DATE_PERIOD_MAP gpm,
    gl_period_statuses gps
  WHERE extract(YEAR FROM gpm.accounting_date)= extract(YEAR FROM sysdate )
  AND gpm.period_set_name                     =led.period_set_name
  AND gpm.period_type                         =led.accounted_period_type
  AND led.complete_flag                       =''Y''
  AND led.FIRST_LEDGER_PERIOD_NAME           IS NOT NULL
  AND gps.ledger_id                           =led.ledger_id
  AND gpm.period_name                         =gps.period_name
  AND gps.application_id                      =101
  AND gps.closing_status                     IN (''C'', ''O'',''P'', ''F'')
  )
SELECT jeb.je_batch_id ,
  jeb.name b_name,
  jel.je_header_id,
  jeh.name h_name,
  jeh.ledger_id h_ledger_id,
  jeh.period_name h_period_name,
  jeb.status b_status,
  jeh.status h_status,
  jel.status l_status
FROM gl_je_lines jel,
  gl_je_headers jeh,
  gl_je_batches jeb,
  ledger led
WHERE jeh.ledger_id                     =led.ledger_id
AND jeh.je_header_id                    = jel.je_header_id
AND jeb.je_batch_id                     = jeh.je_batch_id
AND jel.period_name                     =led.period_name
AND (DECODE(jeh.status, ''P'', ''P'', ''U'') != DECODE(jel.status, ''P'', ''P'', ''U'')
OR (DECODE(jeb.status, ''P'', ''P'', ''U'')  != DECODE(jel.status, ''P'', ''P'', ''U'')) )',
      p_title                  => 'Posted Status for Journal Lines Do Not Match the Header',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The posted status for one of the Journal lines doesn''t match the information at Journal batch or header level.',
      p_solution               => 'Refer to:
[2745665/KB771758] R12: GLBALFIX Auto Installation Script and Concurrent Program "General Ledger - Automated Balance Fix" to Rectify Balance Corruptions. <br>
