debug('begin add_signature: MU_JOURNAL_APPROVAL_INPROCESS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23004',
      p_sig_id                 => 'MU_JOURNAL_APPROVAL_INPROCESS',
      p_sig_sql                => 'SELECT GJB.JE_BATCH_ID JE_BATCH_ID
, GJB.NAME NAME
, GJB.STATUS STATUS
, GJB.DEFAULT_PERIOD_NAME PERIOD_NAME
, GJB.APPROVAL_STATUS_CODE APPROVAL_STATUS_CODE
, GJH.LEDGER_ID LEDGER_ID
FROM GL.GL_JE_BATCHES GJB, GL.GL_JE_HEADERS GJH
WHERE GJB.JE_BATCH_ID = GJH.JE_BATCH_ID
AND GJB.STATUS <> ''P''
AND GJB.APPROVAL_STATUS_CODE = ''I''
AND (GJB.CREATION_DATE >= SYSDATE - 180 AND GJB.CREATION_DATE <= SYSDATE - 7)
and rownum = 1
',
      p_title                  => 'Journal Batch(es) Stuck "In Process" status During Approval',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Journal Approval Workflow is Stuck with Batch Approval Status "In Process" Can not Delete, Modify or Approve it. <br>
Only the first row is displayed in the output due to a maximum threshold defined. But, there could be more transactions having this problem.',
      p_solution               => 'In Process status does not mean stuck. The workflow can still be active. Refer following note for troubleshooting Journal Approval stuck in process:<br>
[415875/KB794059] How to Restart Journal Approval Workflow to Resubmit a Batch "In Process" <br>
If the issue is that the journal is stuck at approval (APPROVAL_STATUS_CODE = I) then please follow the steps from [161382/KB753659] and if the issue is not solved, then please provide the below results in excel sheet with visible column headers, for review: 

a) select je_batch_id, default_period_name
from gl_je_batches
where name like ''&YOUR_BATCH_NAME%'';

b) select b.approval_status_code, b.status, b.budgetary_control_status, b.posted_date,
  h.je_header_id, h.status, h.posted_date,h.accrual_rev_status, l.gl_sl_link_id
from gl_je_headers h, gl_je_batches b, gl_je_lines l
where b.je_batch_id = &batch_id
and b.je_batch_id=h.je_batch_id
and h.je_header_id=l.je_header_id;
 <br>

If the issue persists please raise a Service Request providing the output if this report.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_JOURNAL_APPROVAL_INPROCESS');



debug('begin add_signature: MU_JOURNAL_IMPORT_EC12');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23013',
      p_sig_id                 => 'MU_JOURNAL_IMPORT_EC12',
      p_sig_sql                => 'select 
a.status status
, a.ledger_id ledger_id
, a.period_name period_name
, a.ccid_and_or_combination ccid_and_or_combination
, a.actual_flag actual_flag
, a.group_id group_id
from
(select 
gi.status status
, decode(gi.ledger_id, -1, gi.set_of_books_id, gi.ledger_id) ledger_id
, gp.period_name period_name
, decode (gi.code_combination_id, NULL, gi.segment1||''.''||gi.segment2||''.''||gi.segment3||''.''||gi.segment4||''.''||gi.segment5||''.''||gi.segment6||''.''||gi.segment7||''.''||gi.segment8||''.''||gi.segment9||''.''||gi.segment10, gi.code_combination_id ||'' (''|| gcc.concatenated_segments ||'')'') ccid_and_or_combination
, gi.actual_flag actual_flag
, gi.group_id group_id
from
gl_interface gi,
gl_ledgers gll,
gl_code_combinations_kfv gcc,
gl_periods GP
where decode(gi.ledger_id, -1, gi.set_of_books_id, gi.ledger_id) = gll.ledger_id
AND gp.period_set_name = gll.period_set_name 
and gp.period_type = gll.accounted_period_type
-- AND gll.period_set_name = ''Accounting''
and gi.accounting_date between gp.start_date and gp.end_date
and gi.code_combination_id = gcc.code_combination_id(+)
and gi.status like ''%EC12%''
and rownum < 2) a
where rownum = 1',
