debug('begin add_signature: MU_JOURNAL_LEAD_TRAIL_SPACES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23008',
      p_sig_id                 => 'MU_JOURNAL_LEAD_TRAIL_SPACES',
      p_sig_sql                => 'select a.Batch_Name Batch_Name,
a.Batch_Description Batch_Description,
a.Ledger_ID Ledger_ID,
a.period_name period_name,
a.je_batch_id je_batch_id
from
(select distinct REGEXP_REPLACE(REGEXP_REPLACE(gb.name, ''\s+$'', ''~''), ''^[ \t]+'', ''~'') Batch_Name
, REGEXP_REPLACE(REGEXP_REPLACE(gb.description, ''\s+$'', ''~''), ''^[ \t]+'', ''~'') Batch_Description
, gb.je_batch_id je_batch_id
, gh.ledger_id Ledger_ID
, gh.period_name period_name
from gl_je_batches gb,
gl_je_headers gh
where gb.je_batch_id = gh.je_batch_id
and (gb.description <> trim(gb.description) OR gb.name <> trim(gb.name)
)) a
where rownum =1
',
      p_title                  => 'Journal Batch Name Has Leading and/or Trailing Spaces',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The above data contains leading or trailing spaces in the Journal Batch Name and/or Description. Values with spaces are shown between tilde (~). <br>
Only the first row is displayed in the output due to a maximum threshold defined. But, there could be more transactions having this problem.
<br>
GLXJEENT: Journal Reversal gives Error FRM-40654: Record has been updated. Requery block to see change',
