debug('begin add_signature: MU_UNBALANCED_RECONCILIATION_ACCOUNTED_AMOUNT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22991',
      p_sig_id                 => 'MU_UNBALANCED_RECONCILIATION_ACCOUNTED_AMOUNT',
      p_sig_sql                => 'Select 
a.ledger_id ledger_id, 
a.ledger_name ledger_name,
a.Sum_CR Sum_CR,
a.Sum_DR Sum_DR,
a.Reconcilation_identifier Reconcilation_identifier
from
((SELECT l.ledger_id ledger_id, 
le.Name ledger_name,
SUM(nvl(entered_cr,   0))Sum_CR,
SUM(nvl(entered_dr,   0)) Sum_DR,
jgzz_recon_id Reconcilation_identifier
FROM gl_je_lines l,
gl_je_lines_recon r,
gl_ledgers le
WHERE l.je_header_id = r.je_header_id
AND l.je_line_num = r.je_line_num
AND le.ledger_id = l.Ledger_id
AND jgzz_recon_status = ''R''
GROUP BY r.jgzz_recon_id,l.ledger_id, le.Name
HAVING SUM(nvl(entered_cr,   0))<> SUM(nvl(entered_dr,   0))) 
UNION
(SELECT l.ledger_id ledger_id, 
le.Name ledger_name,
jgzz_recon_id Reconcilation_identifier,
SUM(nvl(accounted_cr, 0))Sum_CR,
SUM(nvl(accounted_dr, 0)) Sum_DR
FROM gl_je_lines l,
gl_je_lines_recon r,
gl_ledgers le
WHERE l.je_header_id = r.je_header_id
AND l.je_line_num = r.je_line_num
AND le.ledger_id = l.Ledger_id
AND jgzz_recon_status = ''R''
GROUP BY r.jgzz_recon_id,l.ledger_id, le.Name
HAVING SUM(nvl(accounted_cr, 0))<> SUM(nvl(accounted_dr, 0)))) a
',
      p_title                  => 'R12: Gl Reconciliation - Unbalanced Accounted Amounts',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'GL Reconciliation was performed. The reconciliation seems to be unbalanced or missing journal lines were spotted in the problematic reconciliation.',
      p_solution               => 'GL Reconciliation was performed. The reconciliation seems to be unbalanced or missing journal lines were spotted in the problematic reconciliation.<br> 
 1. Please review this document, the patch would help if your case matches the one described:<br> 
[2051900/KB731557] GLXRCENT GLXRCREV Journal Reconciliation/Reverse Reconciliation Forms Do Not Synchronize Totals When Lock Error Occurs<br> 
 2. If the above does not seem to be your case and you would like to correct this data with a data fix, please update the SR and Support will engage appropriately.
<br> 
Refer to [1516180/KB823510] R12: GL Reconciliation - Unbalanced (Datafix) ',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_UNBALANCED_RECONCILIATION_ACCOUNTED_AMOUNT');



