AND TRUNC(sysdate) BETWEEN asg.effective_start_date AND asg.effective_end_date
AND TRUNC(sysdate) BETWEEN sup.effective_start_date AND sup.effective_end_date
AND TRUNC(sysdate) BETWEEN sup.effective_start_date AND sup.effective_end_date
