debug('begin add_signature: MU_SERIAL_INVALID_MARK_IDS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23047',
      p_sig_id                 => 'MU_SERIAL_INVALID_MARK_IDS',
      p_sig_sql                => 'SELECT msn.serial_number SERIAL_NUMBER,
  msn.inventory_item_id ITEM_ID,
  msn.current_organization_id ORG_ID,
  msn.current_subinventory_code SUBINV_CODE
FROM mtl_serial_numbers msn
WHERE(msn.group_mark_id IS NOT NULL
 AND msn.group_mark_id <> -1)
AND msn.group_mark_id <> Nvl(msn.reservation_id,-2)
AND msn.group_mark_id <> Nvl(msn.wip_entity_id,-2)
 AND NOT EXISTS
  (SELECT 1
   FROM mtl_serial_numbers_temp msnt
   WHERE msn.group_mark_id = msnt.transaction_temp_id OR msn.group_mark_id = msnt.group_header_id)
AND NOT EXISTS
  (SELECT 1
   FROM wsh_delivery_details wdd
   WHERE wdd.inv_interfaced_flag <> ''Y''
   AND wdd.released_status IN(''Y'',    ''C'')
   AND wdd.transaction_temp_id IS NOT NULL
   AND msn.group_mark_id = wdd.transaction_temp_id)
AND NOT EXISTS
  (SELECT 1
   FROM wsh_delivery_details wdd
   WHERE wdd.inv_interfaced_flag <> ''Y''
   AND wdd.released_status IN(''Y'',    ''C'')
   AND msn.inventory_item_id = wdd.inventory_item_id
   AND msn.serial_number = wdd.serial_number)
AND NOT EXISTS
  (SELECT 1
   FROM mtl_cycle_count_entries mcce
   WHERE mcce.cycle_count_header_id = msn.group_mark_id
   AND mcce.cycle_count_entry_id = msn.line_mark_id
   AND mcce.entry_status_code IN(1,    2))
and rownum < 2',
      p_title                  => 'Locked Serial Numbers Due to Invalid Mark IDs',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are serial numbers that are locked so other processes cannot use them.',
      p_solution               => 'See the Solution in [1472005/KB472235#aref_section216] - Inventory Standard Datafix Instruction #4: Fixing Marked Serial 
Numbers (MSN), Orphan Pending Serials (MSNT), and Orphan Status 6 Serials',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: MU_SERIAL_INVALID_MARK_IDS');



debug('begin add_signature: MU_SERIAL_NUMBER_LEADING_TRAILING_MSN_1');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23048',
      p_sig_id                 => 'MU_SERIAL_NUMBER_LEADING_TRAILING_MSN_1',
