debug('begin add_signature: EBS_MFG_INV_MU_ORPHAN_SERIAL_NUMBER_TEMP_RECORDS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25792',
      p_sig_id                 => 'EBS_MFG_INV_MU_ORPHAN_SERIAL_NUMBER_TEMP_RECORDS',
      p_sig_sql                => 'SELECT msnt.fm_serial_number, msnt.to_serial_number, msnt.TRANSACTION_TEMP_ID, mmtt.inventory_item_id
FROM mtl_serial_numbers_temp msnt, mtl_material_transactions_temp mmtt
    WHERE   NOT EXISTS (SELECT 1 FROM mtl_material_transactions_temp mmtt
    WHERE  mmtt.transaction_temp_id = msnt.transaction_temp_id)
    AND     NOT EXISTS (SELECT 1 FROM MTL_TRANSACTION_LOTS_TEMP mtlt
    WHERE  mtlt.SERIAL_TRANSACTION_TEMP_ID = msnt.transaction_temp_id)
    AND     NOT EXISTS (SELECT 1 FROM wsh_delivery_details wdd
    WHERE  wdd.transaction_temp_id IS NOT NULL
    AND    wdd.transaction_temp_id = msnt.transaction_temp_id
    AND    wdd.released_status in (''Y'',''C'')
    AND    wdd.inv_interfaced_flag <> ''Y'')
    AND     NOT EXISTS (SELECT 1 FROM rcv_transactions_interface rti
    WHERE  interface_transaction_id = msnt.transaction_temp_id)
AND mmtt.TRANSACTION_TEMP_ID = msnt.TRANSACTION_TEMP_ID',
      p_title                  => 'Locked Serial Numbers Due to Orphan Temporary Serials',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There is one or more orphaned pending serial number without related inventory transactions, deliveries, or receiving transactions using the serial. Orphan pending serials may prevent users from selecting or transacting the listed serial numbers. Keep in mind that the serials listed may not be related to your organization and item because the serial temporary table does not have columns for organization and item.',
      p_solution               => 'See the Solution in [1472005/KB472235#aref_section216] - Inventory Standard Datafix Instruction #4: Fixing Marked Serial
Numbers (MSN), Orphan Pending Serials (MSNT), and Orphan Status 6 Serials',
      p_success_msg            => 'There are no serial numbers locked by orphan serial temporary records. Refer to [1472005/KB472235] for more details.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_INV_MU_ORPHAN_SERIAL_NUMBER_TEMP_RECORDS');



