      p_sig_sql                => 'SELECT l.header_id,
l.line_id
FROM oe_order_lines_all l,
oe_order_headers_all h,
hr_operating_units hou
WHERE h.last_update_date between sysdate-30 and sysdate
AND h.header_id (+) = l.header_id
