debug('begin add_signature: MU_ORDER_MGMT_BOOKED_HDR_BOOKED_LIN_PROGRESSED_WF');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23175',
      p_sig_id                 => 'MU_ORDER_MGMT_BOOKED_HDR_BOOKED_LIN_PROGRESSED_WF',
      p_sig_sql                => 'SELECT
    h.header_id ,
    l.line_id 
FROM
    oe_order_lines_all l,
    oe_order_headers_all h
WHERE
    l.flow_status_code = ''BOOKED''
    AND h.flow_status_code=''BOOKED''
    AND l.header_id = h.header_id
    AND h.last_update_date between sysdate-30 and sysdate
    AND nvl(l.shipped_quantity,0) = 0
    AND l.open_flag = ''Y''
    AND l.shipping_interfaced_flag = ''Y''
    AND EXISTS (
        SELECT
            1
        FROM
            wsh_delivery_details wdd
        WHERE
            wdd.source_line_id = l.line_id
    )
    AND EXISTS (
        SELECT
            1
        FROM
            wf_item_activity_statuses wias,
            wf_process_activities wpa
        WHERE
            item_type = ''OEOL''
            AND item_key = TO_CHAR(l.line_id)
            AND wias.process_activity = wpa.instance_id
            AND wpa.activity_name = ''SHIP_LINE''
            AND wias.activity_status = ''NOTIFIED''
            AND wpa.process_name = ''SHIP_CONFIRM''
    )',
      p_title                  => 'Order(s) and Order Line(s) Stuck As Booked',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Order Line(s) are stuck as Booked not Awaiting Shipping',
      p_solution               => 'For more information regarding this issue, review [2173870/KB749639] for instructions and details.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: MU_ORDER_MGMT_BOOKED_HDR_BOOKED_LIN_PROGRESSED_WF');



