debug('begin add_signature: MU_SALES_ORDER_LINES_NO_INVOICE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23172',
      p_sig_id                 => 'MU_SALES_ORDER_LINES_NO_INVOICE',
      p_sig_sql                => 'SELECT oeh.header_id, oel.line_id, oel.fulfillment_date
   FROM OE_ORDER_LINES_ALL oel,
        OE_ORDER_HEADERS_ALL oeh
   WHERE oeh.header_id=oel.header_id
   AND oel.line_category_code in (''ORDER'', ''RETURN'') 
   AND oel.flow_status_code =''CLOSED''  
   AND oel.open_flag=''N''
   AND oel.cancelled_flag=''N''
   AND Nvl(oel.INVOICE_INTERFACE_STATUS_CODE,''N'') =''YES''
   AND oel.invoiced_quantity IS NOT NULL
   AND oel.fulfillment_date >= (sysdate -7)
   AND not exists(select 1
                from ra_customer_trx_lines_all ral
                where ral.interface_line_context=''ORDER ENTRY''
                  and   ral.line_type = ''LINE''
                   and   ral.sales_order_line IS NOT NULL
                and ral.interface_line_attribute6 = TO_CHAR(oel.line_id))
   AND not exists(select 1
                from ra_interface_lines_all rai
                where rai.interface_line_context=''ORDER ENTRY''
                and rai.line_type = ''LINE''
                and rai.interface_line_attribute6 = TO_CHAR(oel.line_id))
   AND rownum < 2',
      p_title                  => 'Sales Order Lines Shipped but Not Invoiced',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order line(s) that have not been invoiced.  Their Invoice Flag is set to Yes; however, they have not been interfaced nor invoiced.',
      p_solution               => 'Only the first row is displayed in the output due to a maximum threshold defined. But, there could be more transactions having this problem.<br><br>

Please log a service request to get a data fix script to (re)invoice such order lines.  Reference [1951677/KB626852] when logging the SR.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: MU_SALES_ORDER_LINES_NO_INVOICE');



