debug('begin add_signature: MU_AMT_APPLIED_TO_DISCOUNT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22949',
      p_sig_id                 => 'MU_AMT_APPLIED_TO_DISCOUNT',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.source,
          ai.vendor_id,
          ai.vendor_site_id,
          ai.invoice_amount,
          nvl(ai.amount_applicable_to_discount, 0) amount_applicable_to_discount,
          nvl(ai.total_tax_amount, 0) total_tax_amount,
          nvl(ap_invoices_utility_pkg.get_freight_total(ai.invoice_id, ai.org_id),0)
            freight_total,
          nvl(abs(ap_invoices_utility_pkg.get_retained_total(ai.invoice_id, ai.org_id)),0)
            retained_amt,
          nvl(ai.exclude_freight_from_discount, ''N'') exclude_freight_from_discount,
          nvl(ai.disc_is_inv_less_tax_flag, ''N'') disc_is_inv_less_tax_flag,
          nvl(ai.net_of_retainage_flag, ''N'') net_of_retainage_flag,
          nvl((
            SELECT (0 - sum(nvl(amount,0)))
            FROM ap_invoice_distributions_all aid_awt
            WHERE aid_awt.invoice_id = ai.invoice_id
            AND   line_type_lookup_code = ''AWT'')
          , 0) total_awt,
          nvl((
            SELECT nvl(sum(aid_awt.amount),0)
            FROM ap_invoice_distributions_all aid_fre,
                 ap_invoice_distributions_all aid_awt
            WHERE aid_fre.invoice_id = ai.invoice_Id
            AND   aid_fre.invoice_id = aid_awt.invoice_id
            AND   aid_fre.line_type_lookup_code = ''FREIGHT''
            AND   aid_awt.line_type_lookup_code = ''AWT''
            AND   aid_fre.invoice_distribution_id = aid_awt.awt_related_id)
          , 0) awt_on_freight,
       ai.terms_id,
       decode(nvl(ai.payment_status_flag, ''N''),
              ''N'', ''UNPAID'',
              ''P'', ''PARTIALLY PAID'',
              ''Y'', ''PAID'') payment_status,
              atl.discount_percent,
              atl.discount_percent_2,
              atl.discount_percent_3
     FROM ap_invoices_all ai,
          ap_terms_lines atl,
          ( SELECT DISTINCT invoice_id FROM ap_invoice_distributions_all WHERE accounting_date BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3) ) invs
     WHERE atl.term_id = ai.terms_id
     AND   ai.invoice_amount <> 0
     AND   ai.historical_flag is null
     AND   ai.cancelled_date is null
     AND   ai.invoice_type_lookup_code NOT IN (''INTEREST'')
     AND   nvl(ai.amount_applicable_to_discount, 0) <>
             (ai.invoice_amount -
               (CASE
                  WHEN nvl(ai.exclude_freight_from_discount, ''N'') = ''Y'' THEN
                    nvl(ap_invoices_utility_pkg.get_freight_total(
                          ai.invoice_id,
                          ai.org_id),0)
                  ELSE 0
                END) -
               (CASE
                  WHEN nvl(ai.net_of_retainage_flag, ''N'') = ''N'' THEN
                    nvl(abs(ap_invoices_utility_pkg.get_retained_total(
                              ai.invoice_id,
                              ai.org_id))
                      ,0)
                  ELSE 0
                END) -
               (CASE
                  WHEN nvl(ai.disc_is_inv_less_tax_flag, ''N'') = ''Y'' THEN
                    nvl(ai.total_tax_amount, 0)
                  ELSE 0
                END) -
  	     (nvl((
                  SELECT (0 - sum(nvl(amount,0)))
                  FROM ap_invoice_distributions_all aid_awt
                  WHERE aid_awt.invoice_id = ai.invoice_id
                  AND   line_type_lookup_code = ''AWT'')
                , 0)) -
               (CASE
                  WHEN nvl(ai.exclude_freight_from_discount, ''N'') = ''Y'' THEN
  	          nvl((
                      SELECT nvl(sum(aid_awt.Amount),0)
                      FROM ap_invoice_distributions_all aid_fre,
                           ap_invoice_distributions_all aid_awt
                      WHERE aid_fre.invoice_id = ai.invoice_id
                      AND   aid_fre.invoice_id = aid_awt.invoice_id
                      AND   aid_fre.line_type_lookup_code = ''FREIGHT''
                      AND   aid_awt.line_type_lookup_code = ''AWT''
                      AND   aid_fre.invoice_distribution_id = aid_awt.awt_related_id)
                    ,0)
                  ELSE 0
                END))
                     AND   ai.invoice_id = invs.invoice_id
                     AND COALESCE(atl.discount_percent,
                    atl.discount_percent_2,
                      atl.discount_percent_3) is not null
                      AND rownum<1000
order by invoice_id',
      p_title                  => 'AMOUNT_APPLICABLE_TO_DISCOUNT Is Wrong in AP_INVOICES_ALL',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The AMOUNT_APPLICABLE_TO_DISCOUNT column in AP_INVOICES_ALL was incorrectly updated (due to bug 9911823) causing incorrect discounts in AP_PAYMENT_SCHEDULES_ALL and over payment to suppliers.<br/><strong>Impact Area(s): </strong>Invoice Data',
      p_solution               => '<strong>Solution GDF: </strong>17445609</br><strong>Note: </strong>[1410403/KB723936]</br><strong>Script Name: </strong>ap_amt_appl_to_disc_wrng_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1410403/KB723936].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: MU_AMT_APPLIED_TO_DISCOUNT');



debug('begin add_signature: MU_INVOICE_1489862_1');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols as per MGD_243'):= 'corruption_type,
                                      ai.invoice_id,
                                      ai.invoice_date,
                                      ai.org_id,
                                      ai.batch_id,
                                      ail.line_number,
                                      NULL invoice_distribution_id, ''Included tax amount is not null on cancelled invoice'' problem_description';
  add_signature(
      p_sig_repo_id            => '22979',
      p_sig_id                 => 'MU_INVOICE_1489862_1',
      p_sig_sql                => 'select * from (WITH invs AS ( SELECT /*+ materialize */ DISTINCT invoice_id
FROM ap_invoice_distributions_all WHERE accounting_date BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3) ) SELECT /*+ ordered */
                                      ''CAN1'' corruption_type,
                                      ai.invoice_id,
                                      ai.invoice_date,
                                      ai.org_id,
                                      ai.batch_id,
                                      ail.line_number,
                                      NULL invoice_distribution_id, ''Included tax amount is not null on cancelled invoice'' problem_description
                                  FROM
                                      invs,
                                      ap_invoices_all        ai, ap_invoice_lines_all   ail
                                  WHERE
                                      ai.invoice_id = ail.invoice_id
                                      AND ai.cancelled_date IS NOT NULL
                                          AND nvl(ail.included_tax_amount, 0) <> 0
                                              AND (
                                          SELECT /*+ index(ZL ZX_LINES_U1) */
                                              nvl(SUM(nvl(zl.tax_amt, 0)), 0)
                                          FROM
                                              zx_lines zl WHERE zl.application_id = 200
                                              AND zl.entity_code = ''AP_INVOICES''
                                                  AND zl.trx_id = ail.invoice_id
                                                      AND zl.trx_line_id = ail.line_number
                                                          AND nvl(zl.self_assessed_flag, ''N'') = ''N''
                                                              AND NVL(zl.reporting_only_flag, ''N'') = ''N'' AND NVL(zl.tax_amt_included_flag, ''N'') = ''Y''
                                      ) = 0
                                                  AND ai.invoice_id = invs.invoice_id UNION ALL
                                  SELECT /*+ ordered */
                                      ''CAN2'', ai.invoice_id,
                                      ai.invoice_date,
                                      ai.org_id,
                                      ai.batch_id,
                                      NULL,
                                      NULL,
                                      ''Incorrect approval status on cancelled invoice''
                                  FROM
                                      invs,
                                      ap_invoices_all ai
                                  WHERE
                                      ai.cancelled_date IS NOT null
                                      AND ai.WFAPPROVAL_STATUS NOT IN (
                                          ''NOT REQUIRED'',
                                          ''APPROVED'',
                                          ''MANUALLY APPROVED''
                                      )
                                          AND ai.invoice_id = invs.invoice_id)
                                          where rownum<1000',
      p_title                  => 'Invoice Cancellation Issue(s)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice cancellation issue(s).<br>
<strong>Impact Area(s): </strong>Invoice Cancellation
',
      p_solution               => '<strong>Solution GDF: </strong>21497508</br><strong>Note: </strong>[1489862/KB611407]</br><strong>Script Name: </strong>ap_one_off_scripts_sel.sql Cancel</br></br>Apply the GDF patch following the instructions provided in [1489862/KB611407].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: MU_INVOICE_1489862_1');



debug('begin add_signature: MU_PARTIAL_CANCELLED_INVOICE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22969',
      p_sig_id                 => 'MU_PARTIAL_CANCELLED_INVOICE',
      p_sig_sql                => 'SELECT
    /*+ leading(invs) use_nl(ai) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.quick_credit
FROM
    ap_invoices_all ai,
    (
        SELECT DISTINCT
            invoice_id
        FROM
            ap_invoice_distributions_all
        WHERE
            accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
    ) invs
WHERE
    ai.invoice_amount = 0
    AND ai.cancelled_date IS NULL
    AND ai.temp_cancelled_amount IS NOT NULL
    AND ai.invoice_id = invs.invoice_id
    AND NOT EXISTS (
        SELECT
            1
        FROM
            ap_holds_all aha
        WHERE
            aha.invoice_id = ai.invoice_id
            AND aha.hold_lookup_code IN (
                ''CANT FUNDS CHECK'',
                ''INSUFFICIENT FUNDS'',
                ''AWT ERROR'',
                ''DIST ACCT INVALID'',
                ''Encumbrance Acctg Fail''
            )
            AND aha.release_lookup_code IS NULL
            
            
 AND   NOT EXISTS (
           SELECT ail.invoice_id
           FROM ap_invoice_lines_all ail,
                ap_invoice_distributions_all aid
           WHERE ail.invoice_id = ai.invoice_id
           AND   ail.line_type_lookup_code = ''AWT''
           AND   nvl(ail.discarded_flag,''N'') = ''N''
           AND   nvl(ail.cancelled_flag,''N'') = ''N''
           AND   ail.line_type_lookup_code = ''AWT''
           AND   aid.invoice_id = ail.invoice_id
           AND   aid.invoice_line_number = ail.line_number
           AND   aid.line_type_lookup_code = ''AWT''
           AND   nvl(aid.reversal_flag,''N'') = ''N'')
    )
    AND rownum<1000
ORDER BY
    invoice_id',
      p_title                  => 'Partially Cancelled Invoice(s) Issue',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices on which cancellation was attempted but did not successfully complete.<br/><strong>Impact Area(s): </strong>Invoice Cancellation',
      p_solution               => '<strong>Solution GDF: </strong>19276929</br><strong>Note: </strong>[1060611/KB738036]</br><strong>Script Name: </strong>ap_cancel_inv_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1060611/KB738036]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: MU_PARTIAL_CANCELLED_INVOICE');



debug('begin add_signature: MU_COMMON_INVOICE_DATA_ISSUES');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added now cols as per MGD_27'):= '1 corruption_type,
                                      aid.invoice_id,
                                      aid.org_id,
                                      aid.invoice_distribution_id child_id,
                                      aid.accounting_event_id,
                                      aid.bc_event_id,
                                      aid.posted_flag FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      ap_invoice_distributions_all   aid,
                                      financials_system_params_all   fsp';
  add_signature(
      p_sig_repo_id            => '22960',
      p_sig_id                 => 'MU_COMMON_INVOICE_DATA_ISSUES',
      p_sig_sql                => 'select * from (WITH invs AS (  SELECT /*+ materialize */ DISTINCT
                invoice_id
            FROM
                ap_invoice_distributions_all
            WHERE
                accounting_date BETWEEN ( trunc(SYSDATE) - 7 ) AND (trunc(SYSDATE) + 3 ) ) SELECT /*+ ordered use_nl(ai, aid) */
                                      1 corruption_type,
                                      aid.invoice_id,
                                      aid.org_id,
                                      aid.invoice_distribution_id child_id,
                                      aid.accounting_event_id,
                                      aid.bc_event_id,
                                      aid.posted_flag FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      ap_invoice_distributions_all   aid,
                                      financials_system_params_all   fsp
                                  WHERE
                                      ai.invoice_id = invs.invoice_id
                                      AND aid.invoice_id = ai.invoice_id
                                          AND aid.posted_flag = ''Y''
                                              AND ai.org_id = fsp.org_id
                                                  AND ( ( nvl(fsp.purch_encumbrance_flag, ''N'') = ''N''
                                                          AND aid.match_status_flag NOT IN (
                                          ''T'',
                                          ''A''
                                      ) )
                                                        OR (nvl(fsp.purch_encumbrance_flag, ''N'') = ''Y''
                                                             AND aid.match_status_flag <> ''A'' ) )
                                                      AND EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              xla_events x
                                          WHERE
                                              x.application_id = 200
                                              AND x.event_id = aid.accounting_event_id
                                                  AND x.event_status_code IN (
                                                  ''N'',
                                                  ''P''
                                              )
                                                      AND x.process_status_code = ''P''
                                      )
                                  UNION ALL SELECT /*+ordered use_nl(asa) */ 1.1 corruption_type,
                                      asa.invoice_id,
                                      asa.org_id,
                                      asa.invoice_distribution_id,
                                      asa.accounting_event_id,
                                      asa.bc_event_id,
                                      asa.posted_flag
                                  FROM
                                      invs,
                                      ap_self_assessed_tax_dist_all asa
                                  WHERE
                                      asa.invoice_id = invs.invoice_id
                                      AND asa.posted_flag = ''Y''
                                          AND nvl(asa.match_status_flag, ''N'') <> ''A'' AND EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              xla_events x
                                          WHERE
                                              x.application_id = 200 AND x.event_id = asa.accounting_event_id
                                                  AND x.event_status_code IN (
                                                  ''N'',
                                                  ''P''
                                              )
                                                      AND x.process_status_code = ''P''
                                      )
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(aid) */ 2,
                                      aid.invoice_id,
                                      aid.org_id, aid.invoice_distribution_id,
                                      aid.accounting_event_id,
                                      aid.bc_event_id,
                                      aid.posted_flag
                                  FROM
                                      invs,
                                      ap_invoice_distributions_all aid
                                  WHERE
                                      line_type_lookup_code IN (
                                          ''REC_TAX'',
                                          ''NONREC_TAX'',
                                          ''TRV'',
                                          ''TERV'',
                                          ''TIPV''
                                      )
                                      AND detail_tax_dist_id IS NULL
                                          AND summary_tax_line_id IS NULL
                                              AND nvl(aid.historical_flag, ''N'') = ''N''
                                                  AND aid.invoice_id = invs.invoice_id
                                  UNION ALL SELECT /*+ ordered use_nl(asad) */ 3,
                                      asad.invoice_id,
                                      asad.org_id,
                                      asad.invoice_distribution_id,
                                      asad.accounting_event_id,
                                      asad.bc_event_id,
                                      asad.posted_flag
                                  FROM
                                      invs,
                                      ap_self_assessed_tax_dist_all asad
                                  WHERE
                                      EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              zx_rec_nrec_dist zd
                                          WHERE
                                              zd.trx_id = asad.invoice_id
                                              AND zd.rec_nrec_tax_dist_id = asad.detail_tax_dist_id
                                                  AND zd.entity_code = ''AP_INVOICES''
                                                      AND zd.event_class_code IN (
                                                  ''STANDARD INVOICES'',
                                                  ''PREPAYMENT INVOICES'',
                                                  ''EXPENSE REPORTS''
                                              )
                                                          AND zd.application_id = 200
                                                              AND zd.self_assessed_flag = ''N''
                                      )
                                      AND asad.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(aid) */
                                      4,
                                      aid.invoice_id,
                                      aid.org_id,
                                      aid.invoice_distribution_id,
                                      aid.accounting_event_id,
                                      aid.bc_event_id,
                                      aid.posted_flag
                                  FROM
                                      invs,
                                      ap_invoice_distributions_all aid
                                  WHERE
                                      aid.detail_tax_dist_id IS NOT NULL
                                      AND nvl(aid.historical_flag, ''N'') = ''N''
                                          AND EXISTS (
                                          SELECT /*+ no_unnest */ 1
                                          FROM
                                              zx_rec_nrec_dist zd
                                          WHERE
                                              zd.trx_id = aid.invoice_id
                                              AND zd.rec_nrec_tax_dist_id = aid.detail_tax_dist_id
                                                  AND zd.entity_code = ''AP_INVOICES''
                                                      AND zd.event_class_code IN (
                                                  ''STANDARD INVOICES'',
                                                  ''PREPAYMENT INVOICES'',
                                                  ''EXPENSE REPORTS''
                                              )
                                                          AND zd.application_id = 200
                                                              AND zd.self_assessed_flag = ''Y''
                                      )
                                              AND aid.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(ai, asad) */
                                      5,
                                      ai.invoice_id,
                                      ai.org_id,
                                      asad.invoice_distribution_id,
                                      NULL,
                                      NULL,
                                      NULL
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_self_assessed_tax_dist_all   asad
                                  WHERE
                                      ai.invoice_id = asad.invoice_id
                                      AND asad.accounting_event_id IS NULL
                                          AND asad.bc_event_id IS NULL
                                              AND ai.cancelled_date IS NULL
                                                  AND nvl(ai.force_revalidation_flag, ''N'') <> ''Y''
                                                      AND ap_invoices_pkg.get_approval_status(ai.invoice_id, ai.invoice_amount, ai
                                                      .payment_status_flag, ai.invoice_type_lookup_code) IN (
                                          ''APPROVED'',
                                          ''AVAILABLE'',
                                          ''UNPAID'',
                                          ''FULL''
                                      )
                                                          AND ai.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(aha) */
                                      6,
                                      aha.invoice_id,
                                      aha.org_id,
                                      aha.hold_id,
                                      NULL,
                                      NULL,
                                      NULL
                                  FROM
                                      invs,
                                      ap_holds_all aha
                                  WHERE
                                      hold_lookup_code = ''CANNOT EXECUTE ALLOCATION''
                                      AND release_lookup_code IS NULL
                                          AND NOT EXISTS (
                                          SELECT /*+ no_unnest */ 1
                                          FROM
                                              ap_invoice_lines_all ail
                                          WHERE
                                              ail.invoice_id = aha.invoice_id
                                              AND line_type_lookup_code IN (
                                                  ''FREIGHT'',
                                                  ''MISCELLANEOUS''
                                              )
                                                  AND nvl(discarded_flag, ''N'') = ''N''
                                                      AND nvl(generate_dists,''N'') = ''Y''
                                      )
                                                  AND aha.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(ai) */
                                      7,
                                      ai.invoice_id,
                                      ai.org_id,
                                      NULL,
                                      NULL,
                                      NULL,
                                      NULL
                                  FROM
                                      invs,
                                      ap_invoices_all ai
                                  WHERE
                                      nvl(ai.historical_flag, ''N'') = ''N''
                                      AND ai.cancelled_date IS NOT NULL
                                          AND nvl(ai.amount_paid, 0) <> 0
                                              AND ai.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(ai) */
                                      8,
                                      ai.invoice_id,
                                      ai.org_id,
                                      NULL,
                                      NULL,
                                      NULL,
                                      NULL
                                  FROM
                                      invs,
                                      ap_invoices_all ai
                                  WHERE
                                      ai.cancelled_date IS NOT NULL
                                      AND ai.invoice_amount = 0
                                          AND nvl(ai.historical_flag, ''N'') = ''N''
                                              AND EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              ap_payment_schedules_all aps
                                          WHERE
                                              aps.invoice_id = ai.invoice_id
                                              AND aps.hold_flag = ''Y''
                                      )
                                                  AND ai.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(ai, aidrev) */
                                      9,
                                      ai.invoice_id,
                                      ai.org_id,
                                      aidrev.invoice_distribution_id,
                                      aidrev.accounting_event_id,
                                      aidrev.bc_event_id,
                                      aidrev.posted_flag
                                  FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      ap_invoice_distributions_all   aidrev
                                  WHERE
                                      ai.invoice_id = aidrev.invoice_id
                                      AND nvl(ai.historical_flag, ''N'') = ''N''
                                          AND aidrev.parent_reversal_id IS NOT NULL
                                              AND aidrev.reversal_flag = ''Y''
                                                  AND EXISTS (
                                          SELECT /*+ no_unnest */
                                              1 FROM
                                              ap_invoice_distributions_all aidori
                                          WHERE
                                              aidori.invoice_id = aidrev.invoice_id
                                              AND aidori.invoice_line_number = aidrev.invoice_line_number
                                                  AND aidori.invoice_distribution_id = aidrev.parent_reversal_id
                                                      AND abs(nvl(aidori.amount, 0)) <> abs(nvl(aidrev.amount, 0))
                                      )
                                                      AND ai.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(aid) */
                                      10,
                                      aid.invoice_id,
                                      aid.org_id,
                                      aid.invoice_distribution_id,
                                      aid.accounting_event_id,
                                      aid.bc_event_id,
                                      aid.posted_flag
                                  FROM
                                      invs,
                                      ap_invoice_distributions_all aid
                                  WHERE
                                      match_status_flag = ''S''
                                      AND nvl(aid.historical_flag, ''N'') = ''N''
                                          AND EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              ap_invoices_all ai
                                          WHERE
                                              ai.invoice_id = aid.invoice_id
                                              AND ai.validation_request_id IS NULL
                                      )
                                              AND aid.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(ai, aid) */
                                      11,
                                      ai.invoice_id,
                                      ai.org_id,
                                      aid.invoice_distribution_id,
                                      aid.accounting_event_id,
                                      aid.bc_event_id,
                                      aid.posted_flag
                                  FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      ap_invoice_distributions_all   aid,
                                      financials_system_params_all   fsp
                                  WHERE
                                      ai.org_id = fsp.org_id
                                      AND ai.invoice_id = aid.invoice_id
                                          AND ai.cancelled_date IS NOT NULL
                                              AND aid.accounting_event_id IS NOT NULL
                                                  AND ai.invoice_amount = 0 AND nvl(ai.historical_flag, ''N'') = ''N''
                                                          AND ai.validation_request_id IS NULL
                                                              AND 0 = (
                                          SELECT /*+ no_unnest */
                                              SUM(aid1.amount)
                                          FROM
                                              ap_invoice_distributions_all aid1
                                          WHERE
                                              aid1.invoice_id = ai.invoice_id
                                      )
                                                                  AND NOT EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              ap_invoice_distributions_all aid2
                                          WHERE
                                              aid2.invoice_id = ai.invoice_id
                                              AND aid2.parent_reversal_id IS NULL
                                                  AND aid2.reversal_flag = ''Y''
                                                      AND 1 <> (
                                                  SELECT /*+ no_unnest */
                                                      COUNT(1)
                                                  FROM
                                                      ap_invoice_distributions_all aid3
                                                  WHERE
                                                      aid3.parent_reversal_id = aid2.invoice_distribution_id
                                              )
                                      )
                                                                          AND ( ( nvl(aid.match_status_flag, ''N'') <> ''A''
                                                                                  AND fsp.purch_encumbrance_flag = ''Y'' )
                                                                                OR ( nvl(aid.match_status_flag, ''N'') NOT IN (
                                          ''A'',
                                          ''T''
                                      )
                                                                                     AND fsp.purch_encumbrance_flag = ''N'' ) )
                                                                              AND ai.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(ai, ail, aid) */
                                      12,
                                      ai.invoice_id,
                                      ai.org_id,
                                      aid.invoice_distribution_id,
                                      aid.accounting_event_id,
                                      aid.bc_event_id,
                                      aid.posted_flag
                                  FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      financials_system_params_all   fsp,
                                      ap_invoice_lines_all           ail,
                                      ap_invoice_distributions_all   aid
                                  WHERE
                                      ai.invoice_id = invs.invoice_id
                                      AND ail.invoice_id = ai.invoice_id
                                          AND aid.invoice_id = ail.invoice_id
                                              AND ai.org_id = fsp.org_id
                                                  AND ( nvl(ail.cancelled_flag, ''N'') = ''Y''
                                                        OR nvl(ail.discarded_flag, ''N'') = ''Y'' )
                                                      AND ai.cancelled_date IS NOT NULL
                                                          AND aid.line_type_lookup_code = ''AWT''
                                                              AND aid.parent_reversal_id IS NOT NULL
                                                                  AND aid.awt_invoice_payment_id IS NULL
                                                                      AND aid.reversal_flag = ''Y''
                                                                          AND aid.accounting_event_id IS NULL
                                                                              AND nvl(aid.match_status_flag, ''N'') = ''N''
                                                                                  AND EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              xla_transaction_entities_upg   xte,
                                              xla_events                     xe
                                          WHERE
                                              xte.entity_id = xe.entity_id
                                              AND xte.ledger_id = aid.set_of_books_id
                                                  AND nvl(xte.source_id_int_1, - 99) = aid.invoice_id
                                                      AND xte.entity_code = ''AP_INVOICES''
                                                          AND xte.application_id = 200
                                                              AND xe.event_type_code LIKE ''%CANCELLED''
                                                                  AND xe.budgetary_control_flag = ''N''
                                      )
                                                                                      AND NOT EXISTS (
                                          SELECT
                                              1
                                          FROM
                                              ap_holds_all aha
                                          WHERE
                                              aha.invoice_id = ai.invoice_id
                                              AND aha.release_lookup_code IS NULL
                                      )
                                                                                              AND fsp.purch_encumbrance_flag = ''N'')
                                                                                              where rownum<1000
                                                                                    ',
      p_title                  => 'Invoice Data Integrity',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice Data Integrity Issue(s) detected.<br>
<strong>Impact Area(s): </strong>Invoice Cancellation, Invoice Validation, Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>19637587</br><strong>Note: </strong>[1266869/KB748792]</br><strong>Script Name: </strong>AP_MISC_INVOICE_DIAG.sql</br></br>Apply the GDF patch following the instructions provided in [1266869/KB748792]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: MU_COMMON_INVOICE_DATA_ISSUES');



debug('begin add_signature: MU_INV_VALIDATION_PRB');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22951',
      p_sig_id                 => 'MU_INV_VALIDATION_PRB',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.validation_request_id
     FROM ap_invoices_all ai,
          ( SELECT DISTINCT invoice_id FROM ap_invoice_distributions_all WHERE accounting_date BETWEEN (trunc(sysdate) - 7)
AND (trunc(sysdate) + 3) ) invs
     WHERE ai.validation_request_id is not null
     AND   ai.validation_request_id > 0
     AND   (EXISTS (
              SELECT 1  FROM fnd_concurrent_requests fcr
              WHERE fcr.request_id = ai.validation_request_id
              AND   fcr.phase_code = ''C'' ) OR
            NOT EXISTS (
              SELECT 1 FROM fnd_concurrent_requests fcr
              WHERE fcr.request_id = ai.validation_request_id ))
     AND   ai.invoice_id = invs.invoice_id
  AND rownum<1000
order by invoice_id',
      p_title                  => 'Invoice Locked by Invoice Validation Request ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice(s) with VALIDATION_REQUEST_ID populated after invoice validation has completed with error.<br/><strong>Impact Area(s): </strong>Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>21616697</br><strong>Note: </strong>[1072774/KB199903]</br><strong>Script Name: </strong>ap_inv_val_prb_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1072774/KB199903].',
      p_success_msg            => 'OK! No issue found',
