debug('begin add_signature: MU_INCOMPLETE_DISCARDED_LINE');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols'):= 'ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ail.line_number,
                                      aid.parent_reversal_id      inv_dist_id,
                                      ail.line_type_lookup_code   line_type,
                                      ail.discarded_flag,
                                      1 corruption_type';
  add_signature(
      p_sig_repo_id            => '22938',
      p_sig_id                 => 'MU_INCOMPLETE_DISCARDED_LINE',
      p_sig_sql                => 'WITH invs AS ( SELECT /*+ materialize */ DISTINCT
                invoice_id
            FROM
                ap_invoice_distributions_all
            WHERE
                accounting_date BETWEEN ( trunc(SYSDATE) - 7 ) AND ( trunc(SYSDATE) + 3 ) ) SELECT
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ail.line_number,
                                      aid.parent_reversal_id      inv_dist_id,
                                      ail.line_type_lookup_code   line_type,
                                      ail.discarded_flag,
                                      1 corruption_type
                                  FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      ap_invoice_lines_all           ail,
                                      ap_invoice_distributions_all   aid
                                  WHERE
                                      ai.invoice_id = ail.invoice_id
                                      AND ail.invoice_id = aid.invoice_id
                                          AND ail.line_number = aid.invoice_line_number
                                              AND ai.cancelled_date IS NULL
                                                  AND nvl(ail.historical_flag, ''N'') = ''N''
                                                      AND nvl(ail.discarded_flag, ''N'') = ''Y''
                                                          AND nvl(aid.posted_flag, ''N'') <> ''Y''
                                                              AND nvl(aid.reversal_flag, ''N'') = ''Y''
                                                                  AND aid.parent_reversal_id IS NOT NULL
                                                                      AND ( aid.amount ) * - 1 <> (
                                          SELECT
                                              amount
                                          FROM
                                              ap_invoice_distributions_all aid1
                                          WHERE
                                              aid1.invoice_id = aid.invoice_id
                                              AND aid1.invoice_distribution_id = aid.parent_reversal_id
                                      )
                                                                          AND ai.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT
                                      ail.invoice_id,
                                      NULL,
                                      ail.org_id,
                                      ail.line_number,
                                      NULL,
                                      ail.line_type_lookup_code,
                                      ail.discarded_flag, 2
                                  FROM
                                      invs,
                                      ap_invoice_lines_all ail
                                  WHERE
                                      nvl(ail.discarded_flag, ''N'') = ''Y'' AND ail.amount <> 0
                                          AND nvl(ail.historical_flag, ''N'') <> ''Y''
                                              AND ( NOT EXISTS (
                                          SELECT
                                              1
                                          FROM
                                              ap_invoice_distributions_all aid
                                          WHERE
                                              aid.invoice_id = ail.invoice_id
                                              AND aid.invoice_line_number = ail.line_number
                                      )
                                                        OR (
                                          SELECT
                                              SUM(aid.amount)
                                          FROM
                                              ap_invoice_distributions_all aid
                                          WHERE
                                              aid.invoice_id = ail.invoice_id
                                              AND aid.invoice_line_number = ail.line_number
                                      ) = 0 )
                                                  AND ail.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ail.line_number,
                                      NULL,
                                      ail.line_type_lookup_code,
                                      ail.discarded_flag,
                                      3
                                  FROM
                                      invs, ap_invoices_all        ai,
                                      ap_invoice_lines_all   ail
                                  WHERE
                                      ai.invoice_id = ail.invoice_id
                                      AND nvl(ail.discarded_flag, ''N'') <> ''Y''
                                          AND nvl(ail.cancelled_flag, ''N'') <> ''Y''
                                              AND ail.po_line_location_id IS NOT NULL
                                                  AND EXISTS (
                                          SELECT
                                              1
                                          FROM
                                              ap_invoice_distributions_all dist
                                          WHERE
                                              dist.invoice_id = ail.invoice_id
                                              AND dist.invoice_line_number = ail.line_number
                                                  AND dist.po_distribution_id IS NOT NULL
                                                      AND dist.reversal_flag = ''Y''
                                      )
                                                      AND ai.invoice_id = invs.invoice_id
                                                      AND rownum<1000',
      p_title                  => 'Matched Distributions Are Reversed When Line Is Discarded but the Invoice Line Is Not Discarded',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Matched distributions are reversed when line is discarded but the line is not discarded.<br/><strong>Impact Area(s): </strong>Invoice Discard',
      p_solution               => '<strong>Solution GDF: </strong>18018607</br><strong>Note: </strong>[1329681/KB796151]</br><strong>Script Name: </strong>AP_DISCARD_LINE_SEL.sql</br></br>Apply the GDF patch following the instructions provided in [1329681/KB796151].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: MU_INCOMPLETE_DISCARDED_LINE');



debug('begin add_signature: MU_NOT_NULL_QTY_INV');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22944',
      p_sig_id                 => 'MU_NOT_NULL_QTY_INV',
      p_sig_sql                => 'SELECT ail.invoice_id,
          ail.org_id,
          ail.line_number,
          ail.historical_flag,
          ail.line_type_lookup_code,
          ail.discarded_flag,
          ail.cancelled_flag,
          ail.quantity_invoiced,
          ail.po_line_location_id
     FROM ap_invoice_lines_all ail,
          ( SELECT DISTINCT invoice_id FROM ap_invoice_distributions_all WHERE accounting_date BETWEEN (trunc(sysdate) - 7)
AND (trunc(sysdate) + 3) ) invs
     WHERE (nvl(discarded_flag,''N'') = ''Y'' OR
            nvl(cancelled_flag,''N'') = ''Y'')
     AND   po_line_location_id is not null
     AND   nvl(quantity_invoiced,0) <> 0
     AND   ail.invoice_id = invs.invoice_id
     AND rownum<1000
order by invoice_id',
      p_title                  => 'Quantity Billed / Amount Billed Mismatch',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Cancelled and discarded invoice lines exist where the quantity invoiced has not been set to 0.<br/><strong>Impact Area(s): </strong>Invoice Cancellation, Invoice Discard, PO Matching',
      p_solution               => '<strong>Solution GDF: </strong>17445464</br><strong>Note: </strong>[1362932/KB382681]</br><strong>Script Name: </strong>AP_NOT_NULL_QTY_INV_SEL.sql</br></br>Apply the GDF patch following the instructions provided in [1362932/KB382681].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_NOT_NULL_QTY_INV');



debug('begin add_signature: MU_INVOICE_1489862_2');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols as  per MGD_246'):= 'category,
                                      aid.invoice_id,
                                      aid.org_id,
                                      aid.invoice_line_number,
                                      aid.invoice_distribution_id,
                                      ail.po_line_location_id,
                                      aid.po_distribution_id, ''UOM codes in PO and AP do not match'' issue';
  add_signature(
      p_sig_repo_id            => '22978',
      p_sig_id                 => 'MU_INVOICE_1489862_2',
      p_sig_sql                => 'select * from (WITH invs AS ( SELECT /*+ materialize */ DISTINCT invoice_id
FROM ap_invoice_distributions_all WHERE accounting_date BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3) ) SELECT /*+ ordered */
                                      ''MAT2'' category,
                                      aid.invoice_id,
                                      aid.org_id,
                                      aid.invoice_line_number,
                                      aid.invoice_distribution_id,
                                      ail.po_line_location_id,
                                      aid.po_distribution_id, ''UOM codes in PO and AP do not match'' issue
                                  FROM
                                      invs,
                                      ap_invoice_lines_all           ail,
                                      ap_invoice_distributions_all   aid,
                                      po_line_locations_all          pll
                                  WHERE
                                      ail.invoice_id = aid.invoice_id AND ail.line_number = aid.invoice_line_number
                                          AND ail.po_line_location_id IS NOT NULL
                                              AND ail.po_line_location_id = pll.line_location_id
                                                  AND aid.dist_match_type IN (
                                          ''ITEM_TO_PO'',
                                          ''ITEM_TO_SERVICE_PO''
                                      )
                                                      AND ail.rcv_transaction_id is null
                                                          AND aid.rcv_transaction_id IS NULL
                                                              AND aid.line_type_lookup_code IN (
                                          ''ITEM'',
                                          ''ACCRUAL''
                                      )
                                                                  AND ( nvl(ail.unit_meas_lookup_code, - 1) <> nvl(pll.unit_meas_lookup_code
                                                                  , - 1) OR nvl(aid.matched_uom_lookup_code, - 1) <> nvl(pll.unit_meas_lookup_code
                                                                  , -1)
                                                                           OR nvl(ail.unit_meas_lookup_code, - 1) <> nvl(aid.MATCHED_UOM_LOOKUP_CODE, -1) )
                                                                      AND ail.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered */
                                      ''MAT3'',
                                      ail.invoice_id,
                                      ail.org_id,
                                      ail.line_number,
                                      NULL,
                                      ail.po_line_location_id,
                                      ail.po_distribution_id,
                                      ''Quantity_invoiced mismatch on AP line and distribution''
                                  FROM
                                      invs,
                                      ap_invoice_lines_all           ail,
                                      ap_invoice_distributions_all aid WHERE
                                      ail.po_line_location_id IS NOT NULL
                                      AND nvl(ail.discarded_flag, ''N'') <> ''Y''
                                          AND nvl(ail.cancelled_flag, ''N'') <> ''Y''
                                              AND ail.line_type_lookup_code IN (
                                          ''ITEM'',
                                          ''ACCRUAL''
                                      )
                                                  AND ail.match_type NOT IN (
                                          ''PRICE_CORRECTION'',
                                          ''QTY_CORRECTION''
                                      )
                                                      AND aid.invoice_id = ail.invoice_id
                                                          AND aid.invoice_line_number = ail.line_number
                                                              AND ail.invoice_id = invs.invoice_id
                                  GROUP BY
                                      ail.invoice_id,
                                      ail.org_id,
                                      ail.line_number,
                                      ail.po_line_location_id,
                                      ail.po_distribution_id,
                                      ail.amount,
                                      ail.quantity_invoiced
                                  HAVING nvl(ail.quantity_invoiced,0) <> SUM(nvl(aid.quantity_invoiced,0))
                                         AND ail.amount = SUM(aid.amount)
                                  UNION ALL
                                  SELECT /*+ ordered */
                                      ''MAT4'',
                                      ail.invoice_id,
                                      aid.org_id,
                                      aid.invoice_line_number,
                                      aid.invoice_distribution_id,
                                      ail.rcv_transaction_id,
                                      aid.rcv_transaction_id, ''Rcv_transaction_id missing on distributions matched to receipts''
                                  FROM
                                      invs,
                                      ap_invoice_lines_all           ail,
                                      ap_invoice_distributions_all   aid
                                  WHERE
                                      ail.invoice_id = aid.invoice_id
                                      AND ail.line_number = aid.invoice_line_number
                                          AND ail.po_line_location_id IS NOT NULL
                                              AND aid.po_distribution_id IS NOT NULL
                                                  AND nvl(ail.historical_flag, ''N'') <> ''Y'' AND nvl(aid.historical_flag, ''N'') <> ''Y''
                                                          AND ( ail.line_type_lookup_code IN (
                                          ''ITEM'',
                                          ''PREPAY'',
                                          ''RETAINAGE RELEASE'',
                                          ''RETROITEM''
                                      )
                                                                OR ( ail.line_type_lookup_code IN (
                                          ''FREIGHT'',
                                          ''MISCELLANEOUS''
                                      )
                                                                     AND nvl(ail.match_type, ''NOT_MATCHED'') = ''OTHER_TO_RECEIPT'') )
                                                              AND ( aid.rcv_transaction_id IS NULL
                                                                    AND ail.rcv_transaction_id IS NOT NULL
                                                                        OR ail.rcv_transaction_id IS NULL
                                                                           AND aid.rcv_transaction_id IS NOT NULL )
                                                                  AND ail.invoice_id = invs.invoice_id)
                                                                  where rownum<1000',
      p_title                  => 'Invoice Matching Related Issue(s)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice matching related issue(s) were detected.<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Solution GDF: </strong>21497508</br><strong>Note: </strong>[1489862/KB611407]</br><strong>Script Name: </strong>ap_one_off_scripts_sel.sql Matching</br></br>Apply the GDF patch following the instructions detailed in [1489862/KB611407].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_INVOICE_1489862_2');



debug('begin add_signature: MU_SYNC_MATCH_TYPE');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('added cols'):= 'ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          pll.match_option,
          pll.matching_basis,
          ail.line_type_lookup_code,
          ail.po_line_location_id,
          ail.rcv_transaction_id,
          ail.match_type line_match_type,
          aid.dist_match_type,
          ail.line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,';
  add_signature(
      p_sig_repo_id            => '22970',
      p_sig_id                 => 'MU_SYNC_MATCH_TYPE',
      p_sig_sql                => 'select * from(WITH invs AS  (SELECT /*+ materialize */ DISTINCT invoice_id FROM ap_invoice_distributions_all WHERE accounting_date 
BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3)
) 
     SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          pll.match_option,
          pll.matching_basis,
          ail.line_type_lookup_code,
          ail.po_line_location_id,
          ail.rcv_transaction_id,
          ail.match_type line_match_type,
          aid.dist_match_type,
          ail.line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          ''NON SYNC'' type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid,
        po_line_locations_all pll
   WHERE ai.invoice_id = invs.invoice_id
   AND   ail.invoice_id = ai.invoice_id
   AND   aid.invoice_id = ail.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   ail.corrected_inv_id is null
   AND   ail.corrected_line_number is null
   AND   ail.po_line_location_id is not null
   AND   ail.po_line_location_id = pll.line_location_id
   AND   (nvl(ail.match_type,''NOT_MATCHED'') <>
            nvl(aid.dist_match_type,''NOT_MATCHED'') OR
          nvl(ail.match_type,''NOT_MATCHED'') = ''NOT_MATCHED'')
   AND   ail.line_type_lookup_code IN (''ITEM'',
           ''FREIGHT'', ''MISCELLANEOUS'')
   AND   ((aid.line_type_lookup_code IN (''ITEM'',
            ''ACCRUAL'',''FREIGHT'',''MISCELLANEOUS'') AND
           nvl(ail.match_type,''NOT_MATCHED'') <>
            nvl(aid.dist_match_type,''NOT_MATCHED'')) OR
          nvl(ail.match_type,''XXX'') <> (
            CASE
              WHEN(ail.rcv_transaction_id is not null AND
                   pll.matching_basis =''QUANTITY'' AND
                   ail.line_type_lookup_code=''ITEM'') THEN
                ''ITEM_TO_RECEIPT''
              WHEN(ail.rcv_transaction_id is not null AND
                   pll.matching_basis =''AMOUNT'' AND
                   ail.line_type_lookup_code=''ITEM'')   THEN
                ''ITEM_TO_SERVICE_RECEIPT''
              WHEN(ail.rcv_transaction_id is not null AND
                   ail.line_type_lookup_code in (''FREIGHT'',''MISCELLANEOUS'')) THEN
                ''OTHER_TO_RECEIPT''
              WHEN(ail.rcv_transaction_id is null AND
                   ail.po_line_location_id is not null AND
                   pll.matching_basis =''QUANTITY'' AND
                   ail.line_type_lookup_code=''ITEM'') THEN
                ''ITEM_TO_PO''
              WHEN(ail.rcv_transaction_id is null AND
                   ail.po_line_location_id is not null AND
                   pll.matching_basis =''AMOUNT'' AND
                   ail.line_type_lookup_code=''ITEM'') THEN
                ''ITEM_TO_SERVICE_PO''
              WHEN(ail.rcv_transaction_id is null AND
                   ail.po_line_location_id is null) THEN
                ''NOT_MATCHED''
            END))
   UNION
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          null match_option,
          null matching_basis,
          ail.line_type_lookup_code,
          ail.po_line_location_id,
          ail.rcv_transaction_id,
          ail.match_type,
          aid.dist_match_type,
          ail.line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          ''NON MATCHED''
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = ail.invoice_id
   AND   ail.invoice_id = aid.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   ail.match_type IN (''ITEM_TO_PO'',''ITEM_TO_RECEIPT'')
   AND   nvl(ail.discarded_flag,''N'') <> ''Y''
   AND   nvl(ail.cancelled_flag,''N'') <> ''Y''
   AND   ail.po_header_id is null
   AND   ail.po_line_id is null
   AND   ail.po_line_location_id is null
   AND   ail.po_distribution_id is null
   AND   ail.rcv_transaction_id is null
   AND   ail.corrected_inv_id  is null
   AND   ail.corrected_line_number is null
   UNION
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          null,
          null,
          ail.line_type_lookup_code,
          ail.po_line_location_id,
          ail.rcv_transaction_id,
          ail.match_type,
          aid.dist_match_type,
          ail.line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          ''NULL VALUED''
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = ail.invoice_id
   AND   ail.invoice_id = aid.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   aid.line_type_lookup_code IN (''ITEM'', ''FREIGHT'',
           ''MISCELLANEOUS'')
   AND   aid.po_distribution_id is null
   AND   aid.rcv_transaction_id is null
   AND   aid.dist_match_type is null
   AND   ail.line_source IN (''MANUAL LINE ENTRY'', ''IMPORTED'')
   AND   ail.po_header_id is null
   AND   ail.po_line_id is null
   AND   ail.po_line_location_id is null)
   where rownum<1000
   ',
      p_title                  => 'Values of MATCH_TYPE and DIST_MATCH_TYPE Are Not in Sync ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The values of MATCH_TYPE and DIST_MATCH_TYPE are not in sync between invoice lines and distributions.  This results in issues with quantities and amounts billed which can cause issues when matching or cancelling the invoice.<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Solution GDF: </strong>24828024</br><strong>Note: </strong>[1906407/KB318210]</br><strong>Script Name: </strong>ap_sync_match_type_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1906407/KB318210].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: MU_SYNC_MATCH_TYPE');



debug('begin add_signature: MU_NULL_ESTABLISHMENT_ID_VALUE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22946',
      p_sig_id                 => 'MU_NULL_ESTABLISHMENT_ID_VALUE',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(zl) */ zl.trx_id,
          zl.trx_line_id,
          zl.event_class_code,
          zl.tax_line_id,
          zl.summary_tax_line_id,
          etb.establishment_id
     FROM (
            SELECT DISTINCT invoice_id FROM ap_invoice_distributions_all WHERE accounting_date BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3) ) invs,
          zx_lines zl,
          xle_etb_profiles etb,
          zx_party_tax_profile ptp
     WHERE zl.application_id = 200
     AND   zl.entity_code = ''AP_INVOICES''
     AND   zl.event_class_code IN (''STANDARD INVOICES'',''EXPENSE REPORTS'',
             ''PREPAYMENT INVOICES'')
     AND   zl.legal_entity_id = etb.legal_entity_id
     AND   zl.establishment_id is null
     AND   etb.main_establishment_flag = ''Y''
     AND   nvl(etb.main_effective_from, zl.trx_date) <= zl.trx_date
     AND   nvl(etb.main_effective_to, zl.trx_date) >= zl.trx_date
     AND   etb.party_id = ptp.party_id
     AND   ptp.party_type_code = ''LEGAL_ESTABLISHMENT''
     AND   zl.trx_id = invs.invoice_id
   AND rownum<1000
order by trx_id',
      p_title                  => 'ESTABLISHMENT_ID Value Is Null in Table ZX_LINES/ZX_LINES_SUMMARY ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The ESTABLISHMENT_ID value is Null in table ZX_LINES/ZX_LINES_SUMMARY which can result in ORA-00001 unique constraint errors on ZX_LINES_SUMMARY_U1.<br/><strong>Impact Area(s): </strong>EBTax, Invoice Cancellation, Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>14317362</br><strong>Note: </strong>[1152123/KB723674]</br><strong>Script Name: </strong>zx_pop_estb_id.sql</br></br>Apply the GDF patch(es) {14317362} and/or {14122718} following the instructions provided in [1152123/KB723674#Pattern2] Pattern#2.',
