debug('begin add_signature: MU_AMOUNTS_OUTOFSYNCH_BETWEEN_AP_EBTAX');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols'):= 'category,
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.invoice_date,
                                      ai.org_id,
                                      aid.invoice_line_number,
                                      aid.distribution_line_number,
                                      aid.invoice_distribution_id,
                                      aid.line_type_lookup_code,
                                      aid.amount,
                                      zd.rec_nrec_tax_amt,
                                      aid.base_amount,
                                      zd.rec_nrec_tax_amt_funcl_curr,
                                      aid.posted_flag,
                                      aid.historical_flag';
  add_signature(
      p_sig_repo_id            => '22966',
      p_sig_id                 => 'MU_AMOUNTS_OUTOFSYNCH_BETWEEN_AP_EBTAX',
      p_sig_sql                => 'WITH invs AS (  SELECT DISTINCT invoice_id FROM ap_invoice_distributions_all 
WHERE accounting_date BETWEEN (trunc(sysdate) - 7) 
AND (trunc(sysdate) + 3) ) SELECT /*+ ordered use_nl(ai, aid, zd) */
                                      ''Type 1'' category,
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.invoice_date,
                                      ai.org_id,
                                      aid.invoice_line_number,
                                      aid.distribution_line_number,
                                      aid.invoice_distribution_id,
                                      aid.line_type_lookup_code,
                                      aid.amount,
                                      zd.rec_nrec_tax_amt,
                                      aid.base_amount,
                                      zd.rec_nrec_tax_amt_funcl_curr,
                                      aid.posted_flag,
                                      aid.historical_flag
                                  FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      ap_invoice_distributions_all   aid,
                                      zx_rec_nrec_dist               zd
                                  WHERE
                                      ai.invoice_id = invs.invoice_id
                                      AND aid.invoice_id = ai.invoice_id AND aid.invoice_id = zd.trx_id
                                              AND aid.detail_tax_dist_id = zd.rec_nrec_tax_dist_id
                                                  AND zd.application_id = 200
                                                      AND zd.entity_code = ''AP_INVOICES''
                                                          AND nvl(aid.historical_flag, ''N'') = ''N''
                                                              AND zd.event_class_code IN (
                                          ''STANDARD INVOICES'',
                                          ''EXPENSE REPORTS'',
                                          ''PREPAYMENT INVOICES''
                                      )
                                                                  AND aid.line_type_lookup_code IN (
                                          ''REC_TAX'',
                                          ''NONREC_TAX''
                                      )
                                                                      AND ( nvl(aid.amount, -999999999) <> zd.rec_nrec_tax_amt
                                                                            OR nvl(aid.base_amount, - 999999999) <> zd.rec_nrec_tax_amt_funcl_curr
                                                                            )
                                                                          AND NOT EXISTS (
                                          SELECT
                                              1
                                          FROM
                                              ap_invoice_distributions_all aidv
                                          WHERE
                                              aid.detail_tax_dist_id = aidv.detail_tax_dist_id
                                              AND aid.line_type_lookup_code = ''NONREC_TAX''
                                                  AND aidv.line_type_lookup_code IN (
                                                  ''TERV'',
                                                  ''TIPV'',
                                                  ''TRV''
                                              )
                                      )
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(ai, aid, zd) */
                                      ''Type 2'',
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.invoice_date,
                                      ai.org_id,
                                      aid.invoice_line_number,
                                      aid.distribution_line_number,
                                      aid.invoice_distribution_id,
                                      aid.line_type_lookup_code,
                                      aid.amount,
                                      zd.rec_nrec_tax_amt,
                                      aid.base_amount,
                                      zd.rec_nrec_tax_amt_funcl_curr,
                                      aid.posted_flag,
                                      aid.historical_flag
                                  FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      ap_invoice_distributions_all   aid,
                                      zx_rec_nrec_dist               zd
                                  WHERE
                                      ai.invoice_id = invs.invoice_id
                                      AND aid.invoice_id = ai.invoice_id
                                          AND aid.invoice_id = zd.trx_id
                                              AND aid.detail_tax_dist_id = zd.rec_nrec_tax_dist_id
                                                  AND zd.application_id = 200
                                                      AND zd.entity_code = ''AP_INVOICES''
                                                          AND zd.event_class_code IN (
                                          ''STANDARD INVOICES'',
                                          ''EXPENSE REPORTS'',
                                          ''PREPAYMENT INVOICES''
                                      )
                                                              AND ai.exchange_rate IS NULL
                                                                  AND aid.amount <> 0
                                                                      AND aid.base_amount = 0
                                                                          AND nvl(ai.historical_flag, ''N'') = ''Y''
                                                                          AND rownum<1000',
      p_title                  => 'Amounts or Base Amounts Are Out of Sync Between Payables and EBTax',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Amounts or base amounts are out of sync between Payables and EBTax.<br/><strong>Impact Area(s): </strong>EBTax',
      p_solution               => '<strong>Solution GDF: </strong>16981628</br><strong>Note: </strong>[1322630/KB795633]</br><strong>Script Name: </strong>ap_ebtax_sync_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1322630/KB795633]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: MU_AMOUNTS_OUTOFSYNCH_BETWEEN_AP_EBTAX');



