debug('begin add_signature: MU_PREPAY_TRIPLICATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22968',
      p_sig_id                 => 'MU_PREPAY_TRIPLICATE',
      p_sig_sql                => 'SELECT ai.invoice_id invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_date,
          ai.invoice_amount,
          ai.set_of_books_id,
          xe.event_id,
          xe.event_type_code,
          apph.prepay_history_id,
          apph.invoice_line_number,
          apph.prepay_invoice_id,
          ai_prepay.invoice_num prepay_invoice_num,
          apph.prepay_line_num,
          dist_sum.amt prepay_appl_amt,
          acct_sum.amt prepay_acct_amt
     FROM xla_events xe,
          xla_transaction_entities_upg xte,
          ap_prepay_history_all apph,
          ap_invoices_all ai,
          ap_invoices_all ai_prepay,
          (
            SELECT decode(sum(aid.amount),
                     0, 1,
                     sum(aid.amount))  amt,
                   aid.accounting_event_id
            FROM ap_invoice_distributions_all aid
            WHERE aid.line_type_lookup_code IN (''PREPAY'',''REC_TAX'',''NONREC_TAX'')
            AND   aid.prepay_distribution_id is not null
            GROUP BY aid.accounting_event_id
          ) dist_sum,
          (
            SELECT sum(nvl(xal.entered_cr, 0) - nvl(xal.entered_dr, 0)) amt,
                   xe.event_id,
                   xah.ledger_id
            FROM xla_ae_lines xal,
                 xla_ae_headers xah,
                 xla_events xe,
                 xla_transaction_entities_upg xte
            WHERE xal.application_id = 200
            AND   xah.application_id = 200
            AND   xe.application_id = 200
            AND   xal.ae_header_id = xah.ae_header_id
            AND   xah.event_id = xe.event_id
            AND   xe.entity_id = xte.entity_id
            AND   xte.entity_code = ''AP_INVOICES''
            AND   xte.ledger_id = xah.ledger_id
            AND   xal.accounting_class_code = ''PREPAID_EXPENSE''
            AND   xe.event_type_code IN (''PREPAYMENT APPLIED'',''PREPAYMENT UNAPPLIED'')
            GROUP BY xe.event_id, xah.ledger_id
          ) acct_sum,
          ( SELECT DISTINCT invoice_id FROM ap_invoice_distributions_all WHERE accounting_date BETWEEN (trunc(sysdate) - 7)
AND (trunc(sysdate) + 3) ) invs
     WHERE xe.application_id = 200
     AND   xe.event_type_code IN (''PREPAYMENT APPLIED'',''PREPAYMENT UNAPPLIED'')
     AND   xe.event_status_code = ''P''
     AND   xe.event_id = dist_sum.accounting_event_id
     AND   xe.event_id = acct_sum.event_id
     AND   abs(abs(acct_sum.amt)/abs(dist_sum.amt)) > 2
     AND   xe.event_id = apph.accounting_event_id
     AND   apph.prepay_invoice_id = ai_prepay.invoice_id
     AND   xte.application_id = 200
     AND   xe.entity_id = xte.entity_id
     AND   xte.ledger_id = ai.set_of_books_id
     AND   xte.entity_code = ''AP_INVOICES''
     AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
     AND   ai.invoice_id = invs.invoice_id
AND rownum<1000
order by invoice_id',
      p_title                  => 'Prepayment Application/Unapplication Accounted Multiple Times for the Same Prepayment Amount ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Multiple prepayment application/unapplication events have resulted in accounted amounts which are multiples of the actual prepayment application amount.<br/><strong>Impact Area(s): </strong>Prepay Application',
      p_solution               => '<strong>Solution GDF: </strong>19327661</br><strong>Note: </strong>[1179414/KB725632]</br><strong>Script Name: </strong>ap_prepay_triplicate_s.sql</br></br>Apply the GDF patch following the instructions provided in [1179414/KB725632]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: MU_PREPAY_TRIPLICATE');



debug('begin add_signature: MU_INVOICE_1489862_4');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols as per MGD_249'):= 'corruption_type,
                                      aid_std.invoice_id,
                                      aid_std.org_id,
                                      ail_std.line_number,
                                      aid_std.invoice_distribution_id,
                                      aid_std.accounting_event_id,
                                      ''Prepayment applied belongs to different org or currency code'' problem_description';
  add_signature(
      p_sig_repo_id            => '22945',
      p_sig_id                 => 'MU_INVOICE_1489862_4',
      p_sig_sql                => 'select * from (WITH invs AS (SELECT /*+ materialize */ DISTINCT
                invoice_id
            FROM
                ap_invoice_distributions_all
            WHERE
                accounting_date BETWEEN ( trunc(SYSDATE) - 7 ) AND (trunc(SYSDATE) + 3 ) ) SELECT /*+ ordered use_nl(ai_std, ail_std, aid_std) */
                                      ''PRE1'' corruption_type,
                                      aid_std.invoice_id,
                                      aid_std.org_id,
                                      ail_std.line_number,
                                      aid_std.invoice_distribution_id,
                                      aid_std.accounting_event_id,
                                      ''Prepayment applied belongs to different org or currency code'' problem_description
                                  FROM
                                      invs,
                                      ap_invoices_all                ai_std,
                                      ap_invoice_lines_all           ail_std,
                                      ap_invoice_distributions_all   aid_std,
                                      ap_invoices_all                ai_prepay
                                  WHERE
                                      ai_std.invoice_id = ail_std.invoice_id
                                      AND ail_std.invoice_id = aid_std.invoice_id
                                          AND ail_std.line_number = aid_std.invoice_line_number
                                              AND ail_std.prepay_invoice_id IS NOT NULL
                                                  AND ail_std.line_type_lookup_code = ''PREPAY''
                                                      AND ail_std.prepay_invoice_id = ai_prepay.invoice_id
                                                          AND aid_std.posted_flag = ''N''
                                                              AND ( ai_prepay.invoice_currency_code <> ai_std.invoice_currency_code
                                                                    OR ai_prepay.org_id <> ai_std.org_id )
                                                                  AND ai_std.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(aid_app, aid_unap) */
                                      ''PRE2'',
                                      aid_app.invoice_id,
                                      aid_app.org_id, aid_app.invoice_line_number,
                                      aid_unap.invoice_distribution_id, aid_app.accounting_event_id,
                                      ''Prepayment unapplication event is less than the application event''
                                  FROM
                                      invs,
                                      ap_invoice_distributions_all   aid_app,
                                      ap_invoice_distributions_all   aid_unap
                                  WHERE
                                      aid_app.invoice_id = aid_unap.invoice_id
                                      AND nvl(aid_app.posted_flag, ''N'') <> ''Y''
                                          AND nvl(aid_unap.posted_flag, ''N'') <> ''Y''
                                              AND aid_app.reversal_flag = ''Y''
                                                  AND aid_unap.reversal_flag = ''Y''
                                                      AND aid_app.prepay_distribution_id IS NOT NULL
                                                          AND aid_unap.prepay_distribution_id IS NOT NULL
                                                              AND aid_unap.parent_reversal_id IS not NULL
                                                                  AND aid_unap.parent_reversal_id = aid_app.invoice_distribution_id
                                                                      AND aid_unap.accounting_event_id < aid_app.accounting_event_id
                                                                          AND aid_app.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT /*+ ordered use_nl(ai, ail) */
                                      ''PRE3'' corruption_type,
                                      ai.invoice_id,
                                      ai.org_id,
                                      ail.line_number,
                                      NULL,
                                      NULL,
                                      ''No data in ZX_DET_LINE_FACTORS for prepay invoice''
                                  FROM
                                      invs, ap_invoices_all        ai,
                                      ap_invoice_lines_all   ail
                                  WHERE
                                      ai.invoice_id = invs.invoice_id
                                      AND ai.invoice_id = ail.invoice_id
                                          AND ai.org_id = ail.org_id
                                              AND ai.cancelled_date IS NULL
                                                  AND ai.cancelled_by IS NULL
                                                      AND ai.historical_flag is NULL
                                                          AND ai.invoice_type_lookup_code IN (
                                          ''PREPAYMENT''
                                      )
                                                              AND ail.line_type_lookup_code NOT IN (
                                          ''TAX'', ''AWT'')
                                                                  AND ail.tax_already_calculated_flag IS NULL
                                                                      AND NOT EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              zx_lines_det_factors
                                          WHERE
                                              application_id = 200
                                              AND entity_code = ''AP_INVOICES''
                                                  AND trx_id = ail.invoice_id
                                                      AND trx_line_id = line_number
                                      )
                                                                              AND EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              ap_invoice_distributions_all aid
                                          WHERE
                                              ail.invoice_id = aid.invoice_id
                                              AND ail.line_number = aid.invoice_line_number
                                                  AND ail.org_id = aid.org_id
                                                      AND aid.match_status_flag = ''A''
                                      ))
                                      where rownum<1000',
      p_title                  => 'Invoice Prepayment Related Issue(s)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice prepay related issue(s) detected.<br/><strong>Impact Area(s): </strong>Prepay Application',
      p_solution               => '<strong>Solution GDF: </strong>21497508</br><strong>Note: </strong>[1489862/KB611407]</br><strong>Script Name: </strong>ap_one_off_scripts_sel.sql Prepayment</br></br>Apply the GDF patch following the instructions provided in [1489862/KB611407].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: MU_INVOICE_1489862_4');



debug('begin add_signature: MU_SET_ASSETSTRACK_FLAG');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22948',
      p_sig_id                 => 'MU_SET_ASSETSTRACK_FLAG',
      p_sig_sql                => 'SELECT /*+ leading(invs) */ aid.invoice_id invoice_id,
          aid.invoice_line_number inv_line_number,
          aid.distribution_line_number inv_dist_line_number,
          aid.line_type_lookup_code line_type,
          aid.amount,
          pd.accrue_on_receipt_flag,
          pd.code_combination_id po_code_combination_id,
          gcc_po.account_type po_acc_type,
          aid.dist_code_combination_id aid_code_combination_id,
          gcc_inv.account_type inv_acc_type,
          ail.assets_tracking_flag line_assets_track_flag,
          aid.assets_tracking_flag dist_assets_track_flag,
          aid.assets_addition_flag dist_assets_addition_flag,
          aid.invoice_distribution_id inv_dist_id,
          decode (pd.accrue_on_receipt_flag,
            ''Y'', (decode(gcc_po.account_type,
                    ''E'',nvl(ail.assets_tracking_flag,''N''),
                    ''A'',''Y'',
                    ''N'')),
            ''N'', (decode(gcc_inv.account_type,
                    ''E'',nvl(ail.assets_tracking_flag,''N''),
                    ''A'',''Y'',
                    ''N'')),
            ''N'') derived_assets_tracking_flag
     FROM ( SELECT DISTINCT invoice_id FROM ap_invoice_distributions_all WHERE accounting_date 
     BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3) ) invs,
          ap_invoice_distributions_all aid,
          ap_invoice_lines_all ail,
          po_distributions_all pd,
          gl_code_combinations gcc_po,
          gl_code_combinations gcc_inv
     WHERE aid.invoice_id = invs.invoice_id
     AND   pd.po_distribution_id = aid.po_distribution_id
     AND   ail.invoice_id  = aid.invoice_id
     AND   ail.line_number = aid.invoice_line_number
     AND   gcc_po.code_combination_id = pd.code_combination_id
     AND   gcc_inv.code_combination_id= aid.dist_code_combination_id
     AND   aid.assets_tracking_flag = ''N''
     AND   aid.line_type_lookup_code NOT IN (''NONREC_TAX'',
             ''REC_TAX'',''TRV'',''TIPV'',''TERV'')
     AND   ((pd.accrue_on_receipt_flag = ''Y'' AND
             gcc_po.account_type IN (''A'',''E'')) OR
            (pd.accrue_on_receipt_flag = ''N'' AND
             gcc_inv.account_type IN(''A'',''E'')))
     AND   ((nvl(aid.assets_tracking_flag,''X'') <>
               decode(pd.accrue_on_receipt_flag,
                 ''Y'', (decode(gcc_po.account_type,
                        ''E'',nvl(ail.assets_tracking_flag,''N''),
                        ''A'',''Y'',
                        ''N'')),
                 ''N'', (decode(gcc_inv.account_type,
                        ''E'',nvl(ail.assets_tracking_flag,''N''),
                        ''A'',''Y'',
                        ''N'')),
                 ''N'')) OR
            (aid.assets_tracking_flag = ''Y'' AND
             aid.assets_addition_flag <> ''U''))
AND rownum<1000
order by invoice_id',
      p_title                  => 'ASSETS_TRACKING_FLAG Set Incorrectly on Invoice Distributions ',
      p_fail_condition         => 'RS',
