      p_problem_descr          => 'Orphan bank accounts which are not upgraded and have no owners or assignments.<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>21983844</br>
<strong>Note: </strong>[1370214/KB689127]</br>
<strong>Script Name: </strong>iby_orphan_acct_sel.sql Cancel</br>
</br>Apply the GDF patch following the instructions provided in [1370214/KB689127].',
      p_success_msg            => 'OK!  No Issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: MU_ORPHAN_BANK_ACCTS_NO_OWNER_ASGMT');



debug('begin add_signature: MU_DUP_BANK_ACCOUNTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23324',
      p_sig_id                 => 'MU_DUP_BANK_ACCOUNTS',
      p_sig_sql                => 'SELECT ext_bank_account_id,
          currency_code,
          country_code,
          bank_account_type,
          account_suffix,
          rank() OVER (
            PARTITION BY bank_account_num, bank_id, branch_id,
                         currency_code, country_code, bank_account_num_hash1,
                         bank_account_num_hash2
            ORDER BY end_date desc, creation_date,
                     start_date, ext_bank_account_id
          ) num
   FROM iby_ext_bank_accounts
   WHERE (bank_account_num,
          nvl(bank_id,-99),
          nvl(branch_id,-99),
          nvl(currency_code,''XX''),
          country_code,
          nvl(bank_account_num_hash1,-1),
          nvl(bank_account_num_hash2,-1)) IN (
            SELECT bank_account_num,
                   nvl(bank_id,-99),
                   nvl(branch_id,-99),
                   nvl(currency_code,''XX''),
                   country_code,
                   nvl(bank_account_num_hash1,-1),
                   nvl(bank_account_num_hash2,-1)
            FROM iby_ext_bank_accounts
            WHERE country_code <> ''JP''
            AND   country_code <> ''NZ''
            GROUP BY bank_account_num, bank_id, branch_id, currency_code,
                     country_code, bank_account_num_hash1, bank_account_num_hash2
            HAVING count(*) > 1)
   UNION ALL
   SELECT ext_bank_account_id,
          currency_code,
          country_code,
          bank_account_type,
          account_suffix,
          rank() OVER (
            PARTITION BY bank_account_num, bank_id, branch_id, currency_code,
                         country_code, bank_account_num_hash1,
                         bank_account_num_hash2,bank_account_type
            ORDER BY end_date desc, creation_date, start_date,
                     ext_bank_account_id
          ) num
   FROM iby_ext_bank_accounts
   WHERE (bank_account_num,
          nvl(bank_id,-99),
          nvl(branch_id,-99),
          nvl(currency_code,''XX''),
          country_code,
          nvl(bank_account_num_hash1,-1),
          nvl(bank_account_num_hash2,-1),
          nvl(bank_account_type,''XX'')) IN (
            SELECT bank_account_num,
                   nvl(bank_id,-99),
                   nvl(branch_id,-99),
                   nvl(currency_code,''XX''),
                   country_code,
                   nvl(bank_account_num_hash1,-1),
                   nvl(bank_account_num_hash2,-1),
                   nvl(bank_account_type,''XX'')
            FROM iby_ext_bank_accounts
            WHERE country_code = ''JP''
            GROUP BY bank_account_num, bank_id, branch_id, currency_code,
                  country_code,  bank_account_num_hash1, bank_account_num_hash2,
                  bank_account_type
            HAVING   count(*) > 1)
   UNION ALL
   SELECT ext_bank_account_id,
          currency_code,
          country_code,
          bank_account_type,
          account_suffix,
          rank() OVER (
            PARTITION BY bank_account_num, bank_id,branch_id, currency_code,
                         country_code, bank_account_num_hash1, bank_account_num_hash2,
                         account_suffix
            ORDER BY end_date desc, creation_date,
                     start_date, ext_bank_account_id
          ) num
   FROM iby_ext_bank_accounts
   WHERE (bank_account_num,
          nvl(bank_id,-99),
          nvl(branch_id,-99),
          nvl(currency_code,''XX''),
          country_code,
          nvl(bank_account_num_hash1,-1),
          nvl(bank_account_num_hash2,-1),
          nvl(ACCOUNT_SUFFIX,''XX'')) IN (
            SELECT bank_account_num,
                   nvl(bank_id,-99),
                   nvl(branch_id,-99),
                   nvl(currency_code,''XX''),
                   country_code,
                   nvl(bank_account_num_hash1,-1),
                   nvl(bank_account_num_hash2,-1),
                   nvl(ACCOUNT_SUFFIX,''XX'')
            FROM iby_ext_bank_accounts
            WHERE country_code = ''NZ''
            GROUP BY bank_account_num, bank_id, branch_id, currency_code,
                     country_code, bank_account_num_hash1, bank_account_num_hash2,
                     account_suffix
            HAVING count(*) > 1)',
      p_title                  => 'Duplicate Bank Account(s)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Duplicate bank accounts exist.<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>10144798</br><strong>Note: </strong>[1265353/KB627120]</br><strong>Script Name: </strong>iby_dup_bnkAcct_Sel.sql</br></br>Apply the GDF patch following the instructions provided in [1265353/KB627120].',
      p_success_msg            => 'OK!  No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: MU_DUP_BANK_ACCOUNTS');



debug('begin add_signature: MU_DUPLICATE_EXTERNAL_PAYEES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22976',
      p_sig_id                 => 'MU_DUPLICATE_EXTERNAL_PAYEES',
      p_sig_sql                => 'SELECT a.ext_payee_id,
          a.payee_party_id,
          a.payment_function,
          a.exclusive_payment_flag,
          a.party_site_id,
          a.supplier_site_id,
          a.org_id,
          a.org_type,
          a.default_payment_method_code,
          a.ece_tp_location_code,
          a.payment_reason_code,
          a.inactive_date,
          a.delivery_channel_code,
          a.payment_format_code,
          a.settlement_priority,
          a.remit_advice_delivery_method,
          rank() OVER (
            PARTITION BY a.payee_party_id, a.payment_function,
                         a.party_site_id, a.supplier_site_id,
                         a.org_id, a.org_type
            ORDER BY a.payee_party_id, a.last_update_date desc,
                     a.ext_payee_id
            ) as ranking
FROM iby_external_payees_all a
WHERE EXISTS (
        SELECT ''duplicates'' FROM iby_external_payees_all b
        WHERE a.payee_party_id = b.payee_party_id
        AND   a.payment_function = b.payment_function
        AND   nvl(a.party_site_id, 0) = nvl(b.party_site_id, 0)
        AND   nvl(a.supplier_site_id, 0) = nvl(b.supplier_site_id, 0)
        AND   nvl(a.org_id, 0) = nvl(b.org_id, 0)
        AND   nvl(a.org_type, ''0'') = nvl(b.org_type, ''0'')
        AND   a.ext_payee_id <> b.ext_payee_id)
        AND rownum<1000
order by ext_payee_id',
      p_title                  => 'Duplicate External Payee in IBY_EXTERNAL_PAYEES_ALL ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Duplicate external payees in IBY_EXTERNAL_PAYEES_ALL.<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>13857555</br><strong>Note: </strong>[1315812/KB627688]</br><strong>Script Name: </strong>iby_dup_payee_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1315812/KB627688].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: MU_DUPLICATE_EXTERNAL_PAYEES');



debug('begin add_signature: MU_INCORRECT_PMT_DATA_INVOICE');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols'):= 'ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason';
  add_signature(
      p_sig_repo_id            => '22929',
      p_sig_id                 => 'MU_INCORRECT_PMT_DATA_INVOICE',
      p_sig_sql                => 'select * from (WITH invs AS (
    SELECT /*+ materialize */ DISTINCT
invoice_id
FROM
ap_invoice_distributions_all
WHERE
accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
   )
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT ''Incorrect Amt Paid'' Reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(aid.amount) *
                          nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid,
                       ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND aid.invoice_id = ai.invoice_id
                  AND ail.line_number = aid.invoice_line_number
                  AND aid.prepay_distribution_id is not null
                  AND nvl(ail.invoice_includes_prepay_flag,''N'')<>''Y'') prepay_amt,
                 (SELECT sum(aip.amount) FROM ap_invoice_payments_all aip
                  WHERE aip.invoice_id = ai.invoice_id) pay_amt
          FROM invs,
               ap_invoices_all ai
          WHERE ai.validation_request_id is null
          AND   ai.cancelled_date is null
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   WHERE (nvl(ap.pay_amt,0)-nvl(ap.prepay_amt,0)) <> nvl(ap.amount_paid,0)
   UNION ALL
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT /*+ ordered use_nl(ai) */
                 ''Incorrect Amt Remaining'' Reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid,
                 nvl(ai.discount_amount_taken,0) disc_amt,
                 nvl(ai.payment_cross_rate,1) payment_cross_rate,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(ail.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND ail.line_type_lookup_code = ''AWT'') awt_amt,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(ail.retained_amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND nvl(ai.net_of_retainage_flag,''N'')<>''Y'') retained_amt,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(aid.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid,
                       ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND   aid.invoice_id = ai.invoice_id
                  AND   ail.line_number = aid.invoice_line_number
                  AND   aid.prepay_distribution_id is not null
                  AND   nvl(ail.invoice_includes_prepay_flag,''N'')<>''Y'') prepay_amt,
                 (SELECT sum(aip.amount) FROM ap_invoice_payments_all aip
                  WHERE aip.invoice_id = ai.invoice_id) pay_amt,
                 -- Modified per request 11646
                 (SELECT /*+ no_unnest */ sum(nvl(amount_remaining,0))
                  FROM ap_payment_schedules_all aps
                  WHERE aps.invoice_id = ai.invoice_id) amount_remain
          FROM invs,
               ap_invoices_all ai
          WHERE ai.validation_request_id is null
          AND   ai.cancelled_date is null
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   -- Remove nvl on ap.amount_remain as per request 11646
   WHERE (((ap.invoice_amount * ap.payment_cross_rate) - disc_amt +
            nvl(ap.awt_amt,0) + nvl(ap.retained_amt,0)) -
           (nvl(ap.pay_amt,0) - nvl(ap.prepay_amt,0))) <>
            ap.amount_remain
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ''Null Amt Remaining''
   FROM invs,
        ap_invoices_all ai,
        ap_payment_schedules_all ap
   WHERE ap.amount_remaining is null
   AND   ap.invoice_id = ai.invoice_id
   AND   ap.checkrun_id is null
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ no_query_transformation */
          ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT /*+ ordered use_nl(ai, aps1) */
                 ''Fully paid but Payment_status_flag not Y'' reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(aid.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid,
                       ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND aid.invoice_id = ai.invoice_id
                  AND ail.line_number = aid.invoice_line_number
                  AND aid.prepay_distribution_id is not null
                  AND nvl(ail.invoice_includes_prepay_flag,''N'')<>''Y'') prepay_amt,
                 (SELECT sum(aip.amount) FROM ap_invoice_payments_all aip
                  WHERE aip.invoice_id = ai.invoice_id) pay_amt,
                 (SELECT sum(aps.amount_remaining)
                  FROM ap_payment_schedules_all aps
                  WHERE aps.invoice_id = ai.invoice_id) amount_remain
          FROM invs,
               ap_invoices_all ai,
               ap_payment_schedules_all aps1
          WHERE ai.invoice_id = invs.invoice_id
          AND   aps1.invoice_id = ai.invoice_id
          AND   (ai.payment_status_flag <> ''Y'' OR aps1.payment_status_flag<>''Y'')
          AND   ai.cancelled_date is null
          AND   ai.validation_request_id is null
          AND   aps1.checkrun_id is null
        ) ap
   WHERE nvl(ap.pay_amt,0) - nvl(ap.prepay_amt,0) = nvl(ap.amount_paid,0)
   AND   ap.amount_paid <> 0
   AND   ap.amount_remain = 0
   UNION ALL
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT ''Inv unpaid but Payment_status_flag not N'' Reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid
          FROM invs,
               ap_invoices_all ai,
               ap_payment_schedules_all aps
          WHERE ai.invoice_id = aps.invoice_id
          AND   (nvl(ai.payment_status_flag,''N'') <> ''N'' OR
                 nvl(aps.payment_status_flag,''N'') <> ''N'')
          AND   ai.cancelled_date is null
          AND   aps.amount_remaining <> 0
          AND   ai.validation_request_id is null
          AND   aps.checkrun_id is null
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   WHERE nvl(ap.amount_paid,0)=0
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ap.org_id,
          ''Null Payment status flag'' Reason
   FROM invs,
        ap_invoices_all ai,
        ap_payment_schedules_all ap
   WHERE (ap.payment_status_flag is null OR
          ai.payment_status_flag is null)
   AND   ai.validation_request_id is null
   AND   ap.invoice_id = ai.invoice_id
   AND   ap.checkrun_id is null
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT ''Wrong pay status flag for partial paid invoices'' reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid,
                 nvl(ai.discount_amount_taken,0) disc_amt,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(aid.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid,
                       ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND   aid.invoice_id = ai.invoice_id
                  AND   ail.line_number = aid.invoice_line_number
                  AND   aid.prepay_distribution_id is not null
                  AND   nvl(ail.invoice_includes_prepay_flag,''N'')<>''Y'') prepay_amt,
                 (SELECT sum(aip.amount) FROM ap_invoice_payments_all aip
                  WHERE aip.invoice_id = ai.invoice_id) pay_amt,
                 (SELECT sum(aps.amount_remaining) FROM ap_payment_schedules_all aps
                  WHERE aps.invoice_id = ai.invoice_id) amount_remain
          FROM invs,
               ap_invoices_all ai
          WHERE ai.payment_status_flag in (''N'',''Y'')
          AND   ai.cancelled_date is null
          AND   ai.validation_request_id is null
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   WHERE nvl(ap.amount_remain,0) <> 0
   AND   nvl(ap.amount_paid,0) <> 0
   AND   (nvl(ap.prepay_amt,0) <> 0 OR
          nvl(ap.pay_amt,0) <> 0)
   UNION ALL
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.Reason
   FROM (
          SELECT ''Incorrect pay status flag for partial paid invoices'' Reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 aps.org_id,
                 aps.payment_num,
                 aps.amount_remaining,
                 aps.gross_amount,
                 aps.payment_status_flag,
                 ai.payment_currency_code,
                 (SELECT AP_UTILITIES_PKG.ap_round_currency(sum(aid.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid
                  WHERE aid.invoice_id = ai.invoice_id
                  AND   aid.line_type_lookup_code = ''AWT''
                  AND   aid.awt_invoice_payment_id is null) inv_awt_amt,
                 (SELECT sum(aps.gross_amount) FROM ap_payment_schedules_all aps
                  WHERE aps.invoice_id = ai.invoice_id) tot_gross_amt
          FROM ap_invoices_all ai,
               ap_payment_schedules_all aps, invs
          WHERE ai.invoice_id = aps.invoice_id
          AND   aps.amount_remaining <> 0
          AND   ai.cancelled_date is null
          AND   ai.validation_request_id is null
          AND   aps.checkrun_id is null
          AND   nvl(ai.historical_flag,''N'')<>''Y''
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   WHERE ap.gross_amount<>0
   AND   ap.tot_gross_amt<>0
   AND   ap.payment_status_flag <> decode(nvl(ap.amount_remaining,0), 0, ''Y'', AP_UTILITIES_PKG.ap_round_currency(ap.gross_amount + (nvl(ap.inv_awt_amt,0) * nvl(ap.gross_amount,0) / nvl(ap.tot_gross_amt,1)),payment_currency_code), ''N'', ''P'')
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ''Inc Amt Remn, paid for cancelled invs'' Reason
   FROM invs,
        ap_invoices_all ai
   WHERE ai.cancelled_date is not null
   AND   (nvl(ai.amount_paid,0) <> 0 OR
         EXISTS (
           SELECT 1 FROM ap_payment_schedules_all aps
           WHERE aps.invoice_id = ai.invoice_id
           AND amount_remaining <> 0))
   AND   ai.validation_request_id is null
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT  ai.invoice_id,
           ai.invoice_num,
           ai.invoice_date,
           ai.org_id,
           ''Incorrect Gross Amount on Schedule''
   FROM invs,
        ap_invoices ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   ((ai.pay_curr_invoice_amount <>
             ap_utilities_pkg.ap_round_currency((ai.invoice_amount - (
               CASE
                 WHEN nvl(ai.net_of_retainage_flag, ''N'') = ''N'' THEN
                   nvl(abs(ap_invoices_utility_pkg.get_retained_total(
                             ai.invoice_id,
                             ai.org_id)),0)
                 ELSE 0
               END)) * ai.payment_cross_rate,
               ai.payment_currency_code)
           ) OR
           (ai.pay_curr_invoice_amount <> (
              SELECT sum(aps.gross_amount)
              FROM ap_payment_schedules_all aps
              WHERE aps.invoice_id = ai.invoice_id)))
   AND   ai.historical_flag is null
   AND   EXISTS (
           SELECT 1 FROM ap_payment_schedules_all aps
           WHERE aps.invoice_id = ai.invoice_id
           HAVING count(aps.invoice_id) = 1)
   AND   ai.cancelled_date is null
   AND   ai.validation_request_id is null)
   where rownum<1000',
      p_title                  => 'Invoice with Incorrect Data in Payment Schedules or Payment Fields ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices with incorrect data in payment schedule(s) or payment field(s). <br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>23338547</br><strong>Note: </strong>[1174813/KB738668]</br><strong>Script Name: </strong>ap_inc_payment_schedules_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1174813/KB738668].
</br></br>
<strong>NOTE:</strong>  If  the payment schedule is a split schedule, in a small number of cases this query may produce false positives. If you believe the transaction is in incorrect please work with Support to correct the data.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: MU_INCORRECT_PMT_DATA_INVOICE');



debug('begin add_signature: MU_INV_FROM_TERM_PPR');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols based on MGD_41'):= 'ai.invoice_id     held_invoice_id,
                                      ai.invoice_num    held_invoice_num,
                                      ai.org_id,
                                      ai.invoice_date   held_invoice_date,
                                      aps.payment_num   held_schedule_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      aisc.checkrun_name,
                                      aisc.status || '' (Case 1)'' status,
                                      aisc.request_id';
  add_signature(
      p_sig_repo_id            => '22981',
      p_sig_id                 => 'MU_INV_FROM_TERM_PPR',
      p_sig_sql                => 'select * from (WITH invs AS ( SELECT /*+ materialize */ DISTINCT
                invoice_id
            FROM
                ap_invoice_distributions_all
            WHERE
                accounting_date BETWEEN ( trunc(SYSDATE) - 7 ) AND ( trunc(SYSDATE) + 3 ) ) /* CASE 1 */ SELECT /*+ ordered use_nl(ai, aps, aisc, asi) */
                                      ai.invoice_id     held_invoice_id,
                                      ai.invoice_num    held_invoice_num,
                                      ai.org_id,
                                      ai.invoice_date   held_invoice_date,
                                      aps.payment_num   held_schedule_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      aisc.checkrun_name,
                                      aisc.status || '' (Case 1)'' status,
                                      aisc.request_id
                                  FROM invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc,
                                      ap_selected_invoices_all        asi
                                  WHERE
                                      ai.invoice_id = invs.invoice_id
                                      AND aps.invoice_id = ai.invoice_id
                                          AND aisc.checkrun_id = aps.checkrun_id AND asi.checkrun_id = aisc.checkrun_id
                                                  AND NOT EXISTS (
                                          SELECT /*+ no_unnest */
                                              ''Corresponding PSR''
                                          FROM
                                              iby_pay_service_requests ipsr
                                          WHERE
                                              ipsr.calling_app_id = 200
                                              AND ipsr.call_app_pay_service_req_code = aisc.checkrun_name
                                      )
                                                          AND aisc.status IN (
                                          ''CANCELING'',
                                          ''CANCELED'',
                                          ''SELECTING'',
                                          ''CALCULATING'',
                                          ''REVIEW'',
                                          ''SELECTED'')
                                  UNION /* CASE 1.1 - No data in asi/aps - specially for UNSTARTED case*/
                                  SELECT /*+ ordered use_nl(ai, aps, aisc) */
                                      ai.invoice_id held_invoice_id,
                                      ai.invoice_num    held_invoice_num,
                                      ai.org_id,
                                      ai.invoice_date   held_invoice_date, aps.payment_num   held_schedule_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      aisc.checkrun_name,
                                      aisc.status || '' (Case 1.1)'',
                                      aisc.request_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc WHERE
                                      ai.invoice_id = invs.invoice_id
                                      AND aps.invoice_id = ai.invoice_id
                                          AND aisc.checkrun_id = aps.checkrun_id
                                              AND ( NOT EXISTS (
                                          SELECT /*+ no_unnest */
                                              ''Corresponding PSR''
                                          FROM
                                              iby_pay_service_requests ipsr
                                          WHERE
                                              ipsr.calling_app_id = 200
                                              AND ipsr.call_app_pay_service_req_code = aisc.checkrun_name
                                      )
                                                        OR EXISTS (
                                          SELECT
                                              ''Corresponding PSR''
                                          FROM
                                              iby_pay_service_requests ipsr
                                          WHERE
                                              ipsr.calling_app_id = 200
                                              AND ipsr.call_app_pay_service_req_code = aisc.checkrun_name
                                                  AND ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr.payment_service_request_status
                                                  ) = ''TERMINATED''
                                      ) )
                                                  AND aisc.status IN (
                                          ''CANCELING'',
                                          ''SELECTING'',
                                          ''CALCULATING'',
                                          ''UNSTARTED'',
                                          ''REVIEW'',
                                          ''SELECTED''
                                      )
                                                      AND NOT EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              ap_selected_invoices_all asi
                                          WHERE
                                              asi.checkrun_id = aisc.checkrun_id
                                      )
                                                              AND NOT EXISTS (
                                          SELECT /*+ no_unnest */ 1
                                          FROM
                                              ap_payment_schedules_all aps
                                          WHERE
                                              aps.checkrun_id = aisc.checkrun_id
                                      ) UNION /* CASE 2 */
                                  SELECT /*+ ordered use_nl(ai, aps, aisc, ipsr) */
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_date,
                                      aps.payment_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      ipsr.call_app_pay_service_req_code,
                                      ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr.payment_service_request_status
                                      )
                                      || '' (Case 2)'',
                                      aisc.request_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc,
                                      iby_pay_service_requests        ipsr
                                  WHERE
                                      ai.invoice_id = aps.invoice_id
                                      AND aisc.checkrun_name = ipsr.call_app_pay_service_req_code
                                          AND aps.checkrun_id = aisc.checkrun_id
                                              AND ipsr.calling_app_id = 200
                                                  AND ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr.payment_service_request_status
                                                  ) = ''TERMINATED''
                                                      AND ai.invoice_id = invs.invoice_id
                                  UNION /* CASE 3 */
                                  SELECT /*+ ordered use_nl(ai, aps, aisc, idp, ipsr) */
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_date,
                                      aps.payment_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      ipsr.call_app_pay_service_req_code,
                                      ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr.payment_service_request_status
                                      )
                                      || '' (Case 3)'',
                                      aisc.request_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc,
                                      iby_docs_payable_all            idp,
                                      iby_pay_service_requests        ipsr
                                  WHERE
                                      ai.invoice_id = aps.invoice_id
                                      AND aps.checkrun_id = aisc.checkrun_id
                                          AND ipsr.call_app_pay_service_req_code = aisc.checkrun_name
                                              AND ipsr.calling_app_id = 200 AND idp.calling_app_id = 200
                                                      AND idp.calling_app_doc_unique_ref1 = TO_CHAR(aps.checkrun_id)
                                                          AND idp.calling_app_doc_unique_ref2 = TO_CHAR(aps.invoice_id)
                                                              AND idp.calling_app_doc_unique_ref3 = TO_CHAR(aps.payment_num)
                                                                  AND ipsr.payment_service_request_id = idp.payment_service_request_id
                                                                      AND idp.document_status IN (
                                          ''REMOVED'',
                                          ''REMOVED_INSTRUCTION_TERMINATED'',
                                          ''REMOVED_REQUEST_TERMINATED'',
                                          ''REMOVED_PAYMENT_REMOVED'',
                                          ''REMOVED_PAYMENT_SPOILED'',
                                          ''FAILED_VALIDATION'',
                                          ''PAYMENT_FAILED_VALIDATION'',
                                          ''REJECTED'',
                                          ''FAILED_BY_REJECTION_LEVEL'',
                                          ''FAILED_BY_CALLING_APP'',
                                          ''FAILED_BY_RELATED_DOCUMENT'',
                                          ''REMOVED_PAYMENT_STOPPED'',
                                          ''REMOVED_PAYMENT_VOIDED''
                                      )
                                                                          AND ai.invoice_id = invs.invoice_id
                                  UNION /* CASE 4 */
                                  SELECT /*+ ordered use_nl(ai, aps, aisc, ipsr) */
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_date,
                                      aps.payment_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      ipsr.call_app_pay_service_req_code,
                                      ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr.payment_service_request_status
                                      )
                                      || '' (Case 4)'',
                                      aisc.request_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc,
                                      iby_pay_service_requests        ipsr
                                  WHERE
                                      ai.invoice_id = aps.invoice_id
                                      AND aps.checkrun_id = aisc.checkrun_id
                                          AND ipsr.call_app_pay_service_req_code = aisc.checkrun_name
                                              AND ipsr.calling_app_id = 200
                                                  AND ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr.payment_service_request_status
                                                  ) = ''CONFIRMED''
                                                      AND NOT EXISTS (
                                          SELECT /*+ no_unnest */
                                              ''Corresponding Docs Payable''
                                          FROM
                                              iby_docs_payable_all idp
                                          WHERE
                                              idp.calling_app_doc_unique_ref1 = aps.checkrun_id
                                              AND idp.calling_app_doc_unique_ref2 = aps.invoice_id
                                                  AND idp.calling_app_doc_unique_ref3 = aps.payment_num
                                                      AND idp.payment_service_request_id = ipsr.payment_service_request_id
                                      )
                                                              AND ai.invoice_id = invs.invoice_id
                                  UNION /* CASE 5 */
                                  SELECT /*+ ordered use_nl(ai, aps, aisc) */
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_date,
                                      aps.payment_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      aisc.checkrun_name,
                                      aisc.status || '' (Case 5)'',
                                      aisc.request_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc
                                  WHERE
                                      ai.invoice_id = aps.invoice_id
                                      AND aps.checkrun_id = aisc.checkrun_id
                                          AND NOT EXISTS (
                                          SELECT /*+ no_unnest */
                                              ''Data in AP_SELECTED_INVOICES_ALL''
                                          FROM
                                              ap_selected_invoices_all asi
                                          WHERE
                                              asi.checkrun_id = aisc.checkrun_id
                                      )
                                                  AND ai.invoice_id = invs.invoice_id
                                  UNION /* CASE 6 */
                                  SELECT /*+ ordered use_nl(ai, aps, aisc) */
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_date,
                                      aps.payment_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      aisc.checkrun_name,
                                      aisc.status || '' (Case 6)'',
                                      aisc.request_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc
                                  WHERE
                                      ai.invoice_id = aps.invoice_id
                                      AND aps.checkrun_id = aisc.checkrun_id
                                          AND EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              ap_selected_invoices_all   si2,
                                              ap_payment_schedules_all   ps
                                          WHERE
                                              si2.checkrun_id = aisc.checkrun_id
                                              AND si2.invoice_id = ps.invoice_id
                                                  AND si2.payment_num = ps.payment_num
                                                      AND ( ( si2.org_id IS NULL
                                                              AND ps.org_id IS NOT NULL )
                                                            OR si2.exclusive_payment_flag IS NULL
                                                               OR ps.payment_method_code IS NULL
                                                                  OR si2.payment_amount IS NULL
                                                                     OR si2.payment_currency_code IS NULL
                                                                        OR aisc.check_date IS NULL )
                                      )
                                              AND ai.invoice_id = invs.invoice_id
                                  UNION /* CASE 7 */
                                  SELECT /*+ ordered use_nl(ai, aps, aisc, ipsr) */
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_date,
                                      aps.payment_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      ipsr.call_app_pay_service_req_code,
                                      ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr.payment_service_request_status
                                      )
                                      || '' (Case 7)'',
                                      aisc.request_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc,
                                      iby_pay_service_requests        ipsr,
                                      iby_docs_payable_all            idp
                                  WHERE
                                      ai.invoice_id = aps.invoice_id
                                      AND aps.checkrun_id = aisc.checkrun_id
                                          AND ipsr.call_app_pay_service_req_code = aisc.checkrun_name
                                              AND ipsr.calling_app_id = 200
                                                  AND ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr.payment_service_request_status
                                                  ) = ''CONFIRMED''
                                                      AND idp.calling_app_doc_unique_ref1 = aps.checkrun_id
                                                          AND idp.calling_app_doc_unique_ref2 = aps.invoice_id
                                                              AND idp.calling_app_doc_unique_ref3 = aps.payment_num
                                                                  AND idp.payment_service_request_id = ipsr.payment_service_request_id
                                                                      AND idp.document_status IN (
                                          ''PAYMENT_CREATED''
                                      )
                                                                          AND EXISTS (
                                          SELECT /*+ ordered no_unnest */
                                              ''AP Pmt Data Exists''
                                          FROM
                                              ap_invoice_payments_all   aip,
                                              ap_payment_history_all    aph,
                                              ap_checks_all             ac,
                                              iby_docs_payable_all      idp
                                          WHERE
                                              idp.payment_id = ac.payment_id
                                              AND ac.check_id = aip.check_id
                                                  AND aip.invoice_id = aps.invoice_id
                                                      AND aip.payment_num = aps.payment_num
                                                          AND aip.accounting_event_id = aph.accounting_event_id
                                                              AND ac.check_id = aph.check_id
                                                                  AND nvl(aip.reversal_flag, ''N'') <> ''Y''
                                      )
                                                                              AND ai.invoice_id = invs.invoice_id
                                  UNION /* CASE 8 */
                                  SELECT /*+ ordered use_nl(ai, aps, aisc) */
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_date,
                                      aps.payment_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      aisc.checkrun_name,
                                      aisc.status || ''(Case 8)'',
                                      aisc.request_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc
                                  WHERE
                                      ai.invoice_id = aps.invoice_id
                                      AND aps.checkrun_id = aisc.checkrun_id
                                          AND EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              ap_selected_invoices_all   si2,
                                              ap_invoices_all            ai
                                          WHERE
                                              si2.checkrun_id = aisc.checkrun_id
                                              AND si2.invoice_id = ai.invoice_id
                                                  AND si2.vendor_name IS NULL
                                                      AND ai.vendor_id IS NOT NULL
                                      )
                                              AND ai.invoice_id = invs.invoice_id
                                  UNION /* CASE 9 */
                                  SELECT /*+ ordered use_nl(ai, aps, aisc) */
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_date,
                                      aps.payment_num,
                                      aisc.checkrun_id,
                                      aisc.check_date,
                                      aisc.checkrun_name,
                                      ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr.payment_service_request_status
                                      )
                                      || ''(Case 9)'',
                                      aisc.request_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_payment_schedules_all        aps,
                                      ap_inv_selection_criteria_all   aisc,
                                      iby_pay_service_requests        ipsr,
                                      iby_payments_all                ipa,
                                      iby_pay_instructions_all        ipia,
                                      ce_payment_documents            cpd
                                  WHERE
                                      ai.invoice_id = invs.invoice_id
                                      AND aps.invoice_id = ai.invoice_id
                                          AND aisc.checkrun_id = aps.checkrun_id
                                              AND aisc.checkrun_name = ipsr.call_app_pay_service_req_code
                                                  AND ipsr.calling_app_id = 200
                                                      AND ap_payment_util_pkg.get_psr_status(ipsr.payment_service_request_id, ipsr
                                                      .payment_service_request_status) IN (
                                          ''CONFIRMED'',
                                          ''TERMINATED''
                                      )
                                                          AND ipsr.payment_service_request_id = ipa.payment_service_request_id
                                                              AND ipa.payment_instruction_id = ipia.payment_instruction_id
                                                                  AND cpd.payment_instruction_id = ipia.payment_instruction_id
                                                                      AND NOT EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              ap_selected_invoices_all asi
                                          WHERE
                                              asi.checkrun_id = aisc.checkrun_id
                                      )
                                                                              AND NOT EXISTS (
                                          SELECT /*+ no_unnest */
                                              1
                                          FROM
                                              ap_payment_schedules_all aps
                                          WHERE
                                              aps.checkrun_id = aisc.checkrun_id
                                      ))
                                      where rownum<1000',
      p_title                  => 'Stuck Invoice After PPR Is Terminated or Completed ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'PPRs which are in Terminated, Confirmed, or Review status, but whose associated invoices are in selected state.<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>21533330</br><strong>Note: </strong>[874862/KB208033]</br><strong>Script Name: </strong>ap_Rel_Inv_frm_TermPPR_sel.sql</br></br>Apply the GDF patch following the instructions provided in [874862/KB208033].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: MU_INV_FROM_TERM_PPR');



debug('begin add_signature: MU_ORPHAN_CHECKS_NOT_PAYINGANYINVOICE');
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22962',
      p_sig_id                 => 'MU_ORPHAN_CHECKS_NOT_PAYINGANYINVOICE',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.amount,
          ac.status_lookup_code,
          aph.accounting_event_id,
          aph.posted_flag,
          ac.vendor_id,
          ac.vendor_site_id,
          ac.payment_id,
          ac.payment_document_id
FROM ap_checks_all ac, ap_payment_history_all aph, 
( SELECT DISTINCT ph.check_id FROM ap_payment_history_all ph WHERE ph.accounting_date BETWEEN (trunc(sysdate) - 7) 
AND (trunc(sysdate) + 3) ) chks 
WHERE ac.check_id = chks.check_id
AND ac.payment_id is null 
AND   ac.status_lookup_code NOT IN (''OVERFLOW'',''SET UP'',''SPOILED'') 
AND   ac.check_id = aph.check_id 
AND   nvl(aph.historical_flag,''N'') <> ''Y'' 
AND   aph.posted_flag <> ''Y'' 
AND   NOT EXISTS 
( SELECT 1 FROM ap_invoice_payments_all aip WHERE aip.check_id = ac.check_id) 
AND   EXISTS  
( SELECT 1 FROM ap_invoice_payments_all aip1, ap_checks_all ac1 
WHERE aip1.check_id = ac1.check_id 
AND   ac.org_id = ac1.org_id 
AND   ((ac.vendor_id = ac1.vendor_id 
AND ac.vendor_site_id = ac1.vendor_site_id) 
OR ac.payment_document_id = ac1.payment_document_id) 
AND   Ac.check_number = ac1.check_number ) 
AND   ac.check_id = chks.check_id
AND rownum<1000
order by check_id',
      p_title                  => 'Orphan Checks',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphan checks not paying any invoice and where another check exists with the same check number and vendor information or payment document id. These orphans cause the accounting program to fail.<br/><strong>Impact Area(s): </strong>Accounting Failure, Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>22873624</br><strong>Note: </strong>[2115968/KB778253]</br><strong>Script Name: </strong>ap_incorrect_checks_sel.sql Case 1</br></br>Apply the GDF patch following the instructions provided in [2115968/KB778253].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_ORPHAN_CHECKS_NOT_PAYINGANYINVOICE');



