debug('begin add_signature: MU_OUTOFSYNC_AMOUNTS_DIST_XLA');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols'):= 'corruption_type,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_amount,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.accounting_event_id';
  add_signature(
      p_sig_repo_id            => '22965',
      p_sig_id                 => 'MU_OUTOFSYNC_AMOUNTS_DIST_XLA',
      p_sig_sql                => 'select * from (WITH invs AS (
    SELECT /*+ materialize */ DISTINCT
       invoice_id
   FROM
       ap_invoice_distributions_all
   WHERE
       accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
   )
   SELECT /*+ ordered use_nl(ai, aid, xdl, xe, xah, xal) */
          ''INCL_TAX_INCORR_AMT_IN_AID_XDL'' corruption_type,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_amount,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.accounting_event_id
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        xla_distribution_links xdl,
        xla_events xe,
        xla_ae_headers xah,
        gl_ledgers gl,
        xla_ae_lines xal
   WHERE ai.invoice_id = invs.invoice_id
   AND   xah.ledger_id = gl.ledger_id
   AND   gl.sla_ledger_cash_basis_flag = ''N''
   AND   ai.invoice_id = aid.invoice_id
   AND   aid.line_type_lookup_code NOT IN (''PREPAY'', ''AWT'', ''NONREC_TAX'',
           ''REC_TAX'', ''TRV'', ''TERV'', ''TIPV'')
   AND   aid.prepay_distribution_id is null
   AND   aid.accounting_event_id = xe.event_id
   AND   xe.event_status_code = ''P''
   AND   xe.process_status_code = ''P''
   AND   nvl(xe.budgetary_control_flag, ''N'') = ''N''
   AND   xe.event_id = xah.event_id
   AND   xah.balance_type_code = ''A''
   AND   xah.application_id = 200
   AND   xah.application_id = xe.application_id
   AND   xah.application_id = xal.application_id
   AND   xah.application_id = xdl.application_id
   AND   xah.parent_ae_header_id is null
   AND   xah.ae_header_id = xal.ae_header_id
   AND   nvl(xah.upg_batch_id, -9999) = -9999
   AND   xal.accounting_class_code = ''LIABILITY''
   AND   xah.ae_header_id = xdl.ae_header_id
   AND   xal.ae_line_num = xdl.ae_line_num
   AND   xdl.source_distribution_type = ''AP_INV_DIST''
   AND   xdl.source_distribution_id_num_1 = aid.invoice_distribution_id
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_distributions_all aid2
           WHERE aid2.invoice_id = aid.invoice_id
           AND   aid2.line_type_lookup_code IN (''NONREC_TAX'', ''REC_TAX'',
                   ''TIPV'', ''TERV'', ''TRV'')
           AND   aid2.invoice_line_number = aid.invoice_line_number
           AND   aid2.charge_applicable_to_dist_id = aid.invoice_distribution_id
           AND   aid2.posted_flag = ''Y'')
   AND   (nvl(xdl.unrounded_entered_cr, xdl.unrounded_entered_dr) <> abs(aid.amount) OR
          NOT EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_invoice_distributions_all aid3,
                xla_ae_headers xah2,
                xla_distribution_links xdl2
           WHERE aid3.invoice_id = aid.invoice_id
           AND   aid3.line_type_lookup_code IN (''NONREC_TAX'', ''REC_TAX'',
                   ''TIPV'', ''TERV'', ''TRV'')
           AND   aid3.invoice_line_number = aid.invoice_line_number
           AND   aid3.charge_applicable_to_dist_id = aid.invoice_distribution_id
           AND   xah2.ledger_id = xah.ledger_id
           AND   xah2.application_id = xah.application_id
           AND   xdl2.application_id = xah.application_id
           AND   xah2.event_id = aid3.accounting_event_id
           AND   xah2.ae_header_id = xdl2.ae_header_id
           AND   xdl2.source_distribution_type = ''AP_INV_DIST''
           AND   xdl2.source_distribution_id_num_1 = aid3.invoice_distribution_id ))
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid, xdl, xe, xah, xal) */
          ''INCORR_AMT_AID_XDL'' corruption_type,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          aid.org_id,
          ai.invoice_amount,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.accounting_event_id
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        xla_distribution_links xdl,
        xla_events xe,
        xla_ae_headers xah,
        gl_ledgers gl,
        xla_ae_lines xal
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.invoice_id = ai.invoice_id
   AND   aid.line_type_lookup_code NOT IN (''PREPAY'',''AWT'')
   AND   aid.prepay_distribution_id is null
   AND   xe.event_id = aid.accounting_event_id
   AND   xe.event_status_code = ''P''
   AND   xe.process_status_code = ''P''
   AND   xe.application_id = 200
   AND   nvl(xe.budgetary_control_flag, ''N'') = ''N''
   AND   xah.event_id = xe.event_id
   AND   xah.application_id = xe.application_id
   AND   xah.balance_type_code = ''A''
   AND   xah.parent_ae_header_id is null
   AND   nvl(xah.upg_batch_id, -9999) = -9999
   AND   gl.ledger_id = xah.ledger_id
   AND   gl.sla_ledger_cash_basis_flag = ''N''
   AND   xal.ae_header_id = xah.ae_header_id
   AND   xal.application_id = xah.application_id
   AND   xal.accounting_class_code = ''LIABILITY''
   AND   xdl.source_distribution_type = ''AP_INV_DIST''
   AND   xdl.source_distribution_id_num_1 = aid.invoice_distribution_id
   AND   xdl.application_id = xah.application_id
   AND   xdl.ae_header_id = nvl(xal.ae_header_id,0)
   AND   xdl.ae_line_num = nvl(xal.ae_line_num,0)
   AND   ((abs(nvl(aid.base_amount, aid.amount)) <>
             abs(nvl(xdl.unrounded_accounted_cr,0) -
             nvl(xdl.unrounded_accounted_dr,0))  AND
           xah.ledger_id = ai.set_of_books_id) OR
          ((abs(aid.amount) <>  abs(nvl(xdl.unrounded_entered_cr,0) -
              nvl(xdl.unrounded_entered_dr,0)))  AND
            xah.ledger_id <> ai.set_of_books_id))
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid, xe, xah, xte) */
          ''MISSING_AID_IN_XDL'' corruption_type,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          aid.org_id,
          ai.invoice_amount,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.accounting_event_id
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        xla_events xe,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah,
        gl_ledgers gl
   WHERE xah.ledger_id = gl.ledger_id
   AND   gl.sla_ledger_cash_basis_flag = ''N''
   AND   ai.invoice_id = aid.invoice_id
   AND   aid.line_type_lookup_code NOT IN (''PREPAY'',''AWT'')
   AND   aid.prepay_distribution_id is null
   AND   xe.event_id = aid.accounting_event_id
   AND   nvl(xe.budgetary_control_flag, ''N'') = ''N''
   AND   xah.event_id = xe.event_id
   AND   xah.application_id = 200
   AND   xah.balance_type_code = ''A''
   AND   xah.parent_ae_header_id is null
   AND   NOT (aid.line_type_lookup_code IN (''ERV'',''TERV'') AND
           xah.ledger_id <> ai.set_of_books_id)
   AND   xe.application_id = 200
   AND   xe.event_status_code = ''P''
   AND   xe.process_status_code = ''P''
   AND   xe.entity_id = xte.entity_id
   AND   xte.application_id = 200
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.source_id_int_1 = ai.invoice_id
   AND   nvl(xah.upg_batch_id, -9999) = -9999
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM xla_distribution_links xdl
           WHERE xah.application_id = xdl.application_id
           AND   xah.ae_header_id = xdl.ae_header_id
           AND   xdl.source_distribution_type = ''AP_INV_DIST''
           AND   xdl.source_distribution_id_num_1 = aid.invoice_distribution_id )
   AND   ai.invoice_id = invs.invoice_id)
   where rownum<1000',
      p_title                  => 'Out of Sync Amounts Between Invoice Distributions and XLA_DISTRIBUTION_LINKS ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Out of sync amounts between Invoice Distributions and XLA_DISTRIBUTION_LINKS.<br/><strong>Impact Area(s): </strong>Accounting Incorrect, Invoice Discard, Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>20086994</br><strong>Note: </strong>[1063263/KB627822]</br><strong>Script Name: </strong>ap_incl_excl_tax_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1063263/KB627822]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: MU_OUTOFSYNC_AMOUNTS_DIST_XLA');



debug('begin add_signature: MU_HISTORICAL_UPGRADED_EVENTS_MISSINGRECORDS');
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols and modified the query based  on MGD_120'):= 'ac.check_id,
    ac.check_number,
    ac.org_id,
    xe.event_id,
    xte.entity_id,
    xah.ae_header_id,
    xte.source_id_int_1 transaction_id,
    xte.transaction_number,
    xte.entity_code,
    xte.ledger_id';
  add_signature(
      p_sig_repo_id            => '22936',
      p_sig_id                 => 'MU_HISTORICAL_UPGRADED_EVENTS_MISSINGRECORDS',
      p_sig_sql                => 'SELECT
    ac.check_id,
    ac.check_number,
    ac.org_id,
    xe.event_id,
    xte.entity_id,
    xah.ae_header_id,
    xte.source_id_int_1 transaction_id,
    xte.transaction_number,
    xte.entity_code,
    xte.ledger_id
FROM
    xla_events                     xe,
    xla_transaction_entities_upg   xte,
    ap_checks_all                  ac,
    gl_period_statuses             upg,
    ap_system_parameters_all       asp,
    xla_ae_headers                 xah,
    xla_ae_lines                   xal, (SELECT DISTINCT
            ph.check_id
        FROM
            ap_payment_history_all ph
        WHERE
            ph.accounting_date BETWEEN ( trunc(SYSDATE) - 7 ) AND ( trunc(SYSDATE) + 3) ) chks
WHERE
    xe.application_id = 200
    AND xe.event_status_code = ''P''
        AND xe.upg_batch_id IS NOT NULL
            AND xe.upg_batch_id <> - 9999
                AND xah.application_id = 200
                    AND xal.application_id = 200
                        AND xah.event_id = xe.event_id
                            AND xah.ae_header_id = xal.ae_header_id
                                AND xah.upg_batch_id IS NOT NULL
                                    AND xte.application_id = 200
                                        AND xte.ledger_id = xah.ledger_id
                                            AND xte.entity_code = ''AP_PAYMENTS''
                                                AND xte.entity_id = xe.entity_id
                                                    AND ac.check_id = nvl(xte.source_id_int_1, - 99)
                                                        AND upg.application_id = xte.application_id
                                                            AND upg.ledger_id = xte.ledger_id
                                                                AND upg.set_of_books_id = asp.set_of_books_id
                                                                    AND asp.set_of_books_id = xte.ledger_id
                                                                        AND asp.org_id = ac.org_id
                                                                            AND ac.check_date BETWEEN upg.start_date AND upg.end_date
                                                                                AND upg.migration_status_code = ''U''
                                                                                    AND upg.closing_status IN (
        ''O'',
        ''C'',
        ''P''
    )
                                                                                        AND trunc(upg.start_date) < (
        SELECT
            MIN(trunc(creation_date))
        FROM
            ad_applied_patches
        WHERE
            patch_type = ''MAINTENANCE-PACK''
            AND maint_pack_level LIKE ''12.%''
    )
                                                                                            AND EXISTS (
        SELECT
            1 FROM
            ap_invoice_payments_all aip
        WHERE
            aip.check_id = ac.check_id
    )
                                                                                                AND NOT EXISTS (
        SELECT
            1
        FROM
            xla_distribution_links xdl
        WHERE
            xdl.application_id = 200
            AND xdl.ae_header_id = xah.ae_header_id
                AND xdl.ae_line_num = xal.ae_line_num
    )
                                                                                                        AND ac.check_id = chks.check_id
AND rownum<1000',
      p_title                  => 'Historical Upgraded Events with Missing Records in XLA_DISTRIBUTION_LINKS',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Missing records in XLA_DISTRIBUTION_LINKS for migrated transactions.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close',
      p_solution               => '<strong>Solution GDF: </strong>19877760</br><strong>Note: </strong>[1054299/KB202267]</br><strong>Script Name: </strong>ap_trx_missing_xdl.sql</br></br>Apply the GDF patch following the instructions provided in [1054299/KB202267].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: MU_HISTORICAL_UPGRADED_EVENTS_MISSINGRECORDS');



debug('begin add_signature: MU_INVALIDAADS');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Modified the sql query as per MGD_280 and removed the org_id paramter'):= 'l.name ledger_name,
          l.ledger_id,
          o.owner,
          o.object_name,
          o.object_id,
          o.status,
          o.last_ddl_time,
          o.timestamp,
          am.accounting_method_code,
          am.name accounting_method_name,
          am.enabled_flag accounting_method_enabled,
          pr.product_rule_code aad,
          pr.name aad_name,
          pr.enabled_flag aad_enabled_flag,
          pr.compile_status_code aad_compile_status,
          pr.product_rule_type_code,
          pr.product_rule_hash_id';
  add_signature(
      p_sig_repo_id            => '22932',
      p_sig_id                 => 'MU_INVALIDAADS',
      p_sig_sql                => 'SELECT l.name ledger_name,
          l.ledger_id,
          o.owner,
          o.object_name,
          o.object_id,
          o.status,
          o.last_ddl_time,
          o.timestamp,
          am.accounting_method_code,
          am.name accounting_method_name,
          am.enabled_flag accounting_method_enabled,
          pr.product_rule_code aad,
          pr.name aad_name,
          pr.enabled_flag aad_enabled_flag,
          pr.compile_status_code aad_compile_status,
          pr.product_rule_type_code,
          pr.product_rule_hash_id
   FROM ap_system_parameters_all sp,
        gl_ledgers l,
        xla_acctg_methods_vl am,
        xla_acctg_method_rules aad,
        xla_product_rules_vl pr,
        dba_objects o
   WHERE 
   o.owner = ''APPS''
   AND   o.object_type = ''PACKAGE BODY''
   AND   o.object_name like ''XLA_00200_AAD%''||pr.product_rule_hash_id||''%PKG''
   AND   o.status = ''INVALID''
   AND   l.ledger_id = sp.set_of_books_id
   AND   am.accounting_method_type_code = l.sla_accounting_method_type
   AND   am.accounting_method_code = l.sla_accounting_method_code
   AND   aad.application_id = 200
   AND   aad.accounting_method_code = am.accounting_method_code
   AND   aad.accounting_method_type_code = am.accounting_method_type_code
   AND   pr.application_id = aad.application_id
   AND   pr.amb_context_code = aad.amb_context_code
   AND   pr.product_rule_type_code = aad.product_rule_type_code
   AND   pr.product_rule_code = aad.product_rule_code
  AND rownum<1000
   ORDER BY l.ledger_id

',
      p_title                  => 'Application Accounting Definitions (AAD) Found with Invalid Status ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invalid Application Accounting Definitions (AAD) exist for the indicated ledgers.  A valid Payables AAD is required to create Payables accounting for a ledger.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close',
      p_solution               => '<strong>Note: </strong>[601318/KB662778]</br><strong>Script Name: </strong>None</br></br>Run the Validate Application Accounting definition program to validate the AAD.  Review the report output and investigate/resolve any invalids.  See [601318/KB662778] for details on running and investigating/resolving invalid AAD errors.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: MU_INVALIDAADS');



debug('begin add_signature: MU_INVOICES_MULTIPLE_TRANSACTION_ENTITIES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22939',
      p_sig_id                 => 'MU_INVOICES_MULTIPLE_TRANSACTION_ENTITIES',
      p_sig_sql                => 'SELECT /*+ leading(invs) use_nl(ai, xte2) */ 
 ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          xte2.application_id,
          xte2.entity_id,
          xte2.ledger_id,
          xte2.entity_code,
  xte2.source_id_int_1
FROM (
       SELECT DISTINCT invoice_id
       FROM ap_invoice_distributions_all
       WHERE accounting_date BETWEEN (trunc(sysdate) - 7) AND
         (trunc(sysdate) + 3)
     ) invs,
     ap_invoices_all ai,
     xla_transaction_entities_upg xte2,
     xla_events xe2
WHERE 1 < (
        SELECT count(*)
        FROM xla_transaction_entities_upg xte
        WHERE xte.application_id = xte2.application_id
        AND   xte.ledger_id = xte2.ledger_id
        AND   xte.entity_code = xte2.entity_code
        AND   nvl(xte.source_id_int_1,-99) = xte2.source_id_int_1)
AND   xe2.application_id(+) = xte2.application_id
AND   xe2.entity_id(+) = xte2.entity_id
AND   xte2.ledger_id = ai.set_of_books_id
AND   xte2.application_id = 200
AND   xte2.entity_code = ''AP_INVOICES''
AND   nvl(xte2.source_id_int_1, -99) = ai.invoice_id
AND   ai.invoice_id = invs.invoice_id
AND rownum<1000
order by invoice_id',
      p_title                  => 'Multiple Entities Created for Invoice(s) ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices with multiple transaction entity records in SLA.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close, Sweep',
      p_solution               => '<strong>Solution GDF: </strong>9651687</br><strong>Note: </strong>[1133423/KB787666]</br><strong>Script Name: </strong>xla_mulent_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1133423/KB787666].</br></br>
<strong>Note: </strong>GDF 9651687 is released for 12.0 & 12.2.  GDF patch 21221141 is released for 12.1.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: MU_INVOICES_MULTIPLE_TRANSACTION_ENTITIES');



debug('begin add_signature: MU_INVOICES_POSTINGSTATUSOUTOFSYNCH_W_ACCTGEVENTS');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols as per MGD_104'):= 'ai.invoice_id,
                                      ai.invoice_num,
                                      ai.invoice_date,
                                      ai.org_id,
                                      aid.invoice_line_number,
                                      aid.distribution_line_number,
                                      ''ap_invoice_distributions_all'' trx_table, aid.invoice_distribution_id   trx_id,
                                      aid.posted_flag,
                                      aid.accrual_posted_flag,
                                      aid.cash_posted_flag,
                                      xe.event_id, aid.set_of_books_id';
  add_signature(
      p_sig_repo_id            => '22959',
      p_sig_id                 => 'MU_INVOICES_POSTINGSTATUSOUTOFSYNCH_W_ACCTGEVENTS',
      p_sig_sql                => 'select * from (WITH invs AS ( SELECT /*+ materialize */ DISTINCT invoice_id
       FROM ap_invoice_distributions_all
       WHERE accounting_date BETWEEN (trunc(sysdate) - 7) AND
         (trunc(sysdate) + 3) ) SELECT
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.invoice_date,
                                      ai.org_id,
                                      aid.invoice_line_number,
                                      aid.distribution_line_number,
                                      ''ap_invoice_distributions_all'' trx_table, aid.invoice_distribution_id   trx_id,
                                      aid.posted_flag,
                                      aid.accrual_posted_flag,
                                      aid.cash_posted_flag,
                                      xe.event_id, aid.set_of_books_id           ledger_id
                                  FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      ap_invoice_distributions_all   aid,
                                      xla_events                     xe,
                                      gl_ledgers                     gl
                                  WHERE
                                      ( aid.posted_flag = ''N''
                                        OR ( aid.accrual_posted_flag = ''N''
                                             AND nvl(gl.sla_ledger_cash_basis_flag, ''N'') <> ''Y'' ) )
                                      AND ai.set_of_books_id = gl.ledger_id
                                          AND xe.process_status_code = ''P''
                                              AND xe.event_status_code IN (
                                          ''N'',
                                          ''P''
                                      )
                                                  AND ai.invoice_id = aid.invoice_id
                                                      AND xe.event_id = aid.accounting_event_id AND xe.application_id = 200 AND ai.invoice_id = invs.
                                                      invoice_id UNION ALL
                                  SELECT
                                      ai.invoice_id, ai.invoice_num,
                                      ai.invoice_date,
                                      ai.org_id,
                                      astd.invoice_line_number, astd.distribution_line_number,
                                      ''ap_self_assessed_tax_dist_all'' trx_table,
                                      astd.invoice_distribution_id   trx_id,
                                      astd.posted_flag,
                                      astd.accrual_posted_flag,
                                      astd.cash_posted_flag,
                                      xe.event_id,
                                      astd.set_of_books_id           ledger_id
                                  FROM
                                      invs,
                                      ap_invoices_all                 ai,
                                      ap_self_assessed_tax_dist_all   astd, xla_events                      xe, gl_ledgers                      gl
                                  WHERE
                                      ( astd.posted_flag = ''N''
                                        OR ( astd.accrual_posted_flag = ''N''
                                             AND nvl(gl.sla_ledger_cash_basis_flag, ''N'') <> ''Y'' ) )
                                      AND ai.set_of_books_id = gl.ledger_id
                                          AND xe.process_status_code = ''P''
                                              AND xe.event_status_code IN (
                                          ''N'',''P''
                                      )
                                                  AND ai.invoice_id = astd.invoice_id
                                                      AND xe.event_id = astd.accounting_event_id
                                                          AND xe.application_id = 200
                                                              AND ai.invoice_id = invs.invoice_id
                                  UNION ALL
                                  SELECT
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.invoice_date,
                                      ai.org_id, aph.prepay_line_num,
                                      NULL,
                                      ''ap_prepay_history_all'' trx_table,
                                      aph.prepay_history_id trx_id, aph.posted_flag, null,
                                      NULL,
                                      xe.event_id,
                                      xte.ledger_id           ledger_id
                                  FROM
                                      invs,
                                      ap_invoices_all                ai,
                                      ap_prepay_history_all          aph,
                                      xla_events                     xe,
                                      xla_transaction_entities_upg   xte
                                  WHERE
                                      posted_flag = ''N''
                                      AND process_status_code = ''P''
                                          AND xe.event_status_code IN (
                                          ''N'',
                                          ''P'')
                                              AND ai.invoice_id = aph.prepay_invoice_id
                                                  AND xte.security_id_int_1 = aph.org_id
                                                      AND xe.event_id = aph.accounting_event_id
                                                          AND xe.entity_id = xte.entity_id
                                                              AND xe.application_id = xte.application_id
                                                                  AND xte.application_id = 200
                                                                      AND ai.invoice_id = invs.invoice_id)
                                                                      where rownum<1000',
      p_title                  => 'Posted Flags Are Incorrect for Accounted Invoices ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Out of Sync Posting Status between the Accounting events in the Events tables and the transaction tables.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close, Sweep',
      p_solution               => '<strong>Solution GDF: </strong>18997220</br><strong>Note: </strong>[1071876/KB207473]</br><strong>Script Name: </strong>ap_incorrect_posted_flag_sel.sql Invoices</br></br>Apply the GDF patch following the instructions provided in [1071876/KB207473].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
