debug('begin add_signature: MU_INVOICE_ACCTGDATEOUTOFSYNCH');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added the cols'):= 'ai.invoice_id,
            ai.invoice_num,
            ai.invoice_date,
            ai.org_id';
  add_signature(
      p_sig_repo_id            => '22964',
      p_sig_id                 => 'MU_INVOICE_ACCTGDATEOUTOFSYNCH',
      p_sig_sql                => 'SELECT
    *
FROM
    (
        WITH ai AS (
            SELECT /*+ ordered use_nl(ai) */
                ai.invoice_id,
                ai.invoice_num,
                ai.invoice_date,
                ai.org_id
            FROM
                (
                    SELECT DISTINCT
                        invoice_id
                    FROM
                        apps.ap_invoice_distributions_all
                    WHERE
                        accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
                )               invs,
                apps.ap_invoices_all ai
            WHERE
                ai.invoice_id = invs.invoice_id
        )
        SELECT /*+ ordered use_nl(aid, xe) */
            ai.invoice_id,
            ai.invoice_num,
            ai.invoice_date,
            ai.org_id,
            aid.accounting_date,
            xe.event_date,
            xe.event_id,
            aid.posted_flag,
            aid.invoice_distribution_id,
            NULL                   rec_nrec_tax_dist_id,
            NULL                   prepay_history_id,
            ''Invoice Distribution'' trx_type
        FROM
            ai,
            apps.ap_invoice_distributions_all aid,
            apps.xla_events                   xe
        WHERE
                aid.accounting_event_id = xe.event_id
            AND xe.application_id = 200
                AND ai.invoice_id = aid.invoice_id
                    AND aid.accounting_date <> xe.event_date
        UNION ALL
        SELECT /*+ ordered use_nl(aid, xe) */
            ai.invoice_id,
            ai.invoice_num,
            ai.invoice_date,
            ai.org_id,
            aid.accounting_date,
            xe.event_date,
            xe.event_id,
            aid.posted_flag,
            aid.invoice_distribution_id,
            NULL,
            NULL,
            ''Self Assessed Tax Dist''
        FROM
            ai,
            apps.ap_self_assessed_tax_dist_all aid,
            apps.xla_events                    xe
        WHERE
                aid.accounting_event_id = xe.event_id
            AND xe.application_id = 200
                AND ai.invoice_id = aid.invoice_id
                    AND aid.accounting_date <> xe.event_date
        UNION ALL
        SELECT /*+ ordered use_nl(aid, zrnd, xe) */
            ai.invoice_id,
            ai.invoice_num,
            ai.invoice_date,
            ai.org_id,
            zrnd.gl_date,
            xe.event_date,
            xe.event_id,
            aid.posted_flag,
            NULL,
            zrnd.rec_nrec_tax_dist_id,
            NULL,
            ''Tax Detail For Inv Dist''
        FROM
            ai,
            apps.ap_invoice_distributions_all aid,
            apps.zx_rec_nrec_dist             zrnd,
            apps.xla_events                   xe
        WHERE
                aid.accounting_event_id = xe.event_id
            AND aid.detail_tax_dist_id = zrnd.rec_nrec_tax_dist_id
                AND zrnd.application_id = 200
                    AND zrnd.entity_code = ''AP_INVOICES''
                        AND zrnd.event_class_code IN ( ''STANDARD INVOICES'', ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'' )
                            AND zrnd.trx_id = aid.invoice_id
                                AND aid.invoice_id = ai.invoice_id
                                    AND xe.application_id = 200
                                        AND zrnd.gl_date <> xe.event_date
        UNION ALL
        SELECT
            ai.invoice_id,
            ai.invoice_num,
            ai.invoice_date,
            ai.org_id,
            zrnd.gl_date,
            xe.event_date,
            xe.event_id,
            aid.posted_flag,
            NULL,
            zrnd.rec_nrec_tax_dist_id,
            NULL,
            ''Tax Detail for Self Assessed Tax Dist''
        FROM
            ai,
            apps.ap_self_assessed_tax_dist_all aid,
            apps.zx_rec_nrec_dist              zrnd,
            apps.xla_events                    xe
        WHERE
                aid.accounting_event_id = xe.event_id
            AND aid.detail_tax_dist_id = zrnd.rec_nrec_tax_dist_id
                AND zrnd.application_id = 200
                    AND zrnd.entity_code = ''AP_INVOICES''
                        AND zrnd.event_class_code IN ( ''STANDARD INVOICES'', ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'' )
                            AND zrnd.trx_id = aid.invoice_id
                                AND aid.invoice_id = ai.invoice_id
                                    AND xe.application_id = 200
                                        AND zrnd.gl_date <> xe.event_date
        UNION ALL
        SELECT
            ai.invoice_id,
            ai.invoice_num,
            ai.invoice_date,
            ai.org_id,
            apph.accounting_date,
            xe.event_date,
            xe.event_id,
            apph.posted_flag,
            NULL,
            NULL,
            apph.prepay_history_id,
            ''Prepay History''
        FROM
            ai,
            apps.ap_prepay_history_all apph,
            apps.xla_events            xe
        WHERE
                apph.accounting_event_id = xe.event_id
            AND xe.application_id = 200
                AND ai.invoice_id = apph.invoice_id
                    AND apph.accounting_date <> xe.event_date
    )
WHERE
    ROWNUM < 1000',
      p_title                  => 'Invoice with Accounting Dates Out of Sync with Subledger Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Out of Sync Accounting dates between the Invoicing transaction tables and the Accounting Events table.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close, Sweep',
      p_solution               => '<strong>Solution GDF: </strong>18997124</br><strong>Note: </strong>[874904/KB769084]</br><strong>Script Name: </strong>ap_AcctgDateOutOfSynch_sel.sql</br></br>Apply the GDF patch following the instructions provided in [874904/KB769084].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: MU_INVOICE_ACCTGDATEOUTOFSYNCH');



debug('begin add_signature: MU_INVOICE_DISTRIBUTIONS_WITHNOLINES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22957',
      p_sig_id                 => 'MU_INVOICE_DISTRIBUTIONS_WITHNOLINES',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_date,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.line_type_lookup_code,
          aid.invoice_distribution_id,
          aid.amount,
          aid.base_amount,
          aid.accounting_event_id,
          aid.posted_flag,
          aid.detail_tax_dist_id,
          aid.set_of_books_id
FROM ap_invoice_distributions_all aid,
     ap_invoices_all ai,
     ap_suppliers asu,
     ap_supplier_sites_all assi,
     (
       SELECT DISTINCT invoice_id
       FROM ap_invoice_distributions_all
       WHERE accounting_date BETWEEN (trunc(sysdate) - 7) AND
         (trunc(sysdate) + 3)
     ) invs
WHERE nvl(aid.historical_flag, ''N'') = ''N''
AND   aid.invoice_id = ai.invoice_id
AND   ai.vendor_id = asu.vendor_id(+)
AND   ai.vendor_site_id = assi.vendor_site_id(+)
AND   (NOT EXISTS (
          SELECT 1 FROM ap_invoice_lines_all l
          WHERE l.invoice_id = aid.invoice_id
          AND   l.line_number = aid.invoice_line_number) OR
       aid.parent_reversal_id IN (
          SELECT p.invoice_distribution_id FROM ap_invoice_distributions_all p
          WHERE NOT EXISTS (
            SELECT 1 FROM ap_invoice_lines_all l
            WHERE l.invoice_id = p.invoice_id
            AND   l.line_number = p.invoice_line_number)))
AND   ai.invoice_id = invs.invoice_id
AND rownum<1000
order by invoice_id',
      p_title                  => 'Orphan Invoice Distributions with No Line Found ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphan invoice distributions with no corresponding invoice line.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>17983453</br><strong>Note: </strong>[1060644/KB627475]</br><strong>Script Name: </strong>ap_orphan_dists_s.sql</br></br>Apply the GDF patch following the instructions provided in [1060644/KB627475]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: MU_INVOICE_DISTRIBUTIONS_WITHNOLINES');



debug('begin add_signature: MU_MISSING_ACCOUNTINGEVENT_INVOICE');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Updated cols'):= 'ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_type_lookup_code,
                                      aid.invoice_distribution_id,
                                      aid.cancellation_flag,
                                      aid.prepay_distribution_id,
                                      aid.parent_reversal_id,
                                      ai.invoice_date,
                                      aid.historical_flag,
                                      aid.posted_flag,
                                      aid.prepay_tax_parent_id,
                                      aid.line_type_lookup_code,
                                      ap_invoices_utility_pkg.get_approval_status(ai.invoice_id, ai.invoice_amount,        ai.payment_status_flag
                                      , ai.invoice_type_lookup_code) invoice_status,
                                      ''Invoice Distribution'' distribution_type,
                                      aid.accounting_event_id';
  add_signature(
      p_sig_repo_id            => '22955',
      p_sig_id                 => 'MU_MISSING_ACCOUNTINGEVENT_INVOICE',
      p_sig_sql                => 'select * from (WITH invs AS (SELECT /*+ materialize */ DISTINCT invoice_id
FROM ap_invoice_distributions_all
WHERE accounting_date BETWEEN (trunc(sysdate) - 7) AND
(trunc(sysdate) + 3))
SELECT
                                      ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_type_lookup_code,
                                      aid.invoice_distribution_id,
                                      aid.cancellation_flag,
                                      aid.prepay_distribution_id,
                                      aid.parent_reversal_id,
                                      ai.invoice_date,
                                      aid.historical_flag,
                                      aid.posted_flag,
                                      aid.prepay_tax_parent_id,
                                      aid.line_type_lookup_code,
                                      ap_invoices_utility_pkg.get_approval_status(ai.invoice_id, ai.invoice_amount, ai.payment_status_flag
                                      , ai.invoice_type_lookup_code) invoice_status,
                                      ''Invoice Distribution'' distribution_type,
                                      aid.accounting_event_id
          FROM 
		   invs,
		  ap_invoices_all ai, 
               ap_suppliers asu, 
               ap_supplier_sites_all assi, 
               ap_invoice_distributions_all aid, 
               financials_system_params_all fsp 
        WHERE ai.invoice_id = invs.invoice_id
		AND aid.invoice_id = ai.invoice_id 
          AND ai.vendor_id = asu.vendor_id(+) 
          AND ai.vendor_site_id = assi.vendor_site_id(+) 
       --   AND nvl(ai.historical_flag,   ''N'') <> ''Y'' 
          AND fsp.org_id = aid.org_id 
          AND ((fsp.purch_encumbrance_flag = ''Y'' AND 
                aid.match_status_flag = ''A'') OR 
               (fsp.purch_encumbrance_flag = ''N'' AND 
                aid.match_status_flag IN(''A'',   ''T'')) 
              ) 
          AND nvl(aid.posted_flag,   ''N'') <>''Y'' 
          AND aid.accounting_event_id IS NULL 
       -- bug 18484204
          AND NOT EXISTS (SELECT 1
                           FROM ap_holds_all ah, ap_hold_codes ahc
                           WHERE ah.invoice_id = ai.invoice_id
                           AND ah.hold_lookup_code = ahc.hold_lookup_code
                           AND ah.release_lookup_code IS NULL
                           AND NVL(ahc.postable_flag,''N'') = ''N'')
          AND aid.awt_invoice_payment_id IS NULL                     
        UNION 
        SELECT 
                                       ai.invoice_id,
                                      ai.invoice_num,
                                      ai.org_id,
                                      ai.invoice_type_lookup_code,
                                      asad.invoice_distribution_id,
                                      asad.cancellation_flag        cancellation_flag,
                                      asad.prepay_distribution_id   prepay_distribution_id,
                                      asad.parent_reversal_id       parent_reversal_id,
                                      ai.invoice_date,
                                      NULL,
                                      asad.posted_flag,
                                      NULL,
                                      asad.line_type_lookup_code,
                                      ap_invoices_utility_pkg.get_approval_status(ai.invoice_id, ai.invoice_amount, ai.payment_status_flag
                                      , ai.invoice_type_lookup_code) invoice_status,
                                      ''Self Assessed Tax Distribution'' distribution_type,
                                      asad.accounting_event_id
          FROM 
		   invs,
            ap_invoices_all ai, 
               ap_suppliers asu, 
               ap_supplier_sites_all assi, 
               ap_self_assessed_tax_dist_all asad, 
               financials_system_params_all fsp 
        WHERE ai.invoice_id = invs.invoice_id
		AND  asad.invoice_id = ai.invoice_id 
          AND ai.vendor_id = asu.vendor_id(+) 
          AND ai.vendor_site_id = assi.vendor_site_id(+) 
       --   AND nvl(ai.historical_flag,   ''N'') <> ''Y'' 
          AND fsp.org_id = asad.org_id 
          AND ((fsp.purch_encumbrance_flag = ''Y'' AND 
                asad.match_status_flag = ''A'') OR 
               (fsp.purch_encumbrance_flag = ''N'' AND 
                asad.match_status_flag IN(''A'',   ''T'')) 
              ) 
          AND nvl(asad.posted_flag,   ''N'') <> ''Y'' 
          AND asad.accounting_event_id IS NULL 
       -- bug 21916712
          AND asad.prepay_distribution_id is NULL 
       -- bug 18484204
          AND NOT EXISTS (SELECT 1
                           FROM ap_holds_all ah, ap_hold_codes ahc
                           WHERE ah.invoice_id = ai.invoice_id
                           AND ah.hold_lookup_code = ahc.hold_lookup_code
                           AND ah.release_lookup_code IS NULL
                           AND NVL(ahc.postable_flag,''N'') = ''N'') 
          AND asad.awt_invoice_payment_id IS NULL)
          where rownum<1000',
      p_title                  => 'Approved Invoice Distributions Missing ACCOUNTING_EVENT_ID ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Approved Invoice distributions missing ACCOUNTING_EVENT_ID.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close',
      p_solution               => '<strong>Solution GDF: </strong>21916712</br><strong>Note: </strong>[972261/KB202043]</br><strong>Script Name: </strong>ap_trx_missing_event_sel.sql</br></br>Apply the GDF patch following the instructions provided in [972261/KB202043].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: MU_MISSING_ACCOUNTINGEVENT_INVOICE');



debug('begin add_signature: MU_MISSING_ACCOUNTINGEVENT_PAYMENT2');
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22971',
      p_sig_id                 => 'MU_MISSING_ACCOUNTINGEVENT_PAYMENT2',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ac, aip) */   ac.check_id,
          ac.check_number,
          aip.invoice_payment_id,
          ac.org_id,
          ac.check_date,
          ac.amount,
          ac.status_lookup_code
FROM (
       SELECT DISTINCT ph.check_id
       FROM ap_payment_history_all ph
       WHERE ph.accounting_date BETWEEN
               (trunc(sysdate) - 7) AND (trunc(sysdate) + 3)
     ) chks,
     ap_checks_all ac,
     ap_invoice_payments_all aip
WHERE ac.check_id = aip.check_id
AND   ((aip.accounting_event_id is null AND
        nvl(aip.posted_flag, ''N'') <> ''Y'') OR
       EXISTS (
         SELECT 1 FROM ap_payment_history_all aph
         WHERE aph.check_id = ac.check_id
         AND   aph.accounting_event_id is null
         AND   nvl(aph.posted_flag, ''N'') <> ''Y''))
AND   ac.check_id = chks.check_id
AND rownum<1000
order by check_id',
      p_title                  => 'Approved Payments Distributions Missing ACCOUNTING_EVENT_ID',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice payment or payment history records for the check missing accounting events.<br/><strong>Impact Area(s): </strong>Period Close',
      p_solution               => '<strong>Solution GDF: </strong>21916712</br><strong>Note: </strong>[972261/KB202043]</br><strong>Script Name: </strong>ap_trx_missing_event_sel.sql</br></br>Apply the GDF patch following the instructions provided in [972261/KB202043].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
