debug('begin add_signature: MU_ORPHAN_ACCTG_EVENTS_INVOICE');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols'):= 'ai.invoice_id ,ai.Invoice_num,ai.invoice_date, ai.org_id';
  add_signature(
      p_sig_repo_id            => '22953',
      p_sig_id                 => 'MU_ORPHAN_ACCTG_EVENTS_INVOICE',
      p_sig_sql                => 'select * from (WITH invs AS (SELECT /*+ materialize */ DISTINCT invoice_id
FROM ap_invoice_distributions_all
WHERE accounting_date BETWEEN (trunc(sysdate) - 7) AND
(trunc(sysdate) + 3)
        )
        SELECT /*+ ordered no_unnest use_nl(ai xte xe xah) */
               ''EVENT'' orphan_type,
               ''N'' processed_flag,
               ai.invoice_id,
               ai.invoice_num,
               ai.org_id,
               xe.event_id,
               xe.event_status_code,
               xe.process_status_code,
               xah.ae_header_id,
               xte.source_id_int_1 source_id,
               xte.entity_code source_table,
               xe.event_date,
               xe.entity_id,
               xe.event_type_code,
               xe.budgetary_control_flag,
               xe.upg_batch_id
        FROM invs,
             ap_invoices_all ai,
             xla_transaction_entities_upg xte,
             xla_events xe,
             xla_ae_headers xah
        WHERE xe.application_id = xte.application_id
        AND   xe.event_status_code <> ''P''
        AND   xe.event_id = xah.event_id (+)
        AND   xah.application_id(+) = xe.application_id
        AND   xte.entity_id = xe.entity_id
        AND   xte.application_id = 200
        AND   xte.entity_code = ''AP_INVOICES''
        AND   xte.ledger_id = ai.set_of_books_id
        AND   NOT EXISTS (
                SELECT ''No Invoice rows exist for this event''
                FROM ap_invoice_distributions_all aid
                WHERE aid.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No Distributions exist for the bc_event_id''
                FROM ap_invoice_distributions_all aid
                WHERE aid.bc_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No payment rows exist for this event''
                FROM ap_invoice_payments_all aip
                WHERE aip.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No payment history rows exists for this event''
                FROM ap_payment_history_all aph
                WHERE aph.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No self assessed tax rows exists for this event''
                FROM ap_self_assessed_tax_dist_all asatd
                WHERE asatd.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No self assessed tax rows exists for the bc_event_id''
                FROM ap_self_assessed_tax_dist_all asatd
                WHERE asatd.bc_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No prepay history rows exists for this event''
                FROM ap_prepay_history_all aprh
                WHERE aprh.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No prepayment history rows exists for the bc_event_id''
                FROM ap_prepay_history_all apph
                WHERE apph.bc_event_id = xe.event_id)
        AND   xe.event_type_code NOT IN
                (''MANUAL'', ''REVERSAL'',''PREPAYMENT APPLICATION ADJ'',''INVOICE_BURDEN_VALIDATED'',''INVOICE_BURDEN_CANCELLED'')
        AND   (xe.upg_batch_id is NULL OR
               xe.upg_batch_id = -9999)
        AND   NOT EXISTS (
                SELECT ''No final accounted headers''
                FROM xla_ae_headers xah
                WHERE xah.event_id = xe.event_id
                AND   xah.application_id = 200
                AND   xah.entity_id = xte.entity_id
                AND   xah.accounting_entry_status_code = ''F''
                AND   xah.gl_transfer_status_code = ''Y'')
        AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
        AND   ai.invoice_id = invs.invoice_id
        UNION ALL
        SELECT /*+ ordered no_unnest use_nl(ai xte xah) */
               ''HEADER'',
               ''N'',
               ai.invoice_id,
               ai.invoice_num,
               ai.org_id,
               xah.event_id,
               null,
               null,
               xah.ae_header_id,
               xte.source_id_int_1,
               xte.entity_code,
               xah.accounting_date,
               xah.entity_id,
               xah.event_type_code,
               null,
               xah.upg_batch_id
        FROM invs,
             ap_invoices_all ai,
             xla_transaction_entities_upg xte,
             xla_ae_headers xah
        WHERE xah.application_id = xte.application_id
        AND   xte.entity_id = xah.entity_id
        AND   xte.application_id = 200
        AND   xte.entity_code = ''AP_INVOICES''
        AND   xte.ledger_id = ai.set_of_books_id
        AND   NOT EXISTS (
                SELECT ''No Invoice rows exist for this event''
                FROM ap_invoice_distributions_all aid
                WHERE aid.accounting_event_id = xah.event_id)
        AND   NOT EXISTS (
                SELECT ''No Distributions exist for the bc_event_id''
                FROM ap_invoice_distributions_all aid
                WHERE aid.bc_event_id = xah.event_id)
        AND   NOT EXISTS (
                SELECT ''No payment rows exist for this event''
                FROM ap_invoice_payments_all aip
                WHERE aip.accounting_event_id = xah.event_id)
        AND   NOT EXISTS (
                SELECT ''No payment history rows exists for this event''
                FROM ap_payment_history_all aph
                WHERE aph.accounting_event_id = xah.event_id)
        AND   NOT EXISTS (
                SELECT ''No self assessed tax rows exists for this event''
                FROM ap_self_assessed_tax_dist_all asatd
                WHERE asatd.accounting_event_id = xah.event_id)
        AND   NOT EXISTS (
                SELECT ''No self assessed tax rows exists for the bc_event_id''
                FROM ap_self_assessed_tax_dist_all asatd
                WHERE asatd.bc_event_id = xah.event_id)
        AND   NOT EXISTS (
                SELECT ''No prepay history rows exists for this event''
                FROM ap_prepay_history_all aprh
                WHERE aprh.accounting_event_id = xah.event_id)
        AND   NOT EXISTS (
                SELECT ''No prepayment history rows exists for the bc_event_id''
                FROM ap_prepay_history_all apph
                WHERE apph.bc_event_id = xah.event_id)
        AND   NOT EXISTS (
                SELECT '' Event for this header does not exist''
                FROM xla_events xe
                WHERE xe.application_id = xah.application_id
                AND   xe.event_id = xah.event_id)
        AND   xah.event_type_code NOT IN
                (''MANUAL'', ''REVERSAL'', ''PREPAYMENT APPLICATION ADJ'',''INVOICE_BURDEN_VALIDATED'',''INVOICE_BURDEN_CANCELLED'')
        AND   (xah.upg_batch_id is NULL OR
               xah.upg_batch_id = -9999)
        AND   nvl(xah.gl_transfer_status_code, ''X'') <> ''Y''
        AND   nvl(xah.accounting_entry_status_code, ''X'') <> ''F''
        AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
        AND   ai.invoice_id = invs.invoice_id
        UNION ALL
        SELECT /*+ ordered no_unnest use_nl(ai xte xe xah) */
               ''EVENT'' orphan_type,
               ''Y'' processed_flag,
               ai.invoice_id,
               ai.invoice_num,
               ai.org_id,
               xe.event_id,
               xe.event_status_code,
               xe.process_status_code,
               xah.ae_header_id,
               xte.source_id_int_1 source_id,
               xte.entity_code source_table,
               xe.event_date,
               xe.entity_id,
               xe.event_type_code,
               xe.budgetary_control_flag,
               xe.upg_batch_id
        FROM invs,
             ap_invoices_all ai,
             xla_transaction_entities_upg xte,
             xla_events xe,
             xla_ae_headers xah
        WHERE xe.application_id = 200
        AND   xe.event_status_code = ''P''
        AND   xah.event_id = xe.event_id
        AND   xah.application_id = 200
        AND   xte.entity_id = xe.entity_id
        AND   xte.application_id = 200
        AND   xte.entity_code = ''AP_INVOICES''
        AND   xte.ledger_id = ai.set_of_books_id
        AND   NOT EXISTS (
                SELECT ''No Invoice rows exist for this event''
                FROM ap_invoice_distributions_all aid
                WHERE aid.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No Distributions exist for the bc_event_id''
                FROM ap_invoice_distributions_all aid
                WHERE aid.bc_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No payment rows exist for this event''
                FROM ap_invoice_payments_all aip
                WHERE aip.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No payment history rows exists for this event''
                FROM ap_payment_history_all aph
                WHERE aph.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No self assessed tax rows exists for this event''
                FROM ap_self_assessed_tax_dist_all asatd
                WHERE asatd.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No self assessed tax rows exists for the bc_event_id''
                FROM ap_self_assessed_tax_dist_all asatd
                WHERE asatd.bc_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No prepay history rows exists for this event''
                FROM ap_prepay_history_all aprh
                WHERE aprh.accounting_event_id = xe.event_id)
        AND   NOT EXISTS (
                SELECT ''No prepayment history rows exists for the bc_event_id''
                FROM ap_prepay_history_all apph
                WHERE apph.bc_event_id = xe.event_id)
        AND   xe.event_type_code NOT IN
                (''MANUAL'', ''REVERSAL'', ''PREPAYMENT APPLICATION ADJ'',''INVOICE_BURDEN_VALIDATED'',''INVOICE_BURDEN_CANCELLED'')
        AND   (xe.upg_batch_id is NULL OR
               xe.upg_batch_id = -9999)
        AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
     AND   ai.invoice_id = invs.invoice_id)
     where rownum<1000',
      p_title                  => 'Invoice(s) with Orphan Accounting Event(s)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphan Accounting Events found that have records in the XLA_EVENTS table but are not stamped on any Transaction tables.<br/><strong>Impact Area(s): </strong>Accounting Incorrect, Period Close, Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>30080042</br><strong>Note: </strong>[788135/KB157909]</br><strong>Script Name: </strong>ap_Orphan_Events_Sel.sql</br></br>Apply the GDF patch following the instructions provided in [788135/KB157909]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
