  add_signature(
      p_sig_repo_id            => '22961',
      p_sig_id                 => 'MU_ORPHAN_ACCTG_EVENTS_PAYMENT',
      p_sig_sql                => 'select *
from
(WITH chks AS  ( SELECT /*+ materialize */ DISTINCT ph.check_id FROM ap_payment_history_all ph
WHERE ph.accounting_date BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3) )
 
     SELECT ''EVENT'' orphan_type,
          ''N'' processed_flag,
          ac.check_id,
          ac.check_number,
          ac.org_id,
          xe.event_id,
          xe.event_status_code,
          xe.process_status_code,
          xah.ae_header_id,
          xte.source_id_int_1 source_id,
          xte.entity_code source_table,
