          xe.event_type_code,
          xe.budgetary_control_flag,
          xe.upg_batch_id
     FROM chks,
          ap_checks_all ac,
          ap_system_parameters_all asp,
          xla_transaction_entities_upg xte,
          xla_events xe,
          xla_ae_headers xah
     WHERE xe.application_id = xte.application_id
     AND   xe.event_status_code <> ''P''
     AND   xe.event_id = xah.event_id (+)
     AND   xah.application_id(+) = xe.application_id
     AND   xte.entity_id = xe.entity_id
     AND   xte.application_id = 200
     AND   xte.entity_code = ''AP_PAYMENTS''
     AND   NOT EXISTS (
             SELECT ''No Inv rows for event'' FROM ap_invoice_distributions_all aid
             WHERE aid.accounting_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No Dists for bc_event_id'' FROM ap_invoice_distributions_all aid
             WHERE aid.bc_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No pmt rows for event'' FROM ap_invoice_payments_all aip
             WHERE aip.accounting_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No pmt hist rows for event'' FROM ap_payment_history_all aph
             WHERE aph.accounting_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No self assessed tax rows for event''
             FROM ap_self_assessed_tax_dist_all asatd
             WHERE asatd.accounting_event_id = xe.event_id)
     AND    NOT EXISTS (
             SELECT ''No self assessed tax rows  for bc_event_id''
             FROM   ap_self_assessed_tax_dist_all asatd
             WHERE  asatd.bc_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No prepay hist rows for event''
             FROM ap_prepay_history_all aprh
             WHERE aprh.accounting_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No prepayment hist rows for bc_event_id''
             FROM   ap_prepay_history_all apph
             WHERE  apph.bc_event_id = xe.event_id)
     AND   xe.event_type_code NOT IN
             (''MANUAL'', ''REVERSAL'', ''PREPAYMENT APPLICATION ADJ'')
     AND   (xe.upg_batch_id is null OR xe.upg_batch_id = -9999)
     AND   NOT EXISTS (
             SELECT ''No final accounted headers'' FROM   xla_ae_headers xah
             WHERE  xah.event_id = xe.event_id
             AND    xah.application_id = 200
             AND    xah.entity_id = xte.entity_id
             AND    xah.accounting_entry_status_code = ''F''
             AND    xah.gl_transfer_status_code = ''Y'')
     AND   xte.ledger_id = asp.set_of_books_id
     AND   nvl(xte.source_id_int_1, -99) = ac.check_id
     AND   asp.org_id = ac.org_id
     AND   ac.check_id = chks.check_id
     UNION ALL
     SELECT ''HEADER'',
          ''N'',
          ac.check_id,
          ac.check_number,
          ac.org_id,
          xah.event_id,
          null,
          null,
          xah.ae_header_id,
          xte.source_id_int_1 source_id,
          xte.entity_code source_table,
          xah.accounting_date,
          xah.entity_id,
          xah.event_type_code,
          null,
          xah.upg_batch_id
     FROM chks,
          ap_checks_all ac,
          ap_system_parameters_all asp,
          xla_transaction_entities_upg xte,
          xla_ae_headers xah
     WHERE xah.application_id = xte.application_id
     AND   xte.entity_id = xah.entity_id
     AND   xte.application_id = 200
     AND   xte.entity_code = ''AP_PAYMENTS''
     AND   NOT EXISTS (
             SELECT ''No Invoice rows exist for this event''
             FROM ap_invoice_distributions_all aid
             WHERE aid.accounting_event_id = xah.event_id)
     AND   NOT EXISTS (
             SELECT ''No Distributions exist for the bc_event_id''
             FROM ap_invoice_distributions_all aid
             WHERE aid.bc_event_id = xah.event_id)
     AND   NOT EXISTS (
             SELECT ''No payment rows exist for this event''
             FROM ap_invoice_payments_all aip
             WHERE aip.accounting_event_id = xah.event_id)
     AND   NOT EXISTS (
             SELECT ''No payment history rows exists for this event''
             FROM ap_payment_history_all aph
             WHERE aph.accounting_event_id = xah.event_id)
     AND   NOT EXISTS (
             SELECT ''No self assessed tax rows exists for this event''
             FROM ap_self_assessed_tax_dist_all asatd
             WHERE asatd.accounting_event_id = xah.event_id)
     AND    NOT EXISTS (
             SELECT ''No self assessed tax rows exists for the bc_event_id''
             FROM ap_self_assessed_tax_dist_all asatd
             WHERE  asatd.bc_event_id = xah.event_id)
     AND   NOT EXISTS (
             SELECT ''No prepay history rows exists for this event''
             FROM ap_prepay_history_all aprh
             WHERE aprh.accounting_event_id = xah.event_id)
     AND   NOT EXISTS (
             SELECT ''No prepayment history rows exists for the bc_event_id''
             FROM ap_prepay_history_all apph
             WHERE apph.bc_event_id = xah.event_id)
     AND   NOT EXISTS (
             SELECT '' Event for this header does not exist''
             FROM xla_events xe
             WHERE xe.application_id = xah.application_id
             AND   xe.event_id = xah.event_id)
     AND   xah.event_type_code NOT IN
             (''MANUAL'', ''REVERSAL'', ''PREPAYMENT APPLICATION ADJ'')
     AND   (xah.upg_batch_id is null OR xah.upg_batch_id = -9999)
     AND   nvl(xah.gl_transfer_status_code, ''X'') <> ''Y''
     AND   nvl(xah.accounting_entry_status_code, ''X'') <> ''F''
     AND   xte.ledger_id = asp.set_of_books_id
     AND   nvl(xte.source_id_int_1, -99) = ac.check_id
     AND   asp.org_id = ac.org_id
     AND   ac.check_id = chks.check_id
     UNION ALL
     SELECT ''EVENT'' orphan_type,
          ''Y'' processed_flag,
          ac.check_id,
          ac.check_number,
          ac.org_id,
          xe.event_id,
          xe.event_status_code,
          xe.process_status_code,
          xah.ae_header_id,
          xte.source_id_int_1 source_id,
          xte.entity_code source_table,
          xe.event_date,
          xe.entity_id,
          xe.event_type_code,
          xe.budgetary_control_flag,
          xe.upg_batch_id
     FROM chks,
          ap_checks_all ac,
          ap_system_parameters_all asp,
          xla_transaction_entities_upg xte,
          xla_events xe,
          xla_ae_headers xah
     WHERE xe.application_id = 200
     AND   xe.event_status_code = ''P''
     AND   xah.application_id = 200
     AND   xah.event_id = xe.event_id
     AND   xte.entity_id = xe.entity_id
     AND   xte.application_id = 200
     AND   xte.entity_code = ''AP_PAYMENTS''
     AND   NOT EXISTS (
             SELECT ''No Inv rows for event'' FROM ap_invoice_distributions_all aid
             WHERE aid.accounting_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No Dists for bc_event_id'' FROM ap_invoice_distributions_all aid
             WHERE aid.bc_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No pmt rows for event'' FROM ap_invoice_payments_all aip
             WHERE aip.accounting_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No pmt hist rows for event'' FROM ap_payment_history_all aph
             WHERE aph.accounting_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No self assessed tax rows for event''
             FROM ap_self_assessed_tax_dist_all asatd
             WHERE asatd.accounting_event_id = xe.event_id)
     AND    NOT EXISTS (
             SELECT ''No self assessed tax rows  for bc_event_id''
             FROM   ap_self_assessed_tax_dist_all asatd
             WHERE  asatd.bc_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No prepay hist rows for event''
             FROM ap_prepay_history_all aprh
             WHERE aprh.accounting_event_id = xe.event_id)
     AND   NOT EXISTS (
             SELECT ''No prepayment hist rows for bc_event_id''
             FROM   ap_prepay_history_all apph
             WHERE  apph.bc_event_id = xe.event_id)
     AND   xe.event_type_code NOT IN
             (''MANUAL'', ''REVERSAL'', ''PREPAYMENT APPLICATION ADJ'')
     AND   (xe.upg_batch_id is null OR xe.upg_batch_id = -9999)
     AND   xte.ledger_id = asp.set_of_books_id
     AND   nvl(xte.source_id_int_1, -99) = ac.check_id
     AND   asp.org_id = ac.org_id
     AND   ac.check_id = chks.check_id
 
)
where rownum<1000
order by check_id',
      p_title                  => 'Payment(s) with Orphan Accounting Event(s)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphan Accounting Events found which have records in the XLA_EVENTS table but are not stamped on any Transaction tables.<br/><strong>Impact Area(s): </strong>Period Close, Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>24692565</br><strong>Note: </strong>[788135/KB157909]</br><strong>Script Name: </strong>ap_Orphan_Events_Sel.sql</br></br>Apply the GDF patch following the instructions provided in [788135/KB157909]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: MU_ORPHAN_ACCTG_EVENTS_PAYMENT');



debug('begin add_signature: MU_ORPHAN_XDL');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols'):= 'ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_amount,
          ai.invoice_currency_code,
          ai.invoice_date,
          xe.event_id,
          xe.event_type_code,
          xe.event_status_code,
          xe.process_status_code,
          xah.ae_header_id,
          xah.gl_transfer_status_code,
          decode(xah.balance_type_code,
            ''A'', ''Actual'',
            ''E'', ''Encumbrance'') balance_type,
          xe.event_date,
          ai.set_of_books_id';
  add_signature(
      p_sig_repo_id            => '22928',
      p_sig_id                 => 'MU_ORPHAN_XDL',
      p_sig_sql                => 'select * from (WITH invs AS (
     SELECT /*+ materialize */ DISTINCT
                invoice_id
            FROM
                ap_invoice_distributions_all
            WHERE
                accounting_date BETWEEN ( trunc(SYSDATE) - 7 ) AND ( trunc(SYSDATE) + 3 )
   )
   SELECT /*+ leading(invs) use_nl(ai, xte, xe, xah, xll, xdl) */
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_amount,
          ai.invoice_currency_code,
          ai.invoice_date,
          xe.event_id,
          xe.event_type_code,
          xe.event_status_code,
          xe.process_status_code,
          xah.ae_header_id,
          xah.gl_transfer_status_code,
          decode(xah.balance_type_code,
            ''A'', ''Actual'',
            ''E'', ''Encumbrance'') balance_type,
          xe.event_date,
          ai.set_of_books_id
   FROM invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_events xe,
        xla_ae_headers xah,
        xla_ae_lines xll,
        xla_distribution_links xdl
   WHERE xe.application_id = 200
   AND   xdl.application_id = 200
   AND   xll.application_id = 200
   AND   xah.application_id = 200
   AND   xte.application_id = 200
   AND   xe.event_status_code = ''P''
   AND   nvl(xe.budgetary_control_flag, ''N'') = ''N''
   AND   xe.event_type_code NOT IN (''PREPAYMENT APPLIED'',
              ''PREPAYMENT UNAPPLIED'',
              ''PREPAYMENT APPLICATION ADJ'')
   AND   xe.event_id = xah.event_id
   AND   xe.entity_id = xte.entity_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.ledger_id = ai.set_of_books_id
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   xah.ae_header_id = xll.ae_header_id
   AND   xah.balance_type_code = ''A''
   AND   (xah.upg_batch_id is null OR
          xah.upg_batch_id = -9999)
   AND   xll.accounting_class_code = ''LIABILITY''
   AND   xdl.ae_header_id = xll.ae_header_id
   AND   xdl.ae_line_num = xll.ae_line_num
   AND   xdl.source_distribution_type LIKE ''AP_INV_DIST''
   AND   xe.event_type_code <> ''MANUAL''
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all AID
           WHERE aid.accounting_event_id = xe.event_id)
   AND   NOT EXISTS (
           SELECT ''inv dist'' FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_distribution_id = xdl.source_distribution_id_num_1
           AND   aid.accounting_event_id = xe.event_id)
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ leading(invs) use_nl(ai, xte, xe, xah, xll, xdl) */
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_amount,
          ai.invoice_currency_code,
          ai.invoice_date,
          xe.event_id,
          xe.event_type_code,
          xe.event_status_code,
          xe.process_status_code,
          xah.ae_header_id,
          xah.gl_transfer_status_code,
          decode(xah.balance_type_code,
            ''A'', ''Actual'',
            ''E'', ''Encumbrance'') balance_type,
          xe.event_date,
          ai.set_of_books_id
   FROM invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_events xe,
        xla_ae_headers xah,
        xla_ae_lines xll,
        xla_distribution_links xdl
   WHERE xe.application_id = 200
   AND   xdl.application_id = 200
   AND   xll.application_id = 200
   AND   xah.application_id = 200
   AND   xte.application_id = 200
   AND   xe.event_status_code = ''P''
   AND   nvl(xe.budgetary_control_flag, ''N'') = ''N''
   AND   xe.event_type_code NOT IN (''PREPAYMENT APPLIED'',
           ''PREPAYMENT UNAPPLIED'', ''PREPAYMENT APPLICATION ADJ'')
   AND   xe.event_id = xah.event_id
   AND   xe.entity_id = xte.entity_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   xah.ae_header_id = xll.ae_header_id
   AND   xah.balance_type_code = ''A''
   AND   (xah.upg_batch_id is null OR xah.upg_batch_id = -9999)
   AND   xll.accounting_class_code = ''SELF_ASSESSED_TAX_LIAB''
   AND   xdl.ae_header_id = xll.ae_header_id
   AND   xdl.ae_line_num = xll.ae_line_num
   AND   xdl.source_distribution_type LIKE ''AP_INV_DIST''
   AND   xe.event_type_code <> ''MANUAL''
   AND   EXISTS (
           SELECT  1 FROM ap_self_assessed_tax_dist_all aid
          WHERE aid.accounting_event_id = xe.event_id)
   AND   NOT EXISTS (
           SELECT ''inv dist'' FROM ap_self_assessed_tax_dist_all aid
           WHERE aid.invoice_distribution_id = xdl.source_distribution_id_num_1
           AND   aid.accounting_event_id = xe.event_id)
   AND   ai.invoice_id = invs.invoice_id)
   where rownum<1000',
      p_title                  => 'Orphan Distribution in Subledger Accounting ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Records in XLA_DISTRIBUTION_LINKS which do not tie back to a valid record in AP_INVOICE_DISTRIBUTIONS_ALL or AP_SELF_ASSESSED_TAX_DISTS_ALL tables .<br/><strong>Impact Area(s): </strong>Accounting Failure, Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>17487602<br/><strong>Note: </strong>[1291521/KB392670]<br/><strong>Script Name: </strong>ap_orphan_xdl_s.sql<br/><br/>Apply the GDF patch following the instructions provided in [1291521/KB392670]<br/><br/><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].<br/>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: MU_ORPHAN_XDL');



debug('begin add_signature: MU_PAYMENTS_POSTINGSTATUSOUTOFSYNCH_W_ACCTGEVENTS');
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Added new cols'):= 'ac.check_id,
                                      ac.check_number,
                                      ac.org_id,
                                      ''AP_INVOICE_PAYMENTS_ALL'' trx_table,
                                      aip.invoice_payment_id   trx_id,
                                      aip.posted_flag,
                                      aip.accrual_posted_flag,
                                      aip.cash_posted_flag,
                                      xe.event_id,
                                      xte.ledger_id            ledger_id';
  add_signature(
      p_sig_repo_id            => '22973',
      p_sig_id                 => 'MU_PAYMENTS_POSTINGSTATUSOUTOFSYNCH_W_ACCTGEVENTS',
      p_sig_sql                => 'select * from (WITH chks AS ( SELECT /*+ materialize */ DISTINCT ph.check_id FROM ap_payment_history_all ph 
WHERE ph.accounting_date BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3) ) SELECT
                                      ac.check_id,
                                      ac.check_number,
                                      ac.org_id,
                                      ''AP_INVOICE_PAYMENTS_ALL'' trx_table,
                                      aip.invoice_payment_id   trx_id,
                                      aip.posted_flag,
                                      aip.accrual_posted_flag,
                                      aip.cash_posted_flag,
                                      xe.event_id,
                                      xte.ledger_id            ledger_id
                                  FROM
                                      chks,
                                      ap_checks_all                  ac,
                                      ap_invoice_payments_all        aip,
                                      xla_events                     xe,
                                      xla_transaction_entities_upg   xte,
                                      gl_ledgers                     gl
                                  WHERE
                                      ( aip.posted_flag = ''N''
                                        OR ( aip.accrual_posted_flag = ''N''
                                             AND nvl(gl.sla_ledger_cash_basis_flag, ''N'') <> ''Y'' ) ) AND aip.set_of_books_id = gl.ledger_id
                                          AND xe.process_status_code = ''P''
                                              AND xe.event_status_code IN (
                                          ''N'',
                                          ''P''
                                      )
                                                  AND ac.check_id = aip.check_id
                                                      AND xe.event_id = aip.accounting_event_id
                                                          AND xte.security_id_int_1 = ac.org_id
                                                              AND xe.entity_id = xte.entity_id
                                                                  AND xe.application_id = xte.application_id
                                                                      AND xe.application_id = 200
                                                                          AND ac.check_id = chks.check_id
                                  UNION ALL
                                  SELECT
                                      ac.check_id,
                                      ac.check_number,
                                      ac.org_id,
                                      ''AP_PAYMENT_HISTORY_ALL'' trx_table,
                                      aph.payment_history_id   trx_id,
                                      aph.posted_flag,
                                      NULL,
                                      NULL,
                                      xe.event_id,
                                      xte.ledger_id            ledger_id
                                  FROM
                                      chks,
                                      ap_checks_all                  ac,
                                      ap_payment_history_all         aph,
                                      xla_events                     xe,
                                      xla_transaction_entities_upg   xte
                                  WHERE
                                      aph.posted_flag <> ''Y''
                                      AND xe.process_status_code = ''P''
                                          AND xe.event_status_code IN (
                                          ''N'',
                                          ''P''
                                      )
                                              AND xte.security_id_int_1 = aph.org_id
                                                  AND xe.event_id = aph.accounting_event_id
                                                      AND ac.check_id = aph.check_id
                                                          AND xe.entity_id = xte.entity_id
                                                              AND xe.application_id = 200
                                                                  AND xte.application_id = 200
                                                                      AND ac.check_id = chks.check_id)
                                                                      where rownum<1000
',
      p_title                  => 'Posted Flags Are Incorrect for Accounted Payments ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Out of Sync Posting Status between the Accounting events in the Events tables and the transaction tables.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close, Sweep',
      p_solution               => '<strong>Solution GDF: </strong>18997220</br><strong>Note: </strong>[1071876/KB207473]</br><strong>Script Name: </strong>ap_incorrect_posted_flag_sel.sql Payments</br></br>Apply the GDF patch following the instructions provided in [1071876/KB207473].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: MU_PAYMENTS_POSTINGSTATUSOUTOFSYNCH_W_ACCTGEVENTS');



debug('begin add_signature: MU_PAYMENTS_W_MISSING_REFERENCES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22931',
      p_sig_id                 => 'MU_PAYMENTS_W_MISSING_REFERENCES',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(aip, ai) */ aip.check_id             correct_check_id,
          aip.org_id               org_id,
          aip.accounting_event_id  inv_pmt_acctg_event_id,
          aip.posted_flag          inv_pmt_posted_flag,
          ac.vendor_id            chk_vendor_id,
          ai.vendor_id             inv_vendor_id,
          ac.vendor_site_code      vendor_site_code,
          ai.vendor_site_id        vendor_site_id,
          ac.check_id              wrong_check_id,
          ac.check_number          wrong_check_number,
          ac.amount                wrong_chk_amount,
          ac.payment_id            wrong_chk_payment_id,
          ac.status_lookup_code    wrong_chk_status,
          ac.currency_code         wrong_chk_currency
FROM (
       SELECT DISTINCT ph.check_id
       FROM ap_payment_history_all ph
       WHERE ph.accounting_date BETWEEN
               (trunc(sysdate) - 7) AND (trunc(sysdate) + 3)
     ) chks,
     ap_invoice_payments_all aip,
     ap_invoices_all ai,
     all_sequences seq,
     ap_checks_all ac,
     ap_payment_history_all aph2
WHERE ai.invoice_id = aip.invoice_id
AND   ai.org_id = aip.org_id
AND   nvl(aip.reversal_flag,''N'') <> ''Y''
AND   NOT EXISTS (
        SELECT 1 FROM ap_checks_all ac1
        WHERE ac1.check_id = aip.check_id)
AND   ac.status_lookup_code NOT IN (''OVERFLOW'',''SET UP'',''SPOILED'')
AND   nvl(aph2.historical_flag,''N'') <> ''Y''
AND   ac.check_id = aph2.check_id(+)
AND   ac.org_id = aip.org_id
AND   ac.vendor_id = ai.vendor_id
AND   ac.vendor_site_id = ai.vendor_site_id
AND   NOT EXISTS (
        SELECT /*+ no_unnest */ 1 FROM ap_invoice_payments_all aip1
        WHERE ac.check_id = aip1.check_id)
AND   ac.creation_date > (
        SELECT MIN(creation_date) FROM ad_bugs
        WHERE aru_release_name = ''R12'')
AND   seq.sequence_name = ''AP_CHECKS_S''
AND   seq.sequence_owner = ''AP''
AND   ac.check_id BETWEEN (aip.check_id - (seq.cache_size + 1)) AND
                          (aip.check_id + (seq.cache_size + 1))
AND   aip.check_id = chks.check_id
  AND rownum<1000',
