debug('begin add_signature: MU_PAYMENT_MULTIPLE_ENTITIES');
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22935',
      p_sig_id                 => 'MU_PAYMENT_MULTIPLE_ENTITIES',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          xte2.application_id,
          xte2.entity_id,
          xte2.ledger_id,
          xte2.entity_code,
  xte2.source_id_int_1,
          xte2.transaction_number
FROM xla_transaction_entities_upg xte2,
     xla_events xe2,
     ap_system_parameters_all asp,
     ap_checks_all ac,
     (
       SELECT DISTINCT ph.check_id
       FROM ap_payment_history_all ph
       WHERE ph.accounting_date BETWEEN
               (trunc(sysdate) - 7) AND (trunc(sysdate) + 3)
     ) chks
WHERE (xte2.application_id, xte2.ledger_id, xte2.entity_code,
       nvl(xte2.source_id_int_1, -99)) IN (
         SELECT xte.application_id ,
                   xte.ledger_id ,
                   xte.entity_code ,
                   xte.source_id_int_1
            FROM xla_transaction_entities_upg xte
            WHERE  xte.application_id =200
         AND    xte.ledger_id = asp.set_of_books_id
         AND    xte.entity_code = ''AP_PAYMENTS''
         AND    nvl(xte.source_id_int_1,-99) = ac.check_id
            GROUP BY xte.application_id, xte.source_id_int_1,
                  xte.entity_code , xte.ledger_id
            HAVING   count(1) > 1)
AND   xe2.application_id(+) = xte2.application_id
AND   xe2.entity_id(+) = xte2.entity_id
AND   asp.org_id = ac.org_id
AND   xte2.ledger_id = asp.set_of_books_id
AND   xte2.application_id = 200
AND   xte2.entity_code = ''AP_PAYMENTS''
AND   nvl(xte2.source_id_int_1, -99) = ac.check_id
AND   ac.check_id = chks.check_id
AND   rownum < 11
order by check_id',
      p_title                  => 'Multiple Entities Created for Payment(s) ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Checks with multiple transaction entity records in SLA.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close, Sweep',
      p_solution               => '<strong>Solution GDF: </strong>9651687</br><strong>Note: </strong>[1133423/KB787666]</br><strong>Script Name: </strong>xla_mulent_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1133423/KB787666].
Note: GDF 9651687 is released for 12.0 & 12.2. GDF patch 21221141 is released for 12.1.',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
