debug('begin add_signature: MU_PAYMENT__ACCTGDATEOUTOFSYNCH');
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22947',
      p_sig_id                 => 'MU_PAYMENT__ACCTGDATEOUTOFSYNCH',
      p_sig_sql                => 'SELECT *
FROM (WITH chks AS ( SELECT /*+ materialize */ DISTINCT ph.check_id FROM ap_payment_history_all ph
WHERE ph.accounting_date BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3) ) 
     SELECT ''Invoice Payment'' record_type,
            ac.check_id,
            ac.check_number,
            ac.org_id,
            to_char(aip.accounting_date, ''DD-MON-YY HH24:MI:SS'') accounting_date,
            to_char(xe.event_date, ''DD-MON-YY HH24:MI:SS'') event_date,
            xe.event_id,
            aip.invoice_payment_id,
            aip.posted_flag
     FROM chks,
          ap_checks_all ac,
          ap_invoice_payments_all aip,
          xla_events xe
     WHERE aip.accounting_event_id = xe.event_id
     AND   xe.application_id = 200
     AND   ac.check_id = aip.check_id
     AND   aip.accounting_DATE <> xe.event_date
     AND   ac.check_id = chks.check_id
     UNION ALL
     SELECT ''Payment History'',
            ac.check_id,
            ac.check_number,
            ac.org_id,
            to_char(aph.accounting_date, ''DD-MON-YY HH24:MI:SS''),
            to_char(xe.event_date, ''DD-MON-YY HH24:MI:SS''),
            xe.event_id,
            aph.payment_history_id,
            aph.posted_flag
     FROM chks,
          ap_checks_all ac,
          ap_payment_history_all aph,
          xla_events xe
     WHERE aph.accounting_event_id = xe.event_id
     AND   ac.check_id = aph.check_id
     AND   xe.application_id = 200
     AND   aph.accounting_date <> xe.event_date
     AND   ac.check_id = chks.check_id)
  where rownum<1000
order by check_id',
      p_title                  => 'Payment with Accounting Dates Out of Sync with the Subledger Tables',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Out of sync accounting date between payment transaction tables and XLA_EVENTS table.<br/><strong>Impact Area(s): </strong>Period Close',
      p_solution               => '<strong>Solution GDF: </strong>26255537</br><strong>Note: </strong>[874904/KB769084]</br><strong>Script Name: </strong>ap_AcctgDateOutOfSynch_sel.sql</br></br>Apply the GDF patch following the instructions provided in [874904/KB769084].',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: MU_PAYMENT__ACCTGDATEOUTOFSYNCH');



debug('begin add_signature: MU_PREPAYMENT_EVENT_NOTGETTINGACCOUNTED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22958',
      p_sig_id                 => 'MU_PREPAYMENT_EVENT_NOTGETTINGACCOUNTED',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(aid ppd) no_merge(iview) */ ai.invoice_id invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_date,
          ai.invoice_amount,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.accounting_event_id event_id,
          aid.posted_flag,
          aid.parent_reversal_id,
          aid.reversal_flag,
          xe.event_type_code,
          ai_prepay.invoice_id   prepay_invoice_id,
          ai_prepay.invoice_num  prepay_invoice_num,
          ai_prepay.invoice_date prepay_invoice_date,
          ail.prepay_line_number prepay_line_number,
          ai.set_of_books_id
FROM ( SELECT DISTINCT invoice_id FROM ap_invoice_distributions_all WHERE accounting_date BETWEEN (trunc(sysdate) - 7) 
AND (trunc(sysdate) + 3) ) invs, ap_invoices_all ai, ap_invoice_lines_all ail, ap_invoice_distributions_all aid, ap_invoice_distributions_all ppd, ap_invoices_all ai_prepay, xla_events xe 
WHERE xe.application_id = 200 AND   xe.event_id = aid.accounting_event_id AND   aid.invoice_line_number = ail.line_number 
AND   aid.invoice_id = ail.invoice_id AND   ail.invoice_id = ai.invoice_id 
AND   aid.prepay_distribution_id = ppd.invoice_distribution_id AND   ppd.invoice_id = ai_prepay.invoice_id 
AND   aid.posted_flag <> ''Y'' AND   xe.event_status_code <> ''P'' 
AND   NOT EXISTS ( SELECT 1 FROM ap_invoice_payments_all aip WHERE aip.invoice_id = ai_prepay.invoice_id 
AND   nvl(aip.reversal_flag, ''N'') <> ''Y'') AND   ai.invoice_id = invs.invoice_id
AND rownum<1000
order by invoice_id',
