debug('begin add_signature: MU_REISSUED_PMT_ACCOUNTED_INCORRECTLY');
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22934',
      p_sig_id                 => 'MU_REISSUED_PMT_ACCOUNTED_INCORRECTLY',
      p_sig_sql                => 'select * from 
(WITH ctrl AS (SELECT DISTINCT aip.check_id FROM 
(SELECT DISTINCT ph.check_id
FROM ap_payment_history_all ph
WHERE ph.accounting_date BETWEEN (trunc(sysdate) - 7) AND (trunc(sysdate) + 3)) chks,
ap_invoice_payments_all aip,
ap_invoice_payments_all aip2,
ap_checks_all ac1
WHERE ac1.void_date is not null
AND ac1.status_lookup_code = ''VOIDED''
AND ac1.check_id = aip2.check_id
AND aip.check_id != aip2.check_id
AND aip2.invoice_id = aip.invoice_id
AND aip.check_id = chks.check_id
)
SELECT /*+ ordered use_nl(ac, aph, xe, xh, xl) */
ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.check_date,
          xe.event_id,
          xe.event_type_code,
          sum(nvl(entered_cr,   0)) - sum(nvl(entered_dr,   0)) acctd_amt,
          ac.amount,
          ''Case 1'' case
FROM ctrl,
ap_checks_all ac,
ap_payment_history_all aph,
xla_events xe,
xla_ae_headers xh,
xla_ae_lines xl,
ap_system_parameters_all asp
WHERE xl.application_id = 200
AND aph.check_id = ac.check_id
AND ac.check_id = ctrl.check_id
AND ac.void_date is null
AND EXISTS (
SELECT 1 FROM ap_invoice_payments_all aip
WHERE aip.check_id = ac.check_id
GROUP BY aip.check_id
HAVING sum(aip.amount) = ac.amount)
AND aph.accounting_event_id = xe.event_id
AND aph.posted_flag = ''Y''
AND xe.event_id = xh.event_id
AND xh.upg_batch_id is null
AND xe.event_type_code IN(''PAYMENT CREATED'', ''REFUND RECORDED'',
''PAYMENT CLEARED'')
AND xe.event_status_code = ''P''
AND xe.application_id = 200
AND xh.application_id = 200
AND xh.ledger_id = asp.set_of_books_id
AND xh.ae_header_id = xl.ae_header_id
AND asp.org_id = ac.org_id
AND xl.accounting_class_code IN(''CASH_CLEARING'', ''CASH'',
''FUTURE_DATED_PMT'')
AND decode(xe.event_type_code,
''PAYMENT CLEARED'',xl.accounting_class_code,
''YES'') != ''CASH''
GROUP BY ac.org_id, ac.check_id, ac.check_date, ac.check_number,
ac.amount, xe.event_id, xe.event_type_code
HAVING abs(abs(sum(nvl(entered_cr,0)) -
sum(nvl(entered_dr,0)) ) - abs(ac.amount)) > 1
UNION ALL
SELECT /*+ ordered use_nl(ac, aph, aphd, xh) */
ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.check_date,
          aph.accounting_event_id,
          aph.transaction_type,
          0 acctd_amt,
          ac.amount,
          ''Case 2''
FROM ctrl,
ap_checks_all ac,
ap_payment_history_all aph,
ap_payment_hist_dists aphd,
xla_ae_headers xh,
ap_system_parameters_all asp
WHERE ac.amount <> 0
AND aph.check_id = ac.check_id
AND ac.check_id = ctrl.check_id
AND ac.void_date is null
AND asp.org_id = ac.org_id
AND aphd.accounting_event_id = aph.accounting_event_id
AND aphd.accounting_event_id = xh.event_id
AND xh.application_id = 200
AND xh.upg_batch_id is null
AND aphd.pay_dist_lookup_code IN( ''CASH'', ''FINAL PAYMENT ROUNDING'')
AND aph.transaction_type IN (''PAYMENT CREATED'',''REFUND RECORDED'')
AND aph.posted_flag = ''Y''
GROUP BY ac.org_id, ac.check_id, ac.check_date,
ac.check_number, ac.amount, aph.accounting_event_id,
aph.transaction_type
HAVING SUM(aphd.invoice_dist_base_amount) = 0)
where rownum<1000
order by check_id',
      p_title                  => 'Reissued Check Accounted Incorrectly ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Reissued Checks accounted with incorrect amounts.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>19367686</br><strong>Note: </strong>[1118703/KB690643]</br><strong>Script Name: </strong>ap_reissue_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1118703/KB690643]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: MU_REISSUED_PMT_ACCOUNTED_INCORRECTLY');



debug('begin add_signature: MU_UNACCOUNTED_EVENTS_W_EVENTDATESINCLOSEDPERIODS');
