debug('begin add_signature: EBS_AP_MU_DUPLICATE_AWT_DISTRIBUTIONS');
   l_info('##MASK##AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25777',
      p_sig_id                 => 'EBS_AP_MU_DUPLICATE_AWT_DISTRIBUTIONS',
      p_sig_sql                => 'WITH invs AS (
     SELECT /*+ materialize */ DISTINCT
                invoice_id
            FROM
                ap_invoice_distributions_all
            WHERE
                accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
   )
   SELECT ''1-A'' category,
          aid.invoice_id,
          aid.org_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.invoice_distribution_id,
          aid.accounting_event_id,
          aid.posted_flag,
          aid.parent_reversal_id
   FROM invs,
        ap_invoice_distributions_all aid,
        ap_invoice_lines_all ail,
        ap_system_parameters_all asp
   WHERE aid.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.awt_flag = ''A''
   AND   aid.historical_flag is null
   AND   aid.org_id = asp.org_id
   AND   ail.invoice_id = aid.invoice_id
   AND   ail.line_number = aid.invoice_line_number
   AND   asp.create_awt_dists_type = ''PAYMENT''
   AND   aid.awt_invoice_payment_id is null
   AND   NOT EXISTS (
           SELECT ''Invoice already withheld by AutoApproval''
           FROM ap_invoices_all ai
           WHERE ai.invoice_id = aid.invoice_id
           AND   nvl(ai.awt_flag, ''N'') = ''Y'')
   AND   EXISTS (
           SELECT 1 FROM fnd_product_installations pi
           WHERE  pi.application_id = 200
           AND substr(pi.patch_level, 8, 1) = ''A'')
   UNION ALL
   SELECT ''1-B'' category,
          aid.invoice_id,
          aid.org_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.invoice_distribution_id,
          aid.accounting_event_id,
          aid.posted_flag,
          aid.parent_reversal_id
   FROM invs,
        ap_invoice_distributions_all aid,
        ap_invoice_lines_all ail,
        ap_system_parameters_all asp
   WHERE aid.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.awt_flag = ''A''
   AND   aid.historical_flag is null
   AND   aid.org_id = asp.org_id
   AND   ail.invoice_id = aid.invoice_id
   AND   ail.line_number = aid.invoice_line_number
   AND   asp.create_awt_dists_type = ''PAYMENT''
   AND   ail.awt_group_id is not null
   AND   ail.pay_awt_group_id is null
   AND   NOT EXISTS (
           SELECT ''Invoice already withheld by AutoApproval''
           FROM ap_invoices_all ai
           WHERE ai.invoice_id = aid.invoice_id
           AND   nvl(ai.awt_flag, ''N'') = ''Y'')
   AND   EXISTS (
           SELECT 1 FROM fnd_product_installations pi
           WHERE  pi.application_id = 200
           AND   substr(pi.patch_level, 8, 1) <> ''A'')
   UNION ALL
   SELECT ''2-B'',
          aid.invoice_id,
          aid.org_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.invoice_distribution_id,
          aid.accounting_event_id,
          aid.posted_flag,
          aid.parent_reversal_id
   FROM invs,
        ap_invoice_distributions_all aid,
        ap_system_parameters_all asp,
        ap_invoice_lines_all ail
   WHERE aid.line_type_lookup_code = ''AWT''
   AND   aid.awt_flag = ''A''
   AND   aid.awt_invoice_payment_id is null
   AND   aid.historical_flag is null
   AND   aid.org_id = asp.org_id
   AND   aid.invoice_id = ail.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   asp.create_awt_dists_type = ''PAYMENT''
   AND   ail.awt_group_id is null
   AND   ail.pay_awt_group_id is not null
   AND   NOT EXISTS (
           SELECT ''Invoice already withheld by AutoApproval''
           FROM ap_invoices_all ai
           WHERE ai.invoice_id = aid.invoice_id
           AND   nvl(ai.awt_flag, ''N'') = ''Y'')
   AND   aid.invoice_id = invs.invoice_id
   AND ROWNUM<1000
   ORDER BY invoice_id DESC',
      p_title                  => 'Invoices with Duplicate AWT Distributions',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices with duplicate AWT distributions created during payment with Payment Process Request (PPR)<br/><strong>Impact Area(s): </strong>Automatic Witholding Tax, Period Close
',
      p_solution               => '<strong>Solution GDF: </strong>17311645</br><strong>Note: </strong>[1188825/KB764574]</br><strong>Script Name: </strong>AP_DUP_PMT_AWT_DISTS_SEL.sql Duplicate Dists</br></br>Apply the GDF patch following the instructions provided in [1188825/KB764574]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_DUPLICATE_AWT_DISTRIBUTIONS');



debug('begin add_signature: EBS_AP_MU_FAIL_TO_ACCOUNT_SECONDARY_LEDGER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25738',
      p_sig_id                 => 'EBS_AP_MU_FAIL_TO_ACCOUNT_SECONDARY_LEDGER',
      p_sig_sql                => 'SELECT ai.invoice_id,
       ai.invoice_num,
       xah.ae_header_id,
       xah.ledger_id,
       xah.entity_id,
       xah.event_type_code,
       xah.accounting_date,
       xah.gl_transfer_status_code,
       xah.je_category_name,
       xah.accounting_entry_status_code,
       xah.accounting_entry_type_code,
       xah.accounting_batch_id,
       xah.balance_type_code,
       xah.period_name,
       xah.group_id,
       xah.upg_batch_id,
       xah.request_id
FROM (
       SELECT /*+ materialize */ DISTINCT
                invoice_id
            FROM
                ap_invoice_distributions_all
            WHERE
                accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
     ) invs,
     ap_invoices_all ai,
     xla.xla_transaction_entities xte,
     xla_ae_headers xah
WHERE ai.invoice_id = invs.invoice_id
AND   xte.ledger_id = ai.set_of_books_id
AND   xte.entity_code = ''AP_INVOICES''
AND   nvl(xte.source_id_int_1,-99) = ai.invoice_id
AND   xah.application_id = 200
AND   xte.application_id = 200
AND   xah.entity_id = xte.entity_id
AND   xah.accounting_batch_id is null
AND   xah.upg_source_application_id = -602
AND   xah.accounting_entry_status_code = ''F''
AND   xah.ledger_id IN (
        SELECT DISTINCT gl.ledger_id
        FROM gl_ledgers gl,
             gl_ledger_relationships glr1,
             gl_ledger_relationships glr2,
             gl_ledger_relationships glr3
        WHERE glr3.source_ledger_id = ai.set_of_books_id
        AND   glr3.source_ledger_id = glr2.primary_ledger_id
        AND   glr2.target_ledger_id = glr1.primary_ledger_id
        AND   gl.ledger_id = glr1.source_ledger_id
        AND   gl.ledger_category_code ! = ''PRIMARY'')
AND   EXISTS (
        SELECT 1 FROM xla_distribution_links xdl
        WHERE xdl.application_id = 200
        AND   xdl.ae_header_id = xah.ae_header_id
        AND   xdl.event_id = xah.event_id
        AND   nvl(xdl.calculate_acctd_amts_flag,''N'') = ''N'')
and rownum<1000
order by invoice_id',
      p_title                  => 'Transactions Fail to Account in the Secondary Ledger',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transactions fail to account in the secondary ledger, giving the error "Subledger Journal Entry Does Not Balance In Entered Currency"<br/><strong>Impact Area(s): </strong>Accounting Failure, Accounting Incorrect
',
      p_solution               => '<strong>Bug Number: </strong>20961688</br><strong>Note: </strong>[2009919/KB793807]</br><strong>Script Name: </strong>None</br></br>Apply the code fix patch {12329205} and log an SR to request the data fix from [2009919/KB793807]
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_FAIL_TO_ACCOUNT_SECONDARY_LEDGER');



debug('begin add_signature: EBS_AP_MU_INCORRECT_AWT_ACCOUNTING');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25728',
      p_sig_id                 => 'EBS_AP_MU_INCORRECT_AWT_ACCOUNTING',
      p_sig_sql                => 'SELECT aip.check_id,
          aip.invoice_id,
          ai.invoice_num,
          ai.set_of_books_id,
          ai.payment_status_flag,
          ai.invoice_currency_code,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.amount,
          aid.base_amount
   FROM (
          SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        ) chks,
        ap_checks_all ac,
        ap_invoice_payments_all aip,
        ap_invoice_distributions_all aid,
        ap_invoices_all ai,
        po_vendors pov,
        gl_ledgers gl,
        fnd_currencies fc_b,
        fnd_currencies fc_i
   WHERE ac.check_id = chks.check_id
   AND   aid.invoice_id = ai.invoice_id
   AND   ai.invoice_id = aip.invoice_id
   AND   ai.set_of_books_id = gl.ledger_id
   AND   aip.check_id = ac.check_id
   AND   pov.vendor_id = ac.vendor_id
   AND   pov.vendor_id = ai.vendor_id
   AND   trunc(ai.creation_date)  >= (
           SELECT min(trunc(creation_date)) FROM ad_applied_patches
           WHERE patch_type=''MAINTENANCE-PACK''
           AND   maint_pack_level LIKE ''12.%'' )
   AND   ai.payment_status_flag = ''Y''
   AND   nvl(ai.historical_flag, ''N'') = ''N''
   AND   gl.currency_code = fc_b.currency_code
   AND   fc_i.currency_code = ai.invoice_currency_code
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.base_amount <> round( aid.amount * ai.exchange_rate, fc_b.precision )
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.prepay_distribution_id is not null)
   AND   aid.base_amount <> (
           SELECT sum(aphd.invoice_dist_base_amount)
           FROM ap_invoice_payments_all aip,
                ap_payment_hist_dists aphd
           WHERE aphd.accounting_event_id = aip.accounting_event_id
           AND   aip.amount > 0
           AND   aip.invoice_id = aid.invoice_id
           AND   aphd.invoice_payment_id = aip.invoice_payment_id
           AND   aphd.invoice_distribution_id = aid.invoice_distribution_id
           AND   aphd.pay_dist_lookup_code = ''AWT'')
           AND  ROWNUM <1000
ORDER BY    check_id',
      p_title                  => 'Payment Accounting Does Not Fully Relieve the Liability for Foreign Currency Invoices with Withholding',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment accounting does not fully relieve the liability for foreign currency invoices with withholding.<br/><strong>Impact Area(s): </strong>Accounting Incorrect, Automatic Witholding Tax, Trial Balance
',
      p_solution               => '<strong>Solution GDF: </strong>18818008</br><strong>Note: </strong>[1920640/KB291807]</br><strong>Script Name: </strong>ap_x_prorate_due_to_awt_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1920640/KB291807]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_INCORRECT_AWT_ACCOUNTING');



debug('begin add_signature: EBS_AP_MU_INCORRECT_CHECKS');
   l_info('##MASK##AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##BASE_AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25733',
      p_sig_id                 => 'EBS_AP_MU_INCORRECT_CHECKS',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.checkrun_name,
          ac.payment_type_flag,
          ac.amount,
          ac.currency_code,
          ac.exchange_rate_type,
          ac.exchange_date,
          ac.exchange_rate,
          ac.check_date,
          ac.base_amount
   FROM (
           SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        ) chks,
        ap_checks_all ac,
        ap_payment_history_all aph
   WHERE ac.check_id = chks.check_id
   AND   ac.check_id = aph.check_id
   AND   aph.posted_flag != ''Y''
   AND   ac.payment_type_flag != ''A''
   AND   ac. status_lookup_code <> ''VOIDED''
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_payments_all aip
           WHERE aip.check_id = ac.check_id)
   AND   NOT EXISTS (
           SELECT 1
           FROM ap_checks_all ac1,
                ap_payment_history_all aph1
           WHERE ac1.check_id = ac.check_id
           AND   ac1.payment_id is null
           AND   ac1.status_lookup_code NOT IN (''OVERFLOW'',''SET UP'',''SPOILED'')
           AND   ac1.check_id = aph1.check_id
           AND   nvl(aph1.historical_flag,''N'') != ''Y''
           AND   aph1.posted_flag != ''Y''
           AND   NOT EXISTS (
                   SELECT 1 FROM ap_invoice_payments_all aip
                   WHERE aip.check_id = ac.check_id)
           AND   EXISTS (
                   SELECT 1
                   FROM ap_invoice_payments_all aip2,
                        ap_checks_all ac2
                   WHERE aip2.check_id = ac2.check_id
                   AND   ac1.org_id = ac2.org_id
                   AND   ac1.check_number = ac2.check_number
                   AND   ((ac1.vendor_id = ac2.vendor_id AND
                           ac1.vendor_site_id = ac2.vendor_site_id) OR
                          ac1.payment_document_id =ac2.payment_document_id)))
AND ROWNUM<1000
ORDER BY CHECK_ID',
      p_title                  => 'Checks with No Corresponding Invoice Payment Records',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Checks with no corresponding invoice payment records<br/><strong>Impact Area(s): </strong>Payment Data, Period Close',
      p_solution               => '<strong>Solution GDF: </strong>22873624</br><strong>Note: </strong>[2115968/KB778253]</br><strong>Script Name: </strong>ap_incorrect_checks_sel.sql Case 3</br></br>Apply the GDF patch following the instructions provided in [2115968/KB778253].
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_INCORRECT_CHECKS');



debug('begin add_signature: EBS_AP_MU_INCORRECT_MANUAL_PMT_ADJ');
   l_info('##MASK##AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##CLEARED_AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25781',
      p_sig_id                 => 'EBS_AP_MU_INCORRECT_MANUAL_PMT_ADJ',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.check_date,
          ac.amount,
          ac.vendor_id,
          ac.status_lookup_code,
          ac.org_id,
          ac.cleared_amount,
          ac.cleared_date,
          pay_v.accounting_event_id,
          CASE ac.status_lookup_code
            WHEN ''VOIDED''
              THEN ''No manual action required''
            WHEN ''RECONCILED''
              THEN ''UNCLEAR Check, VOID Check''
            WHEN ''RECONCILED UNACCOUNTED''
              THEN ''UNCLEAR Check, VOID Check''
            WHEN ''CLEARED BUT UNACCOUNTED''
              THEN ''UNCLEAR Check, VOID Check''
            WHEN ''CLEARED''
              THEN ''UNCLEAR Check, VOID Check''
            WHEN ''NEGOTIABLE''
              THEN ''VOID Check''
          END "Pre-Fix Actions"
   FROM ap_checks_all ac,
        (
          SELECT /*+ leading(chks) */
                 aph.check_id,
                 aph.accounting_event_id
          FROM (
                 SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
               ) chks,
               ap_payment_history_all aph,
               ap_invoice_payments_all aip
          WHERE aph.check_id = chks.check_id
          AND   aph.check_id = aip.check_id
          AND   aph.accounting_event_id = aip.accounting_event_id
          AND   aph.transaction_type IN (''MANUAL PAYMENT ADJUSTED'',
                  ''REFUND ADJUSTED'')
          AND   NOT EXISTS (
                  SELECT 1 FROM ap_invoice_payments_all aip2
                  WHERE aip2.accounting_event_id = aph.accounting_event_id
                  AND   aip2.check_id = aph.check_id
                  AND   (aip2.reversal_flag <> ''Y'' OR
                         aip2.reversal_inv_pmt_id is null))
         GROUP BY aph.check_id, aph.accounting_event_id
         HAVING SUM(aip.amount) <> 0
        ) pay_v
   WHERE ac.check_id = pay_v.check_id
   AND ROWNUM<1000',
      p_title                  => 'Incorrect Manual Payment Adjustment Events',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incorrect manual payment adjustment events resulting from reversing invoices in a payment to do a manual payment adjustment but not adding in invoices to balance the payment amount.<br/><strong>Impact Area(s): </strong>Accounting Incorrect
',
      p_solution               => '<strong>Solution GDF: </strong>17811729</br><strong>Note: </strong>[1573926/KB731104]</br><strong>Script Name: </strong>ap_man_pay_adj_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1573926/KB731104]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_INCORRECT_MANUAL_PMT_ADJ');



debug('begin add_signature: EBS_AP_MU_INCORRECT_PAYMENT_CLEARING_EVENT');
   l_info('##MASK##BASE_AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##CLEARED_BASE_AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##DIST_CLEARED_BASE_AMT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25775',
      p_sig_id                 => 'EBS_AP_MU_INCORRECT_PAYMENT_CLEARING_EVENT',
      p_sig_sql                => 'SELECT DISTINCT
          ac.check_id,
          aph.accounting_event_id,
          ac.base_amount,
          ac.cleared_base_amount,
          ac.cleared_charges_base_amount,
          aphd.cleared_base_amount dist_cleared_base_amt
   FROM (
          SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        ) chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        ap_payment_hist_dists aphd,
        ap_system_parameters_all asp,
        xla_ae_headers h
   WHERE ac.check_id = chks.check_id
   AND   ac.check_id = aph.check_id
   AND   aph.transaction_type LIKE ''PAYMENT CLEARING%''
   AND   aph.posted_flag = ''Y''
   AND   aph.bank_currency_code != aph.pmt_currency_code
   AND   aph.org_id = asp.org_id
   AND   aph.bank_currency_code = asp.base_currency_code
   AND   aph.accounting_event_id = h.event_id
   AND   h.application_id = 200
   AND   h.upg_batch_id is null
   AND   h.ledger_id = asp.set_of_books_id
   AND   aphd.payment_history_id = aph.payment_history_id
   AND   aphd.accounting_event_id = aph.accounting_event_id
   AND   aphd.pay_dist_lookup_code = ''FINAL CASH ROUNDING''
   AND   ac.cleared_base_amount is not null
   AND   ac.void_date is null
   AND   ((0.05 > abs(abs(aphd.cleared_base_amount)
             - abs(ac.base_amount - ac.cleared_base_amount
             + nvl(ac.cleared_charges_base_amount, 0)))) OR
          (ac.cleared_charges_base_amount > 0 AND
           (0.05 > (abs(aphd.cleared_base_amount)
              - ac.cleared_charges_base_amount))))',
      p_title                  => 'Payment Clearing Events with Large Final Cash Rounding Lines',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment clearing events with large Final Cash rounding lines causing incorrect accounting.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>13652773</br><strong>Note: </strong>[2004116/KB828328]</br><strong>Script Name: </strong>ap_pay_clear_x_fcr_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2004116/KB828328]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_INCORRECT_PAYMENT_CLEARING_EVENT');



debug('begin add_signature: EBS_AP_MU_INCORRECT_PMT_ADJUSTED_ACCOUNT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25732',
      p_sig_id                 => 'EBS_AP_MU_INCORRECT_PMT_ADJUSTED_ACCOUNT',
      p_sig_sql                => 'SELECT /*+ leading(chks) */ DISTINCT
          aph.check_id,
          aph.related_event_id,
          aip.invoice_id,
          aip.invoice_payment_id,
          aphd.all_inv_dist_base_sum,
          aip.invoice_base_amount,
          aip.amount,
          nvl( aip.invoice_base_amount, aip.amount ) -
            aphd.all_inv_dist_base_sum trx_amt_different,
          aph.posted_flag
   FROM (
         SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        ) chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        ap_invoice_payments_all aip,
        (
          SELECT sum(nvl(aphd1.invoice_dist_base_amount,
                   aphd1.invoice_dist_amount)) all_inv_dist_base_sum,
                 sum(decode(aph1.accounting_event_id,
                       aph1.related_event_id, nvl(aphd1.invoice_dist_base_amount,
                         aphd1.invoice_dist_amount ),
                       0)) pay_cr_inv_dist_sum,
                 aph1.check_id,
                 aph1.related_event_id,
                 aphd1.invoice_payment_id
          FROM ap_payment_hist_dists aphd1,
               ap_payment_history_all aph1
          WHERE aph1.accounting_event_id = aphd1.accounting_event_id
          AND   aphd1.payment_history_id = aph1.payment_history_id
          AND   aph1.transaction_type NOT IN (''MANUAL PAYMENT ADJUSTED'',
                    ''MANUAL REFUND ADJUSTED'')
          AND   aphd1.pay_dist_lookup_code IN (''CASH'')
          GROUP BY aph1.check_id, aph1.related_event_id, aphd1.invoice_payment_id
        ) aphd
   WHERE ac.check_id = chks.check_id
   AND   ac.check_id = aph.check_id
   AND   aph.check_id = aip.check_id
   AND   ac.void_date is null
   AND   aph.transaction_type IN (''PAYMENT ADJUSTED'', ''REFUND ADJUSTED'')
   AND   nvl(aph.historical_flag, ''N'') <> ''Y''
   AND   aph.posted_flag = ''Y''
   AND   aip.posted_flag = ''Y''
   AND   aph.check_id = aphd.check_id
   AND   aph.related_event_id = aphd.related_event_id
   AND   aip.invoice_payment_id = aphd.invoice_payment_id
   AND   aphd.all_inv_dist_base_sum <> nvl(aip.invoice_base_amount, aip.amount)
   AND   aphd.pay_cr_inv_dist_sum = nvl(aip.invoice_base_amount, aip.amount)
   AND   NOT EXISTS (
           SELECT ''unacct pay adj event'' FROM ap_payment_history_all aph2
           WHERE aph2.related_event_id = aph.related_event_id
           AND   aph2.check_id = aph.check_id
           AND   (aph2.posted_flag = ''N'' OR
                  nvl(aph2.historical_flag, ''x'') = ''Y''))
   AND   NOT EXISTS (
           SELECT ''unaccounted dist'' FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = aip.invoice_id
           AND   nvl(aid.posted_flag, ''N'') = ''N'')
   AND   NOT EXISTS (
           SELECT ''payment voided'' FROM ap_checks_all ac1
           WHERE ac1.check_id = aph.check_id
           AND   ac1.void_date is not null)
   AND   NOT EXISTS (
           SELECT ''inv payment reversed'' FROM ap_invoice_payments_all aip1
           WHERE aip1.invoice_payment_id = aip.invoice_payment_id
           AND nvl(aip1.reversal_flag,''N'') = ''Y'')
AND ROWNUM<1000
ORDER BY CHECK_ID',
      p_title                  => 'Payment Adjustment Events Are Accounted with Incorrect Amounts',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment adjustment events are accounted with incorrect amounts resulting in issues with the trial balance.<br/><strong>Impact Area(s): </strong>Accounting Incorrect, Trial Balance
',
      p_solution               => '<strong>Solution GDF: </strong>20514802</br><strong>Note: </strong>[2632103/KB720133]</br><strong>Script Name: </strong>ap_x_pay_adj_acctg_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2632103/KB720133].</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_INCORRECT_PMT_ADJUSTED_ACCOUNT');



debug('begin add_signature: EBS_AP_MU_INCORRECT_PMT_CLEARING_ACCOUNTING');
   l_info('##MASK##CLEARED_BASE_AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##CLR_BASE_AMT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25731',
      p_sig_id                 => 'EBS_AP_MU_INCORRECT_PMT_CLEARING_ACCOUNTING',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.cleared_base_amount,
          aphd.clr_base_amt
   FROM (
          SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        ) chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        (
          SELECT sum(aphd.cleared_base_amount) clr_base_amt,
                 aph.check_id
          FROM ap_payment_hist_dists aphd,
               ap_payment_history_all aph
          WHERE aphd.accounting_event_id = aph.accounting_event_id
          AND   aphd.payment_history_id = aph.payment_history_id
          AND   aph.transaction_type IN (''PAYMENT CLEARING'',
                  ''PAYMENT CLEARING ADJUSTED'')
          AND   NOT EXISTS (
                  SELECT ''unaccounted payment''
                  FROM ap_payment_history_all aph1
                  WHERE aph1.check_id = aph.check_id
                  AND aph1.related_event_id = aph.related_event_id
                  AND aph1.transaction_type = ''PAYMENT UNCLEARING'')
          AND   aphd.pay_dist_lookup_code IN (''CASH'', ''FINAL CASH ROUNDING'',
                  ''BANK CHARGE'', ''BANK ERROR'')
          GROUP BY aph.check_id
        ) aphd
   WHERE ac.check_id = chks.check_id
   AND   ac.void_date is null
   AND   ac.check_id = aph.check_id
   AND   ac.cleared_base_amount is not null
   AND   NOT EXISTS (
           SELECT ''unaccounted payment'' FROM ap_payment_history_all aph1
           WHERE aph1.check_id = ac.check_id
           AND  (nvl( aph1.historical_flag, ''N'') = ''Y'' OR
                 aph1.posted_flag = ''N''))
   AND   ac.cleared_base_amount <> aphd.clr_base_amt
   AND   ac.check_id = aphd.check_id
   AND ROWNUM<1000
ORDER BY check_id
',
      p_title                  => 'Payment Clearing Events Are Accounted with Incorrect Amounts',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment clearing events are accounted with incorrect amounts, causing differences between the cleared base amount and the accounted cash amount.<br/><strong>Impact Area(s): </strong>Accounting Incorrect
',
      p_solution               => '<strong>Solution GDF: </strong>22724558</br><strong>Note: </strong>[2632110/KB781623]</br><strong>Script Name: </strong>ap_x_cash_pay_clr_sel.sq</br></br>Apply the GDF patch following the instructions provided in [2632110/KB781623].</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_INCORRECT_PMT_CLEARING_ACCOUNTING');



debug('begin add_signature: EBS_AP_MU_INVALID_PMTS_CASCADE_EVENTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25782',
      p_sig_id                 => 'EBS_AP_MU_INVALID_PMTS_CASCADE_EVENTS',
      p_sig_sql                => 'SELECT aph.check_id,
          aph.org_id,
          aph.transaction_type,
          aph.payment_history_id,
          aph.related_event_id,
          aph.accounting_event_id,
          aph.invoice_adjustment_event_id,
          aph.accounting_date
   FROM ap_payment_history_all aph,
        xla_events xe,
        (
          SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        ) chks
   WHERE aph.transaction_type LIKE ''%ADJUSTED''
   AND   nvl(aph.posted_flag,   ''N'') <> ''Y''
   AND   aph.transaction_type <> ''MANUAL PAYMENT ADJUSTED''
   AND   xe.event_id = aph.accounting_event_id
   AND   xe.event_status_code <> ''P''
   AND   xe.application_id = 200
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.accounting_event_id = aph.invoice_adjustment_event_id
           AND   aid.line_type_lookup_code != ''AWT'')
   AND   aph.check_id = chks.check_id
   AND ROWNUM<1000
   ORDER BY check_id DESC
