debug('begin add_signature: EBS_AP_MU_INVALID_PREPAY_DISTS');
   l_info('##MASK##ACCTOUNTED_AMT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##PAID_AMT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25735',
      p_sig_id                 => 'EBS_AP_MU_INVALID_PREPAY_DISTS',
      p_sig_sql                => 'SELECT aip.check_id,
       aip.invoice_id,
       aip.invoice_payment_id,
       sum(aip.amount) paid_amt,
       sum(aph.amount) acctounted_amt
FROM (
        SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
     ) chks,
     ap_invoice_payments_all aip,
     ap_payment_hist_dists aph
WHERE aip.check_id = chks.check_id
AND   aip.invoice_payment_id = aph.invoice_payment_id
AND   aip.posted_flag = ''Y''
AND   aph.pay_dist_lookup_code = ''CASH''
AND   EXISTS (
        SELECT 1 FROM ap_prepay_app_dists apad
        WHERE apad.prepay_dist_lookup_code = ''PREPAY APPL''
        AND   apad.invoice_distribution_id = aph.invoice_distribution_id)
GROUP BY aip.check_id,aip.invoice_id,aip.invoice_payment_id
HAVING sum(aip.amount) <> sum(aph.amount)
order by check_id',
      p_title                  => 'Payment Accounting Is Incorrect Due to Invalid Data in the Prepayment Application Distributions Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Tax distributions created during prepay application/unapplication with missing PREPAY_DISTRIBUTION_ID values<br/><strong>Impact Area(s): </strong>Accounting Incorrect
',
      p_solution               => '<strong>Note: </strong>[2665666/KB782861]</br><strong>Script Name: </strong>None</br></br>Apply the root cause fix for the issue following the instructions in [1394302/KB340888] if you have not done so, and log a service request to obtain the data fix as described in [2665666/KB782861]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
