debug('begin add_signature: EBS_AP_MU_INVOICES_NOT_ENCUMBERED');
   l_info('##MASK##AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##BASE_AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25776',
      p_sig_id                 => 'EBS_AP_MU_INVOICES_NOT_ENCUMBERED',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount,
          aid.invoice_distribution_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.base_amount,
          aid.line_type_lookup_code,
          aid.match_status_flag,
          aid.bc_event_id,
          aid.accounting_event_id,
          aid.encumbered_flag,
          aid.posted_flag,
          ai.cancelled_date,
          aid.org_id,
          aid.set_of_books_id
   FROM (
           SELECT /*+ materialize */ DISTINCT
                invoice_id
            FROM
                ap_invoice_distributions_all
            WHERE
                accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        ) invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        po_distributions_all pod,
        po_line_locations_all pll,
        financials_system_params_all fsp
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.invoice_id = ai.invoice_id
   AND   ai.org_id = fsp.org_id
   AND   fsp.purch_encumbrance_flag = ''Y''
   AND   aid.po_distribution_id = pod.po_distribution_id(+)
   AND   pod.line_location_id = pll.line_location_id(+)
   AND   aid.amount <> 0
   AND   aid.line_type_lookup_code <> ''REC_TAX''
   AND   (aid.po_distribution_id is null OR
          nvl(pll.accrue_on_receipt_flag, ''N'') = ''N'')
   AND   aid.match_status_flag = ''A''
   AND   NOT EXISTS (
           SELECT 1 FROM xla_events xe
           WHERE xe.event_id = aid.bc_event_id
           AND   xe.application_id = 200
           AND   xe.event_status_code = ''P''
           AND   xe.process_status_code = ''P'')
   AND   NOT EXISTS (
           SELECT 1 FROM ap_encumbrance_lines_all ael
           WHERE ael.invoice_distribution_id = aid.invoice_distribution_id
           AND   aid.encumbered_flag = ''Y'')
   AND   EXISTS (
           SELECT 1 FROM ap_holds_all aha
           WHERE aha.invoice_id = ai.invoice_id
           AND   aha.hold_lookup_code = ''Encumbrance Acctg Fail''
           AND   aha.release_lookup_code is not null
           AND   aha.release_lookup_code <> ''Encumbrance Acctg Ok''
           UNION
           SELECT 1
           FROM ap_holds_all aha,
                ap_hold_codes ahc
           WHERE aha.invoice_id = ai.invoice_id
           AND   aha.hold_lookup_code = ''Encumbrance Acctg Fail''
           AND   aha.release_lookup_code is null
           AND   aha.hold_lookup_code = ahc.hold_lookup_code
           AND   ahc.postable_flag = ''Y'')
           AND ROWNUM<1000
ORDER BY ai.invoice_id DESC',
      p_title                  => 'Invoices Which Have Not Been Encumbered Because the Encumbrance Accounting Hold Was Released Manually',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices which have not been encumbered because the encumbrance accounting hold was released manually.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>20312904</br><strong>Note: </strong>[2632112/KB779171]</br><strong>Script Name: </strong>ap_unenc_inv_rel_hold_sel.sql</br></br>Follow the instructions as detailed in  [2632112/KB779171] to download the data fix script.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_INVOICES_NOT_ENCUMBERED');



debug('begin add_signature: EBS_AP_MU_MISSING_PREPAY_DISTRIBUTION_ID');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25739',
      p_sig_id                 => 'EBS_AP_MU_MISSING_PREPAY_DISTRIBUTION_ID',
      p_sig_sql                => 'WITH invs AS (
     SELECT /*+ materialize */ DISTINCT
                invoice_id
            FROM
                ap_invoice_distributions_all
            WHERE
                accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        )
   
   SELECT 1 corruption_type,
          aid_tax.invoice_id,
          aid_tax.invoice_distribution_id,
          aid_tax.parent_reversal_id,
          null corr_prepay_dist_id,
          null prepaytax_acctg_event_id,
          null prepaytax_bc_event_id,
          null prepay_acctg_event_id,
          null prepay_bc_event_id
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid_tax,
        ap_invoice_distributions_all aid_prepay
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid_tax.charge_applicable_to_dist_id = aid_prepay.invoice_distribution_id
   AND   aid_tax.invoice_id = aid_prepay.invoice_id
   AND   ai.invoice_id = aid_tax.invoice_id
   AND   ai.historical_flag = ''Y''
   AND   aid_tax.prepay_distribution_id is null
   AND   aid_prepay.line_type_lookup_code = ''PREPAY''
   AND   aid_tax.line_type_lookup_code IN (''REC_TAX'', ''NONREC_TAX'')
   AND   aid_tax.prepay_tax_parent_id is not null
   AND   aid_tax.historical_flag = ''Y''
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid_sub
           WHERE aid_sub.invoice_id = ai.invoice_id
           AND   nvl(aid_sub.historical_flag,''N'') = ''N''
           UNION ALL
           SELECT 1
           FROM ap_invoice_distributions_all aid_sub,
                xla_events xe_sub,
                ap_accounting_events_all aae_sub
           WHERE aid_sub.accounting_event_id = xe_sub.event_id
           AND   xe_sub.event_id = aae_sub.accounting_event_id
           AND   xe_sub.upg_batch_id = -9999
           AND   aid_sub.invoice_id = ai.invoice_id
           UNION ALL
           SELECT 1 FROM ap_invoice_payments_all aip_sub,
                  ap_payment_history_all aph_sub,
                  xla_events xe_sub,
                  ap_accounting_events_all aae_sub
          WHERE aip_sub.invoice_id = ai.invoice_id
          AND   aip_sub.check_id = aph_sub.check_id
          AND   aph_sub.accounting_event_id = xe_sub.event_id
          AND   xe_sub.application_id = 200
          AND   xe_sub.event_id = aae_sub.accounting_event_id
          AND   xe_sub.upg_batch_id = -9999
          UNION ALL
          SELECT 1
          FROM ap_invoice_distributions_all aid_sub,
               xla_events xe_sub,
               xla_ae_headers xah_sub
          WHERE aid_sub.invoice_id = ai.invoice_id
          AND   aid_sub.accounting_event_id = xe_sub.event_id
          AND   xe_sub.application_id = 200
          AND   xe_sub.event_id = xah_sub.event_id
          AND   xah_sub.application_id = 200
          AND   xah_sub.upg_batch_id  is null
          UNION ALL
          SELECT 1
          FROM ap_invoice_payments_all aip_sub,
               ap_payment_history_all aph_sub,
               xla_events xe_sub,
               xla_ae_headers xah_sub
          WHERE aip_sub.invoice_id = ai.invoice_id
          AND   aip_sub.check_id = aph_sub.check_id
          AND   aph_sub.accounting_event_id = xe_sub.event_id
          AND   xe_sub.application_id = 200
          AND   xe_sub.event_id = xah_sub.event_id
          AND   xah_sub.application_id = 200
          AND   xah_sub.upg_batch_id is null)
   UNION ALL
   SELECT 2,
          aid_taxrev.invoice_id,
          aid_taxrev.invoice_distribution_id,
          aid_taxrev.parent_reversal_id,
          aid_tax.prepay_distribution_id corr_prepay_dist_id,
          aid_taxrev.accounting_event_id prepaytax_acctg_event_id,
          aid_taxrev.bc_event_id prepaytax_bc_event_id,
          aid_prepay.accounting_event_id prepay_acctg_event_id,
          aid_prepay.bc_event_id prepay_bc_event_id
   FROM invs,
        ap_invoice_distributions_all aid_taxrev,
        ap_invoice_distributions_all aid_tax,
        ap_invoice_distributions_all aid_prepay
   WHERE aid_tax.invoice_id = invs.invoice_id
   AND   aid_tax.invoice_id = aid_taxrev.invoice_id
   AND   aid_tax.invoice_distribution_id = aid_taxrev.parent_reversal_id
   AND   aid_prepay.invoice_id = aid_taxrev.invoice_id
   AND   aid_prepay.invoice_distribution_id = aid_taxrev.charge_applicable_to_dist_id
   AND   aid_taxrev.detail_tax_dist_id is not null
   AND   nvl(aid_taxrev.historical_flag, ''N'') = ''N''
   AND   nvl(aid_tax.historical_flag, ''N'') = ''Y''
   AND   aid_prepay.line_type_lookup_code = ''PREPAY''
   AND   aid_taxrev.line_type_lookup_code IN (''REC_TAX'', ''NONREC_TAX'')
   AND   aid_taxrev.prepay_distribution_id is null
and rownum<1000
order by invoice_id',
      p_title                  => 'Tax Distributions Created during Prepay Application/Unapplication with Missing PREPAY_DISTRIBUTION_ID Values',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Tax distributions created during prepay application/unapplication with missing PREPAY_DISTRIBUTION_ID values<br/><strong>Impact Area(s): </strong>Accounting Incorrect
',
      p_solution               => '<strong>Solution GDF: </strong>20407191</br><strong>Note: </strong>[1322304/KB202280]</br><strong>Script Name: </strong>ap_prepay_dist_id_pop_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1322304/KB202280]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_MISSING_PREPAY_DISTRIBUTION_ID');



