debug('begin add_signature: EBS_AP_MU_SMALL_ROUNDING_AMOUNT');
   l_info('##MASK##AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##CHECK_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25726',
      p_sig_id                 => 'EBS_AP_MU_SMALL_ROUNDING_AMOUNT',
      p_sig_sql                => 'SELECT aph.check_id,
          ac.check_number,
          ac.amount,
          aip.invoice_id,
          aip.invoice_payment_id,
          aip.invoice_base_amount,
          aip.accounting_event_id,
          aip.amount,
          sum(nvl(aphd.invoice_dist_base_amount, aphd.invoice_dist_amount)) -
            nvl(aip.invoice_base_amount, aip.amount) difference
   FROM (
          SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        ) chks,
         ap_checks_all ac,
         ap_invoice_payments_all aip,
         ap_payment_history_all aph,
         ap_payment_hist_dists aphd
   WHERE ac.check_id = chks.check_id
   AND   aip.check_id = ac.check_id
   AND   aip.check_id = aph.check_id
   AND   aphd.invoice_payment_id = aip.invoice_payment_id
   AND   aphd.pay_dist_lookup_code = ''CASH''
   AND   aip.accounting_event_id = aphd.accounting_event_id
   AND   aip.accounting_event_id = aph.accounting_event_id
   AND   aph.payment_history_id = aphd.payment_history_id
   AND   aph.historical_flag is null
   AND   aph.transaction_type IN (''PAYMENT CREATED'', ''REFUND RECORDED'')
   AND   aph.posted_flag = ''Y''
   GROUP BY aph.check_id, aip.invoice_id, ac.check_number, ac.amount,
            aip.invoice_payment_id, aip.invoice_base_amount,
            aip.accounting_event_id, aip.amount
   HAVING sum(nvl(aphd.invoice_dist_base_amount, aphd.invoice_dist_amount)) !=
            nvl(aip.invoice_base_amount, aip.amount)
            order by check_id
    ',
      p_title                  => 'Payments  accounted with incorrect amounts causing small rounding',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'When there are multiple invoices payments may be accounted with incorrect amounts causing small rounding amount differences in CASH or CASH CLEARING.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>21621811</br><strong>Note: </strong>[2632111/KB163144]</br><strong>Script Name: </strong>ap_pay_cr_has_x_ida_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2632111/KB163144].</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_AP_MU_SMALL_ROUNDING_AMOUNT');



debug('begin add_signature: EBS_AP_MU_TAX_DISTR_UNACCOUNTED');
