      p_fail_condition         => 'RS',
      p_problem_descr          => 'Approved prepayment application or unapplication distributions missing records in the table AP_PREPAY_APP_DISTS, which causes prepayment application or unapplication accounting events to remain unaccounted<br/><strong>Impact Area(s): </strong>Accounting Incorrect, Prepay Application
',
      p_solution               => '<strong>Solution GDF: </strong>17481243</br><strong>Note: </strong>[975184/KB752742]</br><strong>Script Name: </strong>ap_apad_missing_sel.sql</br></br>Apply the GDF patch following the instructions provided in [975184/KB752742]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found
',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
