      p_problem_descr          => 'Incorrect technical rounding on the column Invoice_Dist_Base_Amount in the table AP_PAYMENT_HIST_DISTS causing Incorrect Payment Accounting <br/><strong>Impact Area(s): </strong>Accounting Incorrect
',
      p_solution               => '<strong>Solution GDF: </strong>17533422</br><strong>Note: </strong>[1316588/KB771769]</br><strong>Script Name: </strong>ap_pay_cr_has_x_idba_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1316588/KB771769]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found
',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
