debug('begin add_signature: EBS_FIN_AP_MU_PAYMENTS_AWT_PRORATION');
   l_info('##MASK##AC.AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##AIP.AMOUNT'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '26267',
      p_sig_id                 => 'EBS_FIN_AP_MU_PAYMENTS_AWT_PRORATION',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.org_id,
          ac.check_number,
          ac.check_date,
          ac.amount,
          aip.invoice_id,
          aip.accounting_event_id,
          aip.invoice_payment_id,
          aip.amount,
          sum(aphd.amount) total
   FROM ap_invoice_payments_all aip,
        ap_payment_hist_dists aphd,
        ap_payment_history_all aph,
        ap_checks_all ac,
        (
          SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )

        ) chks
   WHERE aip.invoice_payment_id = aphd.invoice_payment_id
   AND   aip.accounting_event_id = aphd.accounting_event_id
   AND   aip.posted_flag = ''Y''
   AND   aphd.pay_dist_lookup_code = ''CASH''
   AND   aph.accounting_event_id = aip.accounting_event_id
   AND   aph.posted_flag = ''Y''
   AND   aph.historical_flag is null
   AND   EXISTS (
           SELECT 1
           FROM ap_payment_hist_dists hd1,
                ap_payment_hist_dists hd2
           WHERE hd1.invoice_payment_id = aip.invoice_payment_id
           AND   hd1.accounting_event_id = aip.accounting_event_id
           AND   hd1.pay_dist_lookup_code = ''AWT''
           AND   hd1.awt_related_id = hd2.invoice_distribution_id
           AND   hd2.invoice_payment_id = aip.invoice_payment_id
           AND   hd2.accounting_event_id = aip.accounting_event_id
           AND   hd1.payment_hist_dist_id > hd2.payment_hist_dist_id)
   AND   aph.check_id = ac.check_id
   AND   ac.check_id = chks.check_id
   GROUP BY ac.check_id, ac.org_id, ac.check_number, ac.check_date,
            ac.amount, aip.invoice_id, aip.accounting_event_id,
            aip.invoice_payment_id, aip.amount
   HAVING   aip.amount != sum(aphd.amount)

',
      p_title                  => 'Checks Improperly Accounted With Incorrect Payment Proration When Invoice having AWT Distribution ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Checks which are improperly accounted due to incorrect payment proration when AWT distribution and parent distribution have the same amount<br/><strong>Impact Area(s): </strong>Accounting Incorrect
',
      p_solution               => '<strong>Solution GDF: </strong>19528164</br><strong>Note: </strong>[1370096/KB354208]</br><strong>Script Name: </strong>ap_WrngAwtPror_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1370096/KB354208]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found
',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AP_MU_PAYMENTS_AWT_PRORATION');



