debug('begin add_signature: EBS_FIN_AP_MU_ZERO_PAYMENT_WRONG_ACCOUNTING');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '26260',
      p_sig_id                 => 'EBS_FIN_AP_MU_ZERO_PAYMENT_WRONG_ACCOUNTING',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(aph, aip, ai) */
          aip.check_id,
          aip.org_id,
          ai.invoice_id,
          ai.invoice_num,
          aph.accounting_event_id,
          aip.invoice_payment_id
   FROM (
         SELECT /*+ materialize */ DISTINCT
                ph.check_id
            FROM
                ap_payment_history_all ph
            WHERE
                ph.accounting_date BETWEEN ( trunc(sysdate) - 7 ) AND ( trunc(sysdate) + 3 )
        ) chks,
        ap_payment_history_all aph,
        ap_invoice_payments_all aip,
        ap_invoices_all ai
   WHERE aph.check_id = chks.check_id
   AND   aip.invoice_id = ai.invoice_id
   AND   aip.posted_flag = ''Y''
   AND   aip.org_id = ai.org_id
   AND   aip.amount = 0
   AND   ai.invoice_amount = 0
   AND   ai.payment_status_flag = ''Y''
   AND   aph.check_id = aip.check_id
   AND   aph.transaction_type in (''PAYMENT CREATED'',
           ''REFUND RECORDED'', ''PAYMENT CLEARING'')
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.amount    <> 0)
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_payment_hist_dists aphd
           WHERE aphd.accounting_event_id = aph.accounting_event_id
           AND   aphd.invoice_payment_id  = aip.invoice_payment_id
           AND   aphd.pay_dist_lookup_code = ''CASH''
           AND   aphd.amount             = 0)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_payment_hist_dists aphd
           WHERE aphd.accounting_event_id = aph.accounting_event_id
           AND   aphd.invoice_payment_id  = aip.invoice_payment_id
           AND   aphd.pay_dist_lookup_code = ''CASH''
           AND   aphd.amount             <> 0)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM xla_ae_headers xah
           WHERE xah.event_id = aph.accounting_event_id
           AND   xah.upg_batch_id IS NOT NULL
           AND   xah.application_id = 200
           AND   xah.ledger_id = aip.set_of_books_id)
and  rownum <1000
order by aip.check_id DESC
',
      p_title                  => 'Zero Payment has Wrong Accounting Due to Incorrect Payment Proration',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment history distributions having zero values due to incorrect proration of invoice distributions when the invoice amount is zero<br/><strong>Impact Area(s): </strong>Accounting Incorrect
',
      p_solution               => '<strong>Solution GDF: </strong>17505845</br><strong>Note: </strong>[1505485/KB502842]</br><strong>Script Name: </strong>ap_pay_hist_dists_zero_pro_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1505485/KB502842]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AP_MU_ZERO_PAYMENT_WRONG_ACCOUNTING');



