      p_sig_repo_id            => '5169',
      p_sig_id                 => 'RETROPAY_UNEXPECTED_ENTRIES2',
      p_sig_sql                => 'select run_result_id,element_entry_id
from pay_run_results
where ELEMENT_ENTRY_ID<>SOURCE_ID
and ENTRY_TYPE=''E''
AND exists (select 1
from pay_payroll_actions
where action_type = ''L''
and effective_date >= to_date(''01-JAN-2015'',''DD-MON-YYYY''))
union
SELECT prr.run_result_id,prr.element_entry_id
FROM pay_run_results prr
,pay_assignment_actions paa
,pay_payroll_actions ppa
,pay_element_entries_f peef
WHERE prr.source_id <> prr.element_entry_id
AND prr.element_entry_id = peef.element_entry_id
AND peef.creator_type NOT IN (''AD'',''AE'',''D''
,''DF'',''P'',''B''
,''NR'',''PR'',''EE''
,''RR'',''R'',''FL'')
AND peef.entry_type = ''E''
AND prr.source_type = ''E''
AND prr.entry_type = ''E''
AND paa.assignment_id = peef.assignment_id
AND paa.assignment_action_id = prr.assignment_action_id
AND paa.payroll_action_id = ppa.payroll_action_id
AND ppa.action_type IN (''R'',''Q'')',
