debug('begin add_signature: MU_REVENUE_DISTRIBUTION_AND_ACCRUAL_CHECK');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23106',
      p_sig_id                 => 'MU_REVENUE_DISTRIBUTION_AND_ACCRUAL_CHECK',
      p_sig_sql                => 'SELECT ei.expenditure_item_id expenditure_item_id ,
       p.project_id project_id,
       p.org_id org_id
FROM pa_expenditure_items_all ei ,
     pa_projects_all p
WHERE ei.net_zero_adjustment_flag = ''Y''
AND   ei.revenue_distributed_flag = ''Y''
AND   ei.adjusted_expenditure_item_id IS NOT NULL
AND   NOT EXISTS  (
        SELECT 1  FROM pa_cust_rev_dist_lines_all crdl
        WHERE crdl.expenditure_item_id = ei.expenditure_item_id)
AND   0 <> nvl((
        SELECT sum(amount) FROM pa_cust_rev_dist_lines_all crdl1
        WHERE crdl1.expenditure_item_id = ei.adjusted_expenditure_item_id),0)
AND   ei.project_id = p.project_id
AND   (p.REVENUE_ACCRUAL_METHOD = ''WORK'' OR
       p.INVOICE_METHOD = ''WORK'')
AND   ei.accrued_revenue IS NULL
',
      p_title                  => 'Adjusting Expenditure Items Are Wrongly Stamped with Revenue Distributed Flag Y',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'In Expenditure inquiry form, adjusting expenditure items have revenue distributed flag=Y but accrued revenue field is null.<br>
Adjusted expenditure_item_ids have ACCRUED_REVENUE as null and the amount is not copied from the ADJUSTED_EXPENDITURE_ITEM_ID. ',
      p_solution               => 'A data fix will be required from Support.  If you would like to correct these lines with a data fix, please create an SR and Support will engage appropriately.<br>Refer to [2394907/KB603117] xpenditure Inquiry Shows Null Accrued Revenue and Gives "You cannot perform this action on an item which has been fully reversed" When Trying to Adjust',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_REVENUE_DISTRIBUTION_AND_ACCRUAL_CHECK');



debug('begin add_signature: MU_PA_REV_INCORRECT_REVTRANS_AMOUNT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23138',
      p_sig_id                 => 'MU_PA_REV_INCORRECT_REVTRANS_AMOUNT',
      p_sig_sql                => 'SELECT PROJECT_ID PROJECT_ID,
                DRAFT_REVENUE_NUM DRAFT_REVENUE_NUM,
                LINE_NUM LINE_NUM,
                REVTRANS_UBR_DR UBR_DR,
                REVTRANS_UER_CR UER_CR
FROM (SELECT PDR.PROJECT_ID, 
                             PDR.DRAFT_REVENUE_NUM, 
			     PDRI.LINE_NUM,
                             PDR.REVTRANS_UBR_DR, 
			     PDR.REVTRANS_UER_CR
                 FROM PA_DRAFT_REVENUES_ALL PDR, 
		              PA_DRAFT_REVENUE_ITEMS PDRI
               WHERE PDR.PROJECT_ID = PDRI.PROJECT_ID
                     AND PDR.DRAFT_REVENUE_NUM = PDRI.DRAFT_REVENUE_NUM
                     AND PDR.EVENT_ID IN (SELECT EVENT_ID 
		                                                    FROM XLA_EVENTS
                                                                  WHERE EVENT_STATUS_CODE = ''U''
                                                                        AND PROCESS_STATUS_CODE = ''I''
                                                                       AND APPLICATION_ID = 275)
                      AND EXISTS (SELECT 1 
		                                FROM PA_DRAFT_REVENUE_ITEMS
                                             WHERE PROJECT_ID = PDR.PROJECT_ID
                                                   AND DRAFT_REVENUE_NUM = PDR.DRAFT_REVENUE_NUM
                                             HAVING SIGN(SUM(AMOUNT)) <> 
                                                            SIGN(SUM(REVTRANS_AMOUNT)))
                  AND PDRI.AMOUNT < 0
		 AND PDRI.CREATION_DATE > SYSDATE -7
		)',
      p_title                  => 'Create Accounting Fails for Revenue Category',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'PRC: Create Accounting is failing with <br>

"The entered amount and accounted amount for line XX are not on the same side.',
      p_solution               => 'A data fix will be required from Support.  If you would like to correct these lines with a data fix, please create an SR and Support will engage appropriately.<br>Refer to [2848740/KB294565] Mismatch Between Revenue Entered Amount And Revenue Accounted Amount',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_PA_REV_INCORRECT_REVTRANS_AMOUNT');



