debug('begin add_signature: MU_PA_EXP_TRANS_NO_CREDIT_INVOICE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23139',
      p_sig_id                 => 'MU_PA_EXP_TRANS_NO_CREDIT_INVOICE',
      p_sig_sql                => 'SELECT
    project_id project_id,
    draft_invoice_num draft_invoice_number,
    line_num invoice_line_num,
    amount invoice_amount,
    invoice_line_type  invoice_line_type
FROM
    (
        SELECT
            project_id,
            draft_invoice_num,
            line_num,
            amount,
            invoice_line_type
        FROM
            pa_draft_invoice_items dii
        WHERE
                dii.invoice_line_type = ''NET ZERO ADJUSTMENT''
            AND 0 <> (
                SELECT
                    SUM(bill_trans_bill_amount)
                FROM
                    pa_cust_rev_dist_lines_all crdl
                WHERE
                        crdl.project_id = dii.project_id
                    AND crdl.draft_invoice_num = dii.draft_invoice_num
                    AND crdl.draft_invoice_item_line_num = dii.line_num
            )
            AND dii.creation_date >= sysdate - 7
             )',
      p_title                  => 'Transferred Expenditure Items Credit Not Processed By PRC: Generate Draft Invoice',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transferred Expenditure Items Credit not Processed By PRC: Generate Draft Invoice',
      p_solution               => 'A data fix will be required from Support.  If you would like to correct these lines with a data fix, please create SR and Support will engage appropriately.<br>Refer to [2848481/KB299792] Transferred Expenditure Items Credit Not Processed By PRC: Generate Draft Invoice',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: MU_PA_EXP_TRANS_NO_CREDIT_INVOICE');



