debug('begin add_signature: MU_BURD_ACTUALS_DIFF_FROM_ORIGINAL_COST');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23109',
      p_sig_id                 => 'MU_BURD_ACTUALS_DIFF_FROM_ORIGINAL_COST',
      p_sig_sql                => 'SELECT e.expenditure_group expenditure_group,
       cei.expenditure_item_id reversing_exp_item_id,
       cei.adjusted_expenditure_item_id orig_exp_item_id,
       p.segment1 project_number
FROM pa_expenditure_items_all ei,
     pa_expenditure_items_all cei,
     pa_expenditures_all e,
     pa_projects_all p
WHERE e.expenditure_id = ei.expenditure_id
AND   cei.adjusted_expenditure_item_id = ei.expenditure_item_id
AND   cei.net_zero_adjustment_flag = ''Y''
AND   ei.net_zero_adjustment_flag = ''Y''
AND   cei.project_id = p.project_id
AND   (NVL(cei.raw_cost,0) <> (NVL(ei.raw_cost,0) * -1) OR
       NVL(cei.burden_cost,0)  <> (NVL(ei.burden_cost,0) * -1) OR
       NVL(cei.denom_raw_cost,0) <> (NVL(ei.denom_raw_cost,0) * -1) OR
       NVL(cei.denom_burdened_cost,0) <> (NVL(ei.denom_burdened_cost,0) * -1) OR
       NVL(cei.acct_raw_cost,0) <> (NVL(ei.acct_raw_cost,0) * -1) OR
       NVL(cei.acct_burdened_cost,0) <> (NVL(ei.acct_burdened_cost,0)    * -1) OR
       NVL(cei.project_raw_cost,0) <> (NVL(ei.project_raw_cost,0) * -1) OR
       NVL(cei.project_burdened_cost,0) <> (NVL(ei.project_burdened_cost,0) * -1))
AND   cei.creation_date >= SYSDATE - 7
',
      p_title                  => ' Raw and Burden Cost for Adjustment Lines Are Not Matching with Original Expenditure Item',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Raw Cost or Burden Cost for adjusted expenditure items are not matching with original expenditure item.',
      p_solution               => 'Burden cost is calculated incorrectly for reversed expenditure items.
<br> 
A data fix will be required from Support.  If you would like to correct these lines with a data fix, please create an SR and Support will engage appropriately.<br>Refer to [2507646/KB454298] Raw And Burden Cost For Adjustment Lines Are Not Matching With Original Expenditure Item',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_BURD_ACTUALS_DIFF_FROM_ORIGINAL_COST');



