debug('begin add_signature: MU_WP_TASK_WBS_SHARE_VERD');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23110',
      p_sig_id                 => 'MU_WP_TASK_WBS_SHARE_VERD',
      p_sig_sql                => 'SELECT DISTINCT
       p.project_id project_id,
       p.segment1 Project_Number
FROM pa_projects_all p,
     pa_tasks pt,
     pa_proj_elements pe,
     pa_proj_element_versions pev,
     pa_proj_elem_ver_structure pevs
WHERE p.project_id = pt.project_id
AND   pt.project_id = pe.project_id
AND   pe.project_id = pev.project_id
AND   pev.project_id = pevs.project_id
AND   pt.task_id = pe.proj_element_id
AND   pe.proj_element_id = pev.proj_element_id
AND   pe.object_type = ''PA_TASKS''
AND   pev.object_type = ''PA_TASKS''
AND   nvl(pe.link_task_flag, ''N'') = ''N''
AND   pev.financial_task_flag = ''Y''
AND   pev.parent_structure_version_id = pevs.element_version_id
AND   pevs.element_version_id =
        pa_project_structure_utils.get_latest_fin_struc_ver_id(p.project_id)
AND   pt.wbs_level <> pev.wbs_level
AND   p.structure_sharing_code = ''SHARE_FULL''
AND   pa_proj_task_struc_pub.is_wp_versioning_enabled(p.project_id) = ''N''
AND   pt.creation_date >= SYSDATE - 7

',
      p_title                  => 'Task Data Corrupted in Worplan Tables (Wbs Level, Outline Number and Parent Child Relations)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The shared workplan structure does not match the financial structure hierarchy data and as a result progress cannot be collected/monitored.',
      p_solution               => 'A data fix will be required from Support.  If you would like to correct these lines with a data fix, please update the SR and Support will engage appropriately.<br>Refer to [2571660/KB580369] WORKPLAN Tables (WBS level, outline number and parent child relationships got corrupted in workplan tables) For Versioning Disabled Project',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
