debug('begin add_signature: MU_WP_TASK_MIS_SHARE_VERE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23108',
      p_sig_id                 => 'MU_WP_TASK_MIS_SHARE_VERE',
      p_sig_sql                => 'SELECT project_id project_id,
       segment1 project_number,
       task_id task_id,
       task_number task_number,
       str_version_id structure_version_id
FROM (
  SELECT p.project_id,
         p.segment1,
         t.task_id,
         t.task_number,
         pa_project_structure_utils.get_latest_fin_struc_ver_id(p.project_id)
           str_version_id
  FROM pa_projects_all p,
       pa_tasks t,
       pa_project_statuses ps
  WHERE p.project_status_code = ps.project_status_code
  AND   ps.project_system_status_code != ''CLOSED''
  AND   ps.status_type = ''PROJECT''
  AND   trunc(SYSDATE) BETWEEN
          ps.start_date_active AND nvl(ps.end_date_active, trunc(SYSDATE))
  AND   p.structure_sharing_code = ''SHARE_FULL''
  AND   pa_workplan_attr_utils.check_wp_versioning_enabled(p.project_id) = ''Y''
  AND   t.project_id = p.project_id
  AND   (NOT EXISTS (
           SELECT 1 FROM pa_proj_element_versions pev
           WHERE  pev.parent_structure_version_id =
                    pa_project_structure_utils.get_latest_fin_struc_ver_id(p.project_id)
           AND    pev.project_id = t.project_id
           AND    pev.proj_element_id = t.task_id) OR
         NOT EXISTS (
           SELECT 1 FROM pa_proj_elements pe
           WHERE pe.project_id = t.project_id
           AND   pe.proj_element_id = t.task_id))
  AND   t.last_update_date >= SYSDATE - 7
  )

',
      p_title                  => 'Tasks Missing in Work Plan Tables for Fully Shared Work Plan Versioning Enabled Projects',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Not able to publish the workplan , unable to enter the actual and not able to monitor the progress',
      p_solution               => 'A data fix will be required from Support.  If you would like to correct these lines with a data fix, please update the SR and Support will engage appropriately.<br>Refer to [2571248/KB478376] Tasks Missing In Workplan Tables For Fully Shared Workplan Versioning Enabled Projects',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_WP_TASK_MIS_SHARE_VERE');



debug('begin add_signature: MU_WP_TASK_MIS_SHARE_VERD');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23131',
      p_sig_id                 => 'MU_WP_TASK_MIS_SHARE_VERD',
      p_sig_sql                => 'SELECT p.project_id project_id,
       p.segment1 project_number,
       p.str_vers_id structure_version_id
FROM (
  SELECT p.project_id,
         p.segment1,
         pa_project_structure_utils.get_latest_fin_struc_ver_id(p.project_id) str_vers_id
  FROM pa_projects_all p,
       pa_project_statuses ps
  WHERE p.project_status_code = ps.project_status_code
  AND   ps.project_system_status_code != ''CLOSED''
  AND   ps.status_type = ''PROJECT''
  AND   trunc(SYSDATE) BETWEEN
          ps.start_date_active AND
          nvl(ps.end_date_active, trunc(SYSDATE))
  AND   p.structure_sharing_code = ''SHARE_FULL''
  AND   pa_workplan_attr_utils.check_wp_versioning_enabled(p.project_id) = ''N''
  ) p
WHERE p.project_id IN (
        SELECT t.project_id
        FROM pa_tasks t,
             pa_proj_element_versions pev,
             pa_proj_elements pe
        WHERE t.project_id = p.project_id
        AND   p.str_vers_id = pev.parent_structure_version_id(+)
        AND   t.project_id = pev.project_id(+)
        AND   t.task_id = pev.proj_element_id(+)
        AND   t.project_id = pe.project_id(+)
        AND   t.task_id = pe.proj_element_id(+)
        AND   (pev.proj_element_id is null OR
               pe.proj_element_id is null)
        UNION
        SELECT pe.project_id
        FROM pa_tasks t,
             pa_proj_element_versions pev,
             pa_proj_elements pe
        WHERE pe.project_id = p.project_id
        AND   pe.object_type = ''PA_TASKS''
        AND   pe.link_task_flag = ''N''
        AND   pe.project_id = pev.project_id
        AND   pe.proj_element_id = pev.proj_element_id
        AND   pev.parent_structure_version_id = p.str_vers_id
        AND   pe.project_id = t.project_id (+)
        AND   pe.proj_element_id = t.task_id (+)
        AND   t.task_id is null
        AND   t.creation_date >= SYSDATE - 7
  )
',
      p_title                  => 'Tasks Missing From Work Plan Tables for Fully Shared Structures with Versioning Disabled ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Financial structure tasks are missing in the workplan preventing the publishing of the workplan and collection of progress.',
      p_solution               => 'A data fix will be required from Support.  If you would like to correct these lines with a data fix, please create an SR and Support will engage appropriately.<br>Refer to [2571658/KB299364] Tasks Missing In Workplan Tables For Fully Shared Workplan Versioning Disabled Projects',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_WP_TASK_MIS_SHARE_VERD');



