debug('begin add_signature: MU_WP_INVALID_START_DATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23118',
      p_sig_id                 => 'MU_WP_INVALID_START_DATE',
      p_sig_sql                => 'SELECT DISTINCT
       expenditure_item_date expenditure_item_date,
       invoice_num invoice_num,
       segment1 project_number,
       element_number task_number,
       scheduled_start_date scheduled_start_date,
       actual_start_date actual_start_date
FROM(
  SELECT ei.expenditure_item_date,
         to_char(null) invoice_num,
         p.segment1,
         pe.element_number,
         pevs.scheduled_start_date,
         pevs.actual_start_date,
         pevs.estimated_start_date
  FROM pa_expenditure_items_all ei,
       pa_projects_all p,
       pa_proj_elements pe,
       pa_proj_element_versions pev,
       pa_proj_elem_ver_schedule pevs
  WHERE p.project_id = pe.project_id
  AND   ei.project_id = pe.project_id
  AND   ei.task_id = pe.proj_element_id
  AND   pe.proj_element_id = pev.proj_element_id
  AND   pev.element_version_id = pevs.element_version_id
  AND   (ei.expenditure_item_date < pevs.scheduled_start_date OR
         ei.expenditure_item_date < pevs.actual_start_date OR
         ei.expenditure_item_date < pevs.estimated_start_date)
  AND   ei.creation_date >= sysdate - 7
  UNION
  SELECT ad.expenditure_item_date,
         ai.invoice_num,
         p.segment1,
         pe.element_number,
         pevs.scheduled_start_date,
         pevs.actual_start_date,
         pevs.estimated_start_date
  FROM ap_invoice_distributions_all ad,
       pa_projects_all p,
       pa_proj_elements pe,
       pa_proj_element_versions pev,
       pa_proj_elem_ver_schedule pevs,
       ap_invoices_all ai
  WHERE p.project_id = pe.project_id
  AND   ai.invoice_id = ad.invoice_id
  AND   ad.project_id = pe.project_id
  AND   ad.task_id = pe.proj_element_id
  AND   pe.proj_element_id = pev.proj_element_id
  AND   pev.element_version_id = pevs.element_version_id
  AND   (ad.expenditure_item_date < pevs.scheduled_start_date OR
         ad.expenditure_item_date < pevs.actual_start_date OR
         ad.expenditure_item_date < pevs.estimated_start_date )
  AND   ad.creation_date >= sysdate - 7
  )
',
      p_title                  => 'Expenditure Items Exist with Expenditure Item Dates Before The Task Start Dates ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Due to mismatch in task and transaction dates, errors such as "PA_EI_INVALID_START_DATE" can occur when publishing the workplan.',
      p_solution               => 'Refer to [2514928/KB598438] Warning "PA_EI_INVALID_START_DATE" When Publishing Workplan',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_WP_INVALID_START_DATE');



debug('begin add_signature: MU_WP_INVALID_FINISH_DATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23119',
      p_sig_id                 => 'MU_WP_INVALID_FINISH_DATE',
      p_sig_sql                => 'SELECT DISTINCT
       expenditure_item_date expenditure_item_date,
       invoice_num invoice_num,
       segment1 project_number,
       element_number task_number,
       scheduled_finish_date scheduled_finish_date,
       actual_finish_date actual_finish_date
FROM (
  SELECT ei.expenditure_item_date,
         to_char(null) invoice_num,
         p.segment1 ,
         pe.element_number, --Task Number
         pevs.scheduled_finish_date,
         pevs.actual_finish_date ,
         pevs.estimated_finish_date
  FROM pa_expenditure_items_all ei,
       pa_projects_all p ,
       pa_proj_elements pe ,
       pa_proj_element_versions pev ,
       pa_proj_elem_ver_schedule pevs
  WHERE p.project_id = pe.project_id
  AND   ei.project_id = pe.project_id
  AND   ei.task_id = pe.proj_element_id
  AND   pe.proj_element_id = pev.proj_element_id
  AND   pev.element_version_id = pevs.element_version_id
  AND   (pevs.scheduled_finish_date < ei.expenditure_item_date OR
         pevs.actual_finish_date < ei.expenditure_item_date OR
         pevs.estimated_finish_date < ei.expenditure_item_date )
  AND   ei.creation_date >= sysdate - 7
  UNION
  SELECT ap.expenditure_item_date,
         aph.invoice_num ,
         p.segment1 ,
         pe.element_number,
         pevs.scheduled_finish_date,
         pevs.actual_finish_date ,
         pevs.estimated_finish_date
  FROM ap_invoice_distributions_all ap ,
       pa_projects_all p ,
       pa_proj_elements pe ,
       pa_proj_element_versions pev ,
       pa_proj_elem_ver_schedule pevs ,
       ap_invoices_all aph
  WHERE p.project_id = pe.project_id
  AND   aph.invoice_id = ap.invoice_id
  AND   ap.project_id = pe.project_id
  AND   ap.task_id = pe.proj_element_id
  AND   pe.proj_element_id = pev.proj_element_id
  AND   pev.element_version_id = pevs.element_version_id
  AND   (pevs.scheduled_finish_date < ap.expenditure_item_date OR
         pevs.actual_finish_date < ap.expenditure_item_date OR
         pevs.estimated_finish_date < ap.expenditure_item_date )
  AND   ap.creation_date >= sysdate - 7
  )

',
      p_title                  => 'Expenditure Items Exist with Expenditure Item Dates After The Task Finish Dates ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Due to mismatch in task and transaction dates, Errors "PA_EI_INVALID_DATES" or "PA_SI_INVALID_FINISH_DATE" can occur when publishing the workplan.',
      p_solution               => 'Refer to [2514941/KB635604] Warning "PA_EI_INVALID_DATES" or "PA_SI_INVALID_FINISH_DATE" When Publishing Workplan',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_WP_INVALID_FINISH_DATE');



debug('begin add_signature: DIFF_REQ_DESC_BPA_LINE_DESC');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5990',
      p_sig_id                 => 'DIFF_REQ_DESC_BPA_LINE_DESC',
      p_sig_sql                => 'select poh.segment1 PO_NUM,
poh.type_lookup_code,
pla.po_header_id,
pla.po_line_id,
pla.item_description PO_ITEM_DESCRIPTION,
pla.line_num,
prh.segment1 REQ_NUM,
prla.requisition_header_id,
prla.requisition_line_id,
prla.line_num,
prla.item_description REQ_ITEM_DESCRIPTION,
prla.blanket_po_header_id
from po_headers_all poh,
po_lines_all pla,
po_requisition_lines_all prla,
po_requisition_headers_all prh
where pla.po_header_id = poh.po_header_id
and prla.blanket_po_header_id = pla.po_header_id
and prla.blanket_po_line_num = pla.line_num
and prla.requisition_header_id = prh.requisition_header_id
and prla.item_id is null
having pla.item_description <> prla.item_description
group by poh.segment1,poh.type_lookup_code, pla.po_header_id,pla.po_line_id,pla.item_description,
pla.line_num,prh.segment1, prla.requisition_header_id, prla.requisition_line_id, prla.line_num,
prla.item_description, prla.blanket_po_header_id',
      p_title                  => 'Item Description on Requisition Line Is Different Than the Blanket Purchase Agreement Line Item Description',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<p>During the creation of the requisition line, the item description is derived from the Blanket Purchase Agreement (BPA) line item description. Due to a bug in the code, the blank spaces in the description are trimmed on the requisition line.  The item descriptions may also be out of sync for other value variations besides blank spaces.<br />As a result, the item description on the requisition line and the BPA line no longer match. This causes the autocreate process to fail.</p>',
      p_solution               => '<p>Log a Service Request with support and request the datafix associated with [1598083/KB791778] Not All Requisition Lines Are Autocreated Onto a Blanket Release - Requisition Line Cannot be Matched with Any of the Blanket Purchase Order Lines.</p>
<p>Specify that you need the Datafix for Bug {24472591}.</p>',
      p_success_msg            => 'There are no differences between the requisition line item description and the BPA line item description.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: DIFF_REQ_DESC_BPA_LINE_DESC');



debug('begin add_signature: DIFF_BPA_DESC_IP_ITEM_DESC');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5989',
      p_sig_id                 => 'DIFF_BPA_DESC_IP_ITEM_DESC',
      p_sig_sql                => 'select
   ph.po_header_id,
   ph.type_lookup_code,
   ph.global_agreement_flag,
   pl.item_description,
   pl.po_line_id,
   pl.org_id,
   pl.ip_category_id 
from
   po_headers_all ph,
   po_lines_all pl,
   po_attribute_values_tlp pavt,
   icx_cat_attribute_values_tlp icavt 
where
   ph.po_header_id = pl.po_header_id 
   and pavt.po_line_id = pl.po_line_id 
   and icavt.po_line_id = pavt.po_line_id 
   and ph.authorization_status = ''APPROVED'' 
   and pl.item_id is null 
   and pavt.language = icavt.language 
   and pavt.language = userenv(''lang'') 
   and 
   (
      pavt.description <> pl.item_description 
      OR icavt.description <> pl.item_description 
   )',
      p_title                  => 'Difference Between Blanket Purchase Agreement Description and iProcurement Item Description or Item Description in the Attibute Values Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<p>During the creation of the requisition line, the item description is derived from the Blanket Purchase Agreement (BPA) line. Due to a bug in the code, the blank spaces in the item description are trimmed on the requisition line.<br />As a result, the item description on the requisition line, the attribute values table, and the BPA line no longer match. This causes the autocreate process to fail.</p>',
      p_solution               => '<p>Log a Service Request with support and request the datafix associated with [1598083/KB791778] Not All Requisition Lines Are Autocreated Onto a Blanket Release - Requisition Line Cannot be Matched with Any of the Blanket Purchase Order Lines.</p>
<p>Specify that you need the Datafix for Bug 24586811.</p>',
      p_success_msg            => 'There are no issues where there are differences between the Blanket Purchase Agreement (BPA) line item description, the attribute values table, and the iProcurement item description table.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: DIFF_BPA_DESC_IP_ITEM_DESC');



debug('begin add_signature: AUTOCREATE_SOURCING_DOC_CHECKS');
   l_info('##MASK##DESCRIPTION'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##REQ_DESCRIPTION'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3354',
      p_sig_id                 => 'AUTOCREATE_SOURCING_DOC_CHECKS',
      p_sig_sql                => 'SELECT prha.segment1 req_number
, prla.line_num req_line_num
, prha.creation_date Req_Creation_Date, 
  nvl(prha.description,''NO DESCRIPTION'') Req_Description ,prla.Need_By_Date, prha.Preparer_ID Requestor_ID
, prla.document_type_code  Source_Doc_Type
, suggested_buyer_id BUYER_ID
, poh.segment1 PO_Number
, pol.line_num Po_Line_Number
, DECODE(poh.cancel_flag,''N'',''NO'',''**SOURCE PO CANCELLED **'') PO_Cancel_Flag
, poh.end_date_active PO_End_Date
, decode(poh.authorization_status,''APPROVED'',''APPROVED'',''**NOT APPROVED**'') PO_Status
, poh.end_date Header_End_Date
, pol.expiration_date Line_End_Date
, prla.quantity * PRLA.UNIT_PRICE Req_Line_Amount
, pol.MIN_RELEASE_AMOUNT Blanket_Line_Min_Rel_Amount
, pol.cancel_flag PO_Line_Cancel_Flag
, prla.quantity Req_Line_Qty
, prha.requisition_header_id req_header_id
, prla.requisition_line_id req_line_id
, prla.blanket_po_header_id
FROM po_requisition_headers prha
, po_requisition_lines prla
, po_headers poh
, po_lines pol
WHERE prha.requisition_header_id = prla.requisition_header_id
and poh.po_header_id = prla.blanket_po_header_id           --link to blanket po header
and pol.po_header_id (+) = poh.po_header_id                --link to get blanket lines  outer join for contracts
AND prha.authorization_status = ''APPROVED''                  --only approved reqs
AND prla.line_location_id IS  NULL                         --not put on po release or std po yet
AND nvl(prla.closed_code, ''OPEN'') <> ''FINALLY CLOSED''      --NOT CLOSED
AND nvl(prla.cancel_flag, ''N'') <> ''Y''                      --NOT CANCELLED
and prla.blanket_po_header_id is not null                   --get only sourced reqs    
and (
     ( nvl(poh.end_date,sysdate) < sysdate + 30  and poh.end_date is not null)                  --check for end date past
      or nvl(poh.cancel_flag,''N'') = ''Y''                                 --check for cancelled
      or poh.authorization_status <> ''APPROVED''                        --check for not approved header
      or  (nvl(pol.expiration_date,sysdate) < sysdate + 30 and pol.expiration_date is not null  ) --lines expiring in 30 days or less
      or nvl(pol.cancel_flag,''N'') = ''Y''                                         --check blanket line cancel
      or pol.MIN_RELEASE_AMOUNT > (prla.quantity * PRLA.UNIT_PRICE)        --check min release amount blanket line vs req line fixed 2/20
     )',
      p_title                  => 'Requisitions Sourced to Blanket or Contract - Document Checks',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<p>Requisitions are sourced to a Blanket or Contract Agreement document that is either</p>
<ul>
<li>not approved</li>
<li>cancelled</li>
<li>end date has expired</li>
<li>does not meet minimum release quantity</li>
</ul>',
      p_solution               => 'See [2208149/KB677313] - Autocreate Sourcing Document Checklist for key sourcing document checks for Requisitions sourced to Blanket and Contract Purchase Agreements.',
      p_success_msg            => '<p>All requisitions sourced to a Blanket or Contract Agreement do not have an expired header date and the source documents are approved. The lines are not expired and the requisition quantity is not greater than the minimum release amount.  All these checks passed validation and are not an issue.</p>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: AUTOCREATE_SOURCING_DOC_CHECKS');



debug('begin add_signature: REQS_SOURCED_BLANKET_CONTRACT_HEADER_LINE_ERROR');
   l_info('##MASK##BUYER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##MASK##REQUESTOR'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5657',
      p_sig_id                 => 'REQS_SOURCED_BLANKET_CONTRACT_HEADER_LINE_ERROR',
      p_sig_sql                => 'SELECT  prha.segment1 REQ_#
, prla.line_num REQ_LINE_#
, TO_CHAR(prha.creation_date, ''MM/DD/YYYY'') REQ_DATE
, DECODE(poh.cancel_flag,''N'',''ACTIVE'',''**SOURCE PO CANCELLED **'') SRC_PO_Cancel_Flag
, decode(poh.authorization_status,''APPROVED'',''APPROVED'',''**NOT APPROVED**'') SRC_PO_Status
--, decode ( sign(nvl(pol.expiration_date,sysdate ) - sysdate + 30), -1, ''Line End Date Ok'', 0, ''Line End Date Ok'', 1, ''Line End Date Expiring ''|| pol.expiration_date) Soure_Line_Exp_Date
, decode ( sign(trunc(sysdate) + 30 - trunc(nvl(pol.expiration_date,sysdate + 30 )) ), -1, ''Line End Date Ok'', 0, ''Line End Date Ok'', 1, ''Line End Date Expiring ''|| pol.expiration_date) Soure_Line_Exp_Date2
, decode ( sign(trunc(sysdate) + 30 - trunc(nvl(poh.end_date,sysdate + 30 )) ), -1, ''Header End Date Ok'', 0, ''Header End Date Ok'', 1, ''Header End Date Expiring ''|| poh.end_date) Soure_Header_Exp_Date
, decode( sign( nvl(pol.MIN_RELEASE_AMOUNT,0) - (prla.quantity * PRLA.UNIT_PRICE)), -1, ''Amount Sufficient to Release'', 1, ''REQ QTY Not > Min Release Amount of ''||pol.min_release_amount) Enough_To_Release
, pol.MIN_RELEASE_AMOUNT Blanket_Line_Min_Rel_Amount
, prla.quantity Req_Line_Qty
, prla.quantity * PRLA.UNIT_PRICE Req_Line_Amount
,prla.Need_By_Date
, prla.document_type_code  SRC_Doc_Type
, poh.segment1 SRC_PO_#
, pol.line_num   SRC_Po_Line_#
, pol.cancel_flag PO_Line_Cancel_Flag
, poh.end_date SRC_PO_END_DATE
, pol.expiration_date SRC_PO_Line_Exp
, poh.end_date_active SRC_PO_End_Active_date
,  nvl(prha.description,''NO DESCRIPTION'') Req_Description 
, reqstr.full_name Requestor        --, prha.Preparer_ID Requestor_ID
, buyer.full_name  Buyer    --suggested_buyer_id BUYER_ID
FROM po_requisition_headers prha
, po_requisition_lines prla
, po_headers poh
, po_lines pol
, PER_PEOPLE_F buyer
,  po_agents poa
, per_people_f reqstr
WHERE prha.requisition_header_id = prla.requisition_header_id
and poh.po_header_id = prla.blanket_po_header_id      --link to blanket po header
and PRLA.blanket_po_header_id  =         pol.po_header_id (+)         --link to get blanket lines
AND PRLA.BLANKET_PO_LINE_NUM  = POL.LINE_NUM (+)       --OUTER JOIN IN CASE OF CONTRACT
AND prha.authorization_status = ''APPROVED''             --only approved reqs
--AND nvl(prla.reqs_in_pool_flag,''N'') = ''Y''             -- IS NULL don''t need this i don''t think
AND prla.line_location_id IS  NULL                     --not put on po release or std po yet
AND nvl(prla.closed_code, ''OPEN'') <> ''FINALLY CLOSED''  --REQ NOT CLOSED
AND nvl(prla.cancel_flag, ''N'') <> ''Y''                  --REQ NOT CANCELLED
and prla.blanket_po_header_id is not null              --REQ SOURCED get only sourced reqs                 --remove using to test
and poh.agent_id = poa.agent_id 
and poa.agent_id = buyer.person_id                       --link to get the buyer
and prha.Preparer_ID = reqstr.person_id                 --link to submitter
and (
     ( nvl(poh.end_date,sysdate) < sysdate + 30  and poh.end_date is not null)                    --check for end date nearing end or in the past
      or nvl(poh.cancel_flag,''N'') = ''Y''                                                           --check for the source header document is cancelled
      or poh.authorization_status <> ''APPROVED''                                                   --check for source header not approved 
      or  (nvl(pol.expiration_date,sysdate) < sysdate + 30 and pol.expiration_date is not null  ) --check for lines expiring in 30 days or less
      or nvl(pol.cancel_flag,''N'') = ''Y''                                                           --check for blanket lins that are cancelled
      or pol.MIN_RELEASE_AMOUNT > (prla.quantity * PRLA.UNIT_PRICE)                               --check for minimum release amount on blanket line vs req line
     )    
order by 1,2,3',
      p_title                  => 'Requisitions Sourced to Blanket or Contract - Documents Require Attention',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<p>Requisitions sourced to blankets or contract purchase order have an issue with the blanket header or line. The following are checked:</p>
<ul>
<li>Source document header end date is near or already past the end date</li>
<li>Source document has been cancelled</li>
<li>Source document is currently not approved in status</li>
<li>Source document line is expiring in 30 days or less or has already expired</li>
<li>Source document line is cancelled</li>
<li>Minimum release amount on source document is greater than the requisition line amount</li>
</ul>',
      p_solution               => 'See [2208149/KB677313] - Autocreate Sourcing Document Checklist for key sourcing document checks for Requisitions sourced to Blanket and Contract Purchase Orders.',
      p_success_msg            => 'No issues found for requisitions sourced to blanket or contract purchase order.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '14'
      );
   l_info.delete;
debug('end add_signature: REQS_SOURCED_BLANKET_CONTRACT_HEADER_LINE_ERROR');



debug('begin add_signature: REQS_WITH_BLANKETS_APPROACHING_MAX_TOTAL_RELEASED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5658',
      p_sig_id                 => 'REQS_WITH_BLANKETS_APPROACHING_MAX_TOTAL_RELEASED',
      p_sig_sql                => 'SELECT prha.segment1 req_number
,prha.authorization_status Status
,  prla.document_type_code Source_Doc_Type
, BLRL.SEGMENT1 Source_Doc_Number
, blrl.amount_limit Source_Doc_Amount_Limit
, BLRL.blanket_released_amount
, blrl.amount_limit - BLRL.blanket_released_amount Amount_Remaining_To_Release
, SUM(prla.unit_price * prla.quantity ) Total_Requisition_Amount
FROM po_requisition_headers prha
   , po_requisition_lines prla
, (SELECT 
    poh.po_header_id, poh.segment1,poh.amount_limit, 
    nvl ( sum ( decode ( PLL2.quantity, NULL , ( PLL2.amount-
nvl(PLL2.amount_cancelled,0) ),        
       (  ( PLL2.quantity -  nvl(PLL2.quantity_cancelled,0)
)* PLL2.price_override ) ) ), 0 ) blanket_released_amount
FROM 
       PO_LINE_LOCATIONS PLL2, PO_RELEASES_all POR2, po_headers POH
WHERE 
       PLL2.po_release_id = POR2.po_release_id
    AND POR2.po_header_id = POH.po_header_id
     AND nvl(POR2.approved_flag, ''N'') = ''Y''
     AND POH.amount_limit is Not Null   
    group by poh.po_header_id, poh.segment1, poh.amount_limit ) BLRL 
WHERE prha.requisition_header_id = prla.requisition_header_id
AND prla.line_location_id IS  NULL  --REQ IS NOT ON A PO
AND nvl(prla.closed_code, ''OPEN'') <> ''FINALLY CLOSED''
AND nvl(prla.cancel_flag, ''N'') <> ''Y''
and prla.blanket_po_header_id = blrl.po_header_id
and prla.creation_Date > sysdate - 360
GROUP BY prha.segment1 
 ,prha.authorization_status 
 ,prla.document_type_code
, BLRL.SEGMENT1 
, blrl.amount_limit
, BLRL.blanket_released_amount
, blrl.amount_limit - BLRL.blanket_released_amount 
HAVING nvl(blrl.amount_limit - BLRL.blanket_released_amount,0) <  SUM(prla.unit_price * prla.quantity ) + 500  --If Req within $500 of total 
union
SELECT prha.segment1 req_number
,prha.authorization_status Req_Status
, prla.document_type_code Source_Doc_Type
, GLOBAL_REL.SEGMENT1 Source_Doc_Number
, GLOBAL_REL.amount_limit Source_Doc_Amount_Limit
, GLOBAL_REL.blanket_released_amount
, GLOBAL_REL.amount_limit - GLOBAL_REL.blanket_released_amount Amount_Remaining_To_Release
, SUM(prla.unit_price * prla.quantity ) Total_Requisition_Amount
FROM po_requisition_headers prha
   , po_requisition_lines prla
  , (SELECT 
    poh.po_header_id, poh.segment1,poh.amount_limit, 
    nvl ( sum ( decode ( PLL2.quantity, NULL , ( PLL2.amount-
nvl(PLL2.amount_cancelled,0) ),        
       (  ( PLL2.quantity -  nvl(PLL2.quantity_cancelled,0)
)* PLL2.price_override ) ) ), 0 ) blanket_released_amount
FROM 
       PO_LINE_LOCATIONS PLL2, 
       PO_LINES POL, 
       po_headers POH, 
       po_headers STD
WHERE 1=1
    AND POL.FROM_HEADER_ID (+) = POH.PO_HEADER_ID  --LINKS STD PO LINE TO BLANKET HEADER
   AND PLL2.PO_LINE_ID (+) = POL.PO_LINE_ID 
   and std.po_header_id (+) = pol.po_header_id
   and std.authorization_status (+) = ''APPROVED'' 
      AND POH.amount_limit is Not Null
    group by poh.po_header_id, poh.segment1, poh.amount_limit) GLOBAL_REL  
WHERE prha.requisition_header_id = prla.requisition_header_id
AND prla.line_location_id IS  NULL  
AND nvl(prla.closed_code, ''OPEN'') <> ''FINALLY CLOSED''
AND nvl(prla.cancel_flag, ''N'') <> ''Y''
and prla.blanket_po_header_id = GLOBAL_REL.po_header_id
and prla.creation_Date > sysdate - 360
GROUP BY prha.segment1 
 ,prha.authorization_status 
, prla.document_type_code
, GLOBAL_REL.SEGMENT1 
, GLOBAL_REL.amount_limit
, GLOBAL_REL.blanket_released_amount
, GLOBAL_REL.amount_limit - GLOBAL_REL.blanket_released_amount 
HAVING nvl(GLOBAL_REL.amount_limit - GLOBAL_REL.blanket_released_amount,0) <  SUM(prla.unit_price * prla.quantity ) + 500 --Req within $500 of total - total released',
      p_title                  => 'Requisitions Sourced to Blanket Agreements That Are Approaching Total Agreed Amount',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<p>Requisitions have amounts that may <strong>exceed</strong> the total on the Blanket Agreement. This happens due to some Blanket Releases being created but not yet approved and in this case, it will be taken into consideration per the standard functionality.</p>',
      p_solution               => 'See [1487706/KB296642] - Blanket Purchase Agreement ( BPA ) Released Amount Greater Than BPA Agreed Amount for a detailed explanation of the functionality.  Review the Requisitions and associated Blanket Agreements listed and make any required adjustments to the Agreed Amount or negotiation a new Blanket Agreement if required by your business.',
      p_success_msg            => '<p>No requisitions found with amounts that might <strong>exceed</strong> the total on the Blanket Agreement.</p>',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: REQS_WITH_BLANKETS_APPROACHING_MAX_TOTAL_RELEASED');



debug('begin add_signature: MU_REQAPPROVAL_ACTION_RESERVE_DOC');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23069',
      p_sig_id                 => 'MU_REQAPPROVAL_ACTION_RESERVE_DOC',
      p_sig_sql                => 'select 
segment1 Requisition_Number,
org_id Org_ID,
Activity Activity,
Result Result,
ERROR_NAME ERROR_NAME,
ERROR_MESSAGE ERROR_MESSAGE
from (
SELECT reqh.segment1 segment1,
reqh.org_id org_id,
ac.name||'' (''||ac.display_name||'')'' Activity,
ias.activity_result_code Result,
ias.error_name ERROR_NAME,
ias.error_message ERROR_MESSAGE,
ias.error_stack ERROR_STACK
FROM 
po_requisition_headers_all reqh,
wf_item_activity_statuses ias,
wf_process_activities pa,
wf_activities_vl ac,
wf_activities ap,
wf_items i,
dba_source als
WHERE ias.item_type like ''REQAPPRV''
AND ias.activity_status = ''ERROR''
AND ias.process_activity = pa.instance_id
AND pa.activity_name = ac.name
AND pa.activity_item_type = ac.item_type
AND pa.process_name = ap.name
AND pa.process_item_type = ap.item_type
AND pa.process_version = ap.version
AND i.item_type = ''REQAPPRV''
AND i.item_key = ias.item_key
AND i.item_key = reqh.wf_item_key
AND i.item_type = reqh.wf_item_type
AND i.begin_date >= ac.begin_date
AND i.begin_date < nvl(ac.end_date, i.begin_date+1)
AND ias.error_stack like ''%Wf_Engine_Util.Function_Call(PO_REQAPPROVAL_ACTION.RESERVE_DOC%''
AND ''12.1'' = substr((SELECT max(release_name) FROM fnd_product_groups),1,4)
AND FND_IREP_LOADER_PRIVATE.compare_versions(substr(substr(als.text,regexp_instr(als.text,'' *[0-9]'',1,1,1)-1),1, instr(substr(als.text,regexp_instr(als.text,'' *[0-9]'',1,1,1)-1), '' '',1,1)-1),''120.41.12010000.3'') = ''<''
AND als.type = ''PACKAGE BODY''
AND als.name = ''POR_AME_REQ_WF_PVT''
AND als.text like ''%$Header%''
ORDER BY ias.begin_date, ias.execution_time)',
      p_title                  => 'Requisition Approval Error at PO_REQAPPROVAL_ACTION.RESERVE_DOC When Using AME With Encumbrance',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'When approving a Purchase Requisition using AME with encumbrance an error occurs at the following function call:  Wf_Engine_Util.Function_Call(PO_REQAPPROVAL_ACTION.RESERVE_DOC',
      p_solution               => 'Refer to [1277855/KB710343] Requisition Approval Errors With PO_REQAPPROVAL_ACTION.RESERVE_DOC When Using AME With Encumbrance
',
      p_success_msg            => 'OK! No issue found for Requisition approval when using AME with Encumbrance',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: MU_REQAPPROVAL_ACTION_RESERVE_DOC');



debug('begin add_signature: WFSTAT_NOTE1507132.1');
   l_info('##MASK##%RECIPIENT%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##%USER%'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##MASK##SUBJECT'):= 'DISPLAY_FIRST_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4219',
      p_sig_id                 => 'WFSTAT_NOTE1507132.1',
      p_sig_sql                => 'select * from
(SELECT NOTIFICATION_ID, GROUP_ID, MESSAGE_TYPE, MESSAGE_NAME, RECIPIENT_ROLE, STATUS, MAIL_STATUS, FROM_USER, TO_USER, SUBJECT, ITEM_KEY

FROM wf_notifications wn
   WHERE wn.message_name IN ( ''PO_PO_APPROVE'', ''PO_PO_APPROVE_PDF'', ''PO_PO_REMINDER_1'', ''PO_PO_REMINDER_2'' )
   AND wn.status = ''OPEN''
   MINUS
   SELECT wn.NOTIFICATION_ID, wn.GROUP_ID, wn.MESSAGE_TYPE, wn.MESSAGE_NAME, wn.RECIPIENT_ROLE, wn.STATUS, wn.MAIL_STATUS, wn.FROM_USER, wn.TO_USER, wn.SUBJECT, wn.ITEM_KEY
   FROM wf_notifications wn,
   wf_notification_attributes wia
   WHERE
   wn.message_name IN ( ''PO_PO_APPROVE'', ''PO_PO_APPROVE_PDF'', ''PO_PO_REMINDER_1'', ''PO_PO_REMINDER_2'' )
   AND wn.status = ''OPEN''
   AND wn.notification_id=wia.notification_id AND NAME=''NOTE_R'')
where po_apprvl_analyzer_pkg.compare_versions(po_apprvl_analyzer_pkg.max_file_version(''poxwfpoa.wft''), ''120.27.12010000.9'') >= 0
 ',
      p_title                  => 'PO Notifications Affected By Attribute NOTE_R Does Not Exist',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Upon Approval of a Purchase Order the following error is present in the environment:
 
POXDOFDO: ORA-20002:3203: Attribute ''NOTE_R'' Does Not Exist For Notification ''nnn''.

The document notifications for affected Purchase Orders are listed (per the Max Rows parameter specified).  Additional rows may exist.',
      p_solution               => 'Review and apply the solution described in [1507132/KB495799] to resolve the error, Attribute NOTE_R Does Not Exist.',
      p_success_msg            => 'There are no open notifications for Purchase Order approval indicating Attribute NOTE_R Does Not Exist',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '24'
      );
   l_info.delete;
debug('end add_signature: WFSTAT_NOTE1507132.1');



debug('begin add_signature: MU_APPROVAL_INIT1_GET_PO_ATTRIBUTES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23064',
      p_sig_id                 => 'MU_APPROVAL_INIT1_GET_PO_ATTRIBUTES',
      p_sig_sql                => 'select  BEGINDATE BEGINDATE,
ORG_ID ORG_ID,
TYPECODE TYPECODE,
PONUM PONUM,
POSTATUS POSTATUS,
ERROR_MESSAGE_AND_ERROR_STACK ERROR_MESSAGE_AND_ERROR_STACK
FROM
(SELECT i.begin_date "BEGINDATE", i.user_key "PONUM", poh.org_id, 
decode(poh.type_lookup_code, ''PLANNED'',''PA'',''CONTRACT'',''PA'', ''BLANKET'', ''PA'', ''STANDARD'', ''PO'', ''PO'') TYPECODE,
poh.authorization_status "POSTATUS",
--"ac.name||'' (''||ac.display_name||'')'' "ACTIVITY",
--ias.activity_result_code "RESULT",
--ias.error_name "ERROR_NAME",
concat(concat(''Error_Message: '', ias.ERROR_MESSAGE), concat(''  Error_Stack: '', ias.ERROR_STACK)) ERROR_MESSAGE_AND_ERROR_STACK
FROM wf_item_activity_statuses ias,
wf_process_activities pa,
wf_activities_vl ac,
wf_activities ap,
wf_items i,
po_headers_all poh
WHERE ias.item_type = ''POAPPRV''
AND ias.activity_status = ''ERROR''
AND poh.wf_item_key = i.item_key
AND ias.process_activity = pa.instance_id
AND pa.activity_name = ac.name
AND pa.activity_item_type = ac.item_type
AND pa.process_name = ap.name
AND pa.process_item_type = ap.item_type
AND pa.process_version = ap.version
AND i.item_type = ''POAPPRV''
AND i.item_key = ias.item_key
AND i.begin_date >= ac.begin_date
AND i.begin_date < nvl(ac.end_date, i.begin_date+1)
AND ias.error_message like ''%ORA-06512%''
AND ias.error_stack like ''%Wf_Engine_Util.Function_Call(PO_POAPPROVAL_INIT1.GET_PO_ATTRIBUTES%POAPPRV%''
ORDER BY ias.begin_date desc, ias.execution_time)
order by begindate desc',
      p_title                  => 'Purchase Order Approval Fails at PO_POAPPROVAL_INIT1.GET_PO_ATTRIBUTES',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The approval workflow process has failed with error at PO_POAPPROVAL_INIT1.GET_PO_ATTRIBUTES. <br>
This error occurs when the workflow is initiated earlier and then later an upgrade or patching occurs that introduces new attributes to the approval workflow which are not contained in the already initiated workflow.<br>
The issue may also occur on purchase orders having zero quantity for quantity ordered or amount on the distribution.<br>',
      p_solution               => '<br> 1. Review the output of [1525670/KB169264] Purchasing Approval Analyzer for the failing document and check the conditions
<br> 
<br> 2. To fix the issue for purchase orders which were in process during the upgrade
<br> 
<br> 2.1 Add the missing attributes to the workflow, Apply Patch 24375046:R12.PO.D.
<br> 
<br> 2.2 For existing Purchase Orders stuck in workflow due to the above condition (Purchase Orders were in process when upgrade was performed), contact Support for datafix details and reference [2174354/KB294340]
<br> 
<br> 
<br> 3. To prevent and fix the issue of purchase orders having zero quantity for quantity ordered or amount on the distribution
<br> 
<br> 3.1 Apply the code fix for your release
<br>         For 12.2.x release:  Apply patch 29171374:R12.PO.D OR patch 29121578:R12.PO.D
<br>         For 12.1.x release:  Apply patch 16515181:R12:PO:B
<br> 
<br> 3.2 Fix the existing purchasing documents that have the issue
<br> 
<br> 3.2.1 Review the Procurement Approval Analyzer output for the problem document, and confirm if there are any distributions having zero quantity ordered or amount.
<br> 
<br> 3.2.2 For the PO Distribution having zero quantity ordered or amount, check if the req_distribution_id is null (NOT populated)
<br> 
<br>     NOTE1:  ** If req_distribution_id is NOT null ** (there is a req_distribution_id value) then request additional advice from Support regarding a datafix.  Do Not use the below steps if req_distribution_id is NOT null.
<br> 
<br> After confirming req_distribution_id is NULL for the po_distribution_id that has zero quantity
<br> 3.2.2.a. Follow instructions from [390023/KB627850] in order to obtain a reset script.
<br> 3.2.2.b. Apply reset script against the document according to instructions from [390023/KB627850] . The reset script will modify the document status to Requires Reapproval or Incomplete.
<br> 3.2.2.c. Query the document and delete the distribution with zero quantity ordered/amount ordered.
<br> 3.2.2.d. Save changes and resubmit approval process.
',
      p_success_msg            => 'OK! No issue found for Purchase Order Approval at PO_POAPPROVAL_INIT1.GET_PO_ATTRIBUTES.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: MU_APPROVAL_INIT1_GET_PO_ATTRIBUTES');



debug('begin add_signature: AUTOCREATE_TO_ORG_SHIP_TO_ORG');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4733',
      p_sig_id                 => 'AUTOCREATE_TO_ORG_SHIP_TO_ORG',
      p_sig_sql                => 'select mtl.*,poll.ship_to_organization_id
from mtl_supply mtl,po_line_locations_all poll
where mtl.supply_type_code = ''PO''
and mtl.po_line_location_id = poll.line_location_id
and mtl.po_header_id = poll.po_header_id
and mtl.to_organization_id != poll.ship_to_organization_id
and nvl(poll.closed_code,''OPEN'') != ''FINALLY CLOSED''
and nvl(poll.cancel_flag,''N'') != ''Y'' and nvl(poll.quantity_received,0) = 0',
      p_title                  => 'Purchase Orders Have TO_ORGANIZATION_ID Column in MTL_SUPPLY Table Not Equal to SHIP_TO_ORGANIZATION_ID in Purchase Order Shipments',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<p>There is data corruption where purchase orders have the TO_ORGANIZATION_ID column in MTL_SUPPLY table not equal to SHIP_TO_ORGANIZATION_ID in Purchase Order Shipments.</p>',
      p_solution               => 'A datafix and patch fix are available.<p>See datafix from [1280061/KB566661] - Purchase Order Ship To Organization Does Not Match Distribution Deliver To Organization After Location Update In Buyer Work Center.</p>
<p>To prevent the issue from occurring again apply patch {10418505} R12.PO.B.</p>',
      p_success_msg            => 'No data corruption exists.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '12'
      );
   l_info.delete;
debug('end add_signature: AUTOCREATE_TO_ORG_SHIP_TO_ORG');



debug('begin add_signature: AUTOCREATE_SHIP_ORG_DESTINATION_ORG');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4730',
      p_sig_id                 => 'AUTOCREATE_SHIP_ORG_DESTINATION_ORG',
      p_sig_sql                => 'select pod.po_header_id,pod.po_distribution_id,pod.line_location_id,
pod.destination_organization_id,poll.ship_to_organization_id
from po_distributions_all pod,po_line_locations_all poll
where pod.line_location_id = poll.line_location_id
and pod.po_header_id = poll.po_header_id
and pod.destination_organization_id != poll.ship_to_organization_id
and nvl(poll.closed_code,''OPEN'') != ''FINALLY CLOSED''
and nvl(poll.cancel_flag,''N'') != ''Y'' and nvl(poll.quantity_received,0) = 0',
      p_title                  => 'Ship To ORG_ID in Shipments Table Not Equal to Destination ORG_ID in Distributions Table',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<p>There is data corruption where Purchase Orders have the Ship To ORG_ID in shipments table not equal to destination ORG_ID in distributions table.</p>
<p>Code in source PoShipmentsRenderCmd.class which is responsible to synchronize the purchase order shipment''s ''ship-to'' organization and distribution''s ''destination'' organizations is incorrectly removed. Records shown for Purchase Orders in the Inventory supply/demand is based on the destination organization in Purchase Order distributions.  So, this issue causes improper data to be displayed in Inventory supply/demand and MRP reports.</p>',
      p_solution               => 'A patch fix and datafix are available.
<p>See datafix from [1280061/KB566661] - Purchase Order Ship To Organization Does Not Match Distribution Deliver To Organization After Location Update In Buyer Work Center to resolve any data issues.</p>
<p>Apply patch {10418505} R12.PO.B to prevent the issue from occurring again.</p>',
      p_success_msg            => 'No data corruption exists',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: AUTOCREATE_SHIP_ORG_DESTINATION_ORG');



debug('begin add_signature: MU_PRC_PF_INVALID_RECEIVING_EVENTS2');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23072',
      p_sig_id                 => 'MU_PRC_PF_INVALID_RECEIVING_EVENTS2',
      p_sig_sql                => 'SELECT
    ledger_id     ledger_id,
    ledger_name   ledger_name,
    org_id        org_id
FROM
    (
        SELECT
            xte.ledger_id           ledger_id,
            l.name                  ledger_name,
            xte.security_id_int_2   org_id
        FROM
            xla_transaction_entities_upg   xte,
            xla_events                     xe,
            gl_ledgers                     l
        WHERE
            xte.entity_code IN (
                ''RCV_ACCOUNTING_EVENTS''
            )
            AND xe.application_id = xte.application_id
            AND xte.entity_id = xe.entity_id
            AND xte.application_id = 707
            AND xe.process_status_code = ''I''
            AND xte.ledger_id = l.ledger_id
            AND xe.event_date BETWEEN SYSDATE - 30 AND SYSDATE
             AND xte.security_id_int_2 IS NOT NULL
        GROUP BY
            xte.ledger_id,
            l.name,
            xte.security_id_int_2
        HAVING
            COUNT(*) > 0
    )',
      p_title                  => 'Invalid Receiving Events for The Last 30 Days',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found invalid receiving events for the last 30 days',
      p_solution               => 'From Cost Management, Run Create Accounting for Receiving process category or from Purchasing, Run Create Accounting - Receiving. Review and resolve the errors detailed in output file if any.<br>
Refer to [2425619/KB795139] Invalid Receiving Accounting Events',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: MU_PRC_PF_INVALID_RECEIVING_EVENTS2');



