debug('begin add_signature: MU_00233_RCT_DIV_BY_ZERO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23087',
      p_sig_id                 => 'MU_00233_RCT_DIV_BY_ZERO',
      p_sig_sql                => 'select  cr.cash_receipt_id,
        cr.receipt_number,
        app.receivable_application_id,
        app.amount_applied_from,
        app.amount_applied
FROM    xla_events gt,
        ar_receivable_applications_all app,
        ar_cash_receipts_all cr,
        ar_cash_receipt_history_all crh,
        ra_customer_trx_all trx
WHERE   gt.event_type_code IN ( ''RECP_CREATE'' ,''RECP_UPDATE'' , ''RECP_RATE_ADJUST'' ,''RECP_REVERSE'')
AND     gt.application_id = 222
AND     gt.event_date between trunc(sysdate - 30) and trunc(sysdate + 30)
AND     gt.event_id = app.event_id
AND     DECODE(app.acctd_amount_applied_to,0,DECODE(app.acctd_amount_applied_from,0,''N'',''Y''),''N'') = ''Y''
AND     app.cash_receipt_id = cr.cash_receipt_id
AND     app.cash_receipt_history_id = crh.cash_receipt_history_id(+)
AND     app.applied_customer_trx_id = trx.customer_trx_id(+)
AND     nvl(app.amount_applied_from,0) = 0 and nvl(app.amount_applied,0) = 0
AND     app.posting_control_id = -3
Order By 1,2',
      p_title                  => 'Receipt(s) Failing with ORA-01476 Error ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found receipt(s) that fail with Error: ORA-01476 divisor is equal to zero.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1474419/KB625902].</li>
<li>Please run the Receipt Analyzer in [2089720/KB160951] for the cash_receipt_id values listed.</li></ul>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_00233_RCT_DIV_BY_ZERO');



debug('begin add_signature: MU_00322_TRX_NEG_EXCH_RATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23090',
      p_sig_id                 => 'MU_00322_TRX_NEG_EXCH_RATE',
      p_sig_sql                => 'select distinct gld.customer_trx_id,
       trx_number TRX_NUMBER,
       exchange_rate EXCHANGE_RATE
from   ra_cust_trx_line_gl_dist_all gld,
       ra_customer_trx_all  ct,
       gl_ledgers gl    
where  gld.customer_trx_id = ct.customer_trx_id
and    ct.exchange_rate is not null
and    sign(ct.exchange_rate) < 0
and    ct.set_of_books_id = gl.ledger_id
and    ct.invoice_currency_code <> gl.currency_code
and    gld.account_set_flag = ''N''
and    gld.gl_date between trunc(sysdate - 30) and trunc(sysdate + 30)
and    gld.account_class = ''REC''
and    gld.latest_rec_flag = ''Y''
and    gld.posting_control_id = -3
and    sign(gld.acctd_amount) <> sign(gld.amount)
and not exists (select ''x''
                from   ra_cust_trx_line_gl_dist_all gld_posted
                where  gld_posted.posting_control_id <> -3
                and    gld_posted.account_set_flag = ''N''
                and    gld_posted.customer_trx_id = gld.customer_trx_id )
and rownum <= 5',
      p_title                  => 'Transaction Has Negative Exchange Rate ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Transaction has negative exchange rate.',
