debug('begin add_signature: MU_ADJ_UNBAL_DISTRIBUTION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23092',
      p_sig_id                 => 'MU_ADJ_UNBAL_DISTRIBUTION',
      p_sig_sql                => 'select adj.adjustment_id ADJUSTMENT_ID, 
       adj.adjustment_number ADJUSTMENT_NUMBER,
       ard.amount_dr AMOUNT_DR,
       ard.amount_cr AMOUNT_CR,
       ard.acctd_amount_dr ACCTD_AMOUNT_DR,
       ard.acctd_amount_cr ACCTD_AMOUNT_CR
  from ar_adjustments_all adj, 
       fnd_user users,
       ar_distributions_all ard
 where adj.created_by = users.user_id
   and adj.posting_control_id = -3
   and nvl(adj.POSTABLE,''N'') = ''Y''  
   and ard.source_id = adj.adjustment_id
   and ard.source_table = ''ADJ''
   and EXISTS (select ''x''
                 from ar_distributions_all
                where source_table = ''ADJ''
                  and source_id = adj.adjustment_id
               group by source_id
               having (sum(nvl(acctd_amount_dr, 0)) <> sum(nvl(acctd_amount_cr, 0))
                       OR 
                       sum(nvl(amount_dr, 0)) <> sum(nvl(amount_cr, 0)) 
                      )
               )
  and gl_date between trunc(sysdate) - 30 and trunc(sysdate) + 30
  and rownum <= 5
',
