debug('end add_signature: MU_ADJ_UNBAL_DISTRIBUTION');



debug('begin add_signature: MU_APP_UNAPP_DIFF_EVENT_ID');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23100',
      p_sig_id                 => 'MU_APP_UNAPP_DIFF_EVENT_ID',
      p_sig_sql                => 'SELECT  DISTINCT ra.cash_receipt_id CASH_RECEIPT_ID, 
		cr.receipt_number RCT_NUMBER,
		ra.gl_date GL_DATE,
		ra.receivable_application_id APP_RECEIVABLE_APPLICATION_ID,
        ra_unapp.receivable_application_id UN_RECEIVABLE_APPLICATION_ID,
        ra_unapp.event_id UNAPP_EVENT_ID, 
		ra.event_id APP_EVENT_ID, 
		ra.posting_control_id POSTING_CONTROL_ID, 
		ra.gl_posted_date GL_POSTED_DATE
from  	ar_receivable_applications_all ra_unapp,
       	ar_receivable_applications_all ra,
        ar_distributions_all ard_unapp,
		ar_cash_receipts_all cr
where  	ra.gl_date between trunc(sysdate) - 30 and trunc(sysdate) + 30
and   	ra_unapp.status = ''UNAPP''
and   	ra_unapp.cash_receipt_id = ra.cash_receipt_id
and   	cr.cash_receipt_id = ra.cash_receipt_id
and   	ra.status <> ''UNAPP''
and   	ra_unapp.event_id <> ra.event_id
and   	ra_unapp.gl_date = ra.gl_date
and   	ra.posting_control_id <> -3
and   	ra_unapp.posting_control_id = -3
and   	ra_unapp.receivable_application_id = ard_unapp.source_id
and   	ard_unapp.source_table = ''RA''
and   	ard_unapp.source_id_secondary = ra.receivable_application_id 
order 	by 1',
