debug('begin add_signature: MU_CMAPP_UNBAL_DISTRIBUTION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23093',
      p_sig_id                 => 'MU_CMAPP_UNBAL_DISTRIBUTION',
      p_sig_sql                => 'select     distinct ra.customer_trx_id customer_trx_id,
           ct.trx_number TRX_Number, 
           ra.receivable_application_id receivable_application_id,
          ra.org_id org_id
    from   ar_receivable_applications_all ra ,
           ra_customer_trx_all ct,	
           ar_distributions_all ard 
    where  ra.application_type = ''CM''
    and    ra.posting_control_id = -3 
    AND    ra.gl_date between trunc(sysdate - 30) and trunc(sysdate + 30)
    and    ra.receivable_application_id = ard.source_id 
	and    ra.customer_trx_id = ct.customer_trx_id
    and    ard.source_table = ''RA''
    and    not exists 
      ( SELECT SUM(NVL(ARD.ACCTD_AMOUNT_DR,0)) , SUM(NVL(ARD.ACCTD_AMOUNT_CR,0)) 
        from   ar_distributions_all ard 
        where  ard.source_id = ra.receivable_Application_id 
        and    ard.source_table = ''RA''
        and    exists 
         ( select ''x''
           from   ar_distributions_All ard 
           where  ard.source_id = ra.receivable_application_id 
           and    ard.source_table = ''RA'' 
           and    nvl(ard.ref_customer_trx_line_id,0) <> -6
           and    nvl(ard.ref_cust_trx_line_gl_dist_id,0) <> -6) 
           group by ard.source_id , ard.source_table 
           HAVING SUM(NVL(ARD.ACCTD_AMOUNT_DR,0)) = SUM(NVL(ARD.ACCTD_AMOUNT_CR,0)))
    order by 1',
      p_title                  => 'Unbalanced Distributions for Credit Memo Application(s)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found credit memo application(s) with unbalanced distributions.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1565459/KB727763]</li>
<li>Please run the Transaction Analyzer in [2058269/KB157765] for the customer_trx_id values listed.</li></ul>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_CMAPP_UNBAL_DISTRIBUTION');



