debug('begin add_signature: MU_RCT_DUPLICATE_RECP_REVERSE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23091',
      p_sig_id                 => 'MU_RCT_DUPLICATE_RECP_REVERSE',
      p_sig_sql                => 'select cr.cash_receipt_id, 
       crh.cash_receipt_history_id, 
       cr.org_id, crh.event_id, 
       crh.gl_date crh_gl_date, 
       max(ra.gl_date) max_ra_gl_date, 
       xte.entity_id        
from   xla_transaction_entities_upg xte, ar_cash_receipts_all cr, 
       ar_cash_receipt_history_all crh, ar_receivable_applications_all ra        
where  xte.entity_code = ''RECEIPTS''        
and    xte.application_id = 222        
and    nvl(xte.source_id_int_1,-99)  = cr.cash_receipt_id        
and    xte.ledger_id = cr.set_of_books_id        
and    cr.cash_receipt_id = crh.cash_receipt_id        
and    crh.status = ''REVERSED''        
and    cr.status in (''REV'',''STOP'',''NSF'') 
and    ra.cash_receipt_history_id = crh.cash_receipt_history_id        
and    ra.cash_receipt_id = cr.cash_receipt_id        
and    1 < (select count(*) 
            from xla_events xe                   
            where xe.entity_id = xte.entity_id                   
            and   xe.application_id = 222                   
            and   xe.event_type_code = ''RECP_REVERSE'')
AND    crh.gl_date between trunc(sysdate - 30) and trunc(sysdate + 30)
group by cr.cash_receipt_id, crh.cash_receipt_history_id, cr.org_id, crh.event_id, 
         crh.gl_date, xte.entity_id
order by 1',
      p_title                  => 'Reversed Receipt Has Multiple RECP_REVERSE Events',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found receipt(s) with multiple reversal events.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [752574/KB731811].</li>
<li>Please run the Receipt Analyzer in [2089720/KB160951] for the cash_receipt_id values listed.</li></ul> ',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: MU_RCT_DUPLICATE_RECP_REVERSE');



