debug('begin add_signature: MU_RCT_NULL_EVENT_ID');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23097',
      p_sig_id                 => 'MU_RCT_NULL_EVENT_ID',
      p_sig_sql                => 'select crh.cash_receipt_id CASH_RECEIPT_ID,
       cr.receipt_number RECEIPT_NUMBER,
       cr.type TYPE,
       cr.org_id ORG_ID
  from ar_cash_receipts_all cr,
       AR_CASH_RECEIPT_HISTORY_ALL crh
 where crh.posting_control_id = -3
   and nvl(crh.postable_flag, ''Y'') = ''Y''
   and crh.event_id is null
   and crh.gl_date between trunc(sysdate) - 30  and trunc(sysdate) + 30 
   and cr.cash_receipt_id = crh.cash_receipt_id
   and rownum <= 5
union
select ra.cash_receipt_id,
       cr.receipt_number RECEIPT_NUMBER,
       cr.type TYPE,
       cr.org_id ORG_ID
  from ar_cash_receipts_all cr,
       ar_receivable_applications_all ra
 where ra.application_type = ''CASH''
   and ra.posting_control_id = -3
   and ra.event_id is null
   and ra.gl_date between trunc(sysdate) - 30  and trunc(sysdate) + 30
   and cr.cash_receipt_id = ra.cash_receipt_id
   and rownum <= 5
union
select mcd.cash_receipt_id CASH_RECEIPT_ID,
       cr.receipt_number RECEIPT_NUMBER,
       cr.type TYPE,
       cr.org_id ORG_ID
from   ar_cash_receipts_all cr,
       ar_misc_cash_distributions_all mcd
where  mcd.posting_control_id = -3
  and mcd.event_id is null
 and mcd.gl_date between trunc(sysdate) - 30  and trunc(sysdate) + 30
  and cr.cash_receipt_id = mcd.cash_receipt_id
  and rownum <= 5',
