debug('begin add_signature: MU_TRX_ACCRULE_DUR_GLD_MISMATCH');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23099',
      p_sig_id                 => 'MU_TRX_ACCRULE_DUR_GLD_MISMATCH',
      p_sig_sql                => 'select CUSTOMER_TRX_ID, 
       GL_DIST_ID,
       USER_NAME,
       RESP_ID
from
(
select ct.customer_trx_id CUSTOMER_TRX_ID, 
       gld_rec.CUST_TRX_LINE_GL_DIST_ID  GL_DIST_ID,
       user_name USER_NAME,
	(
	SELECT min(responsibility_id)
	FROM fnd_responsibility resp
	WHERE application_id = 222
        ) resp_id
  from ra_customer_trx_all ct,
       ra_cust_trx_types_all ctt,
       ra_cust_trx_line_gl_dist_all gld_rec,
       fnd_user users
 where ct.created_by = users.user_id 
   and ct.invoicing_rule_id in (-2,-3)
   and ctt.cust_trx_type_id = ct.cust_trx_type_id
   and ctt.type = ''CM''
   and ct.customer_trx_id = gld_rec.customer_trx_id
   and gld_Rec.account_class = ''REC''
   and gld_rec.account_set_flag = ''N''
   and gld_rec.latest_rec_flag = ''Y'' 
   and gld_rec.gl_date between sysdate-30 and sysdate+30
   and exists (select ''x''
                 from ra_customer_trx_lines_all ctl ,
                      ra_cust_trx_line_gl_dist_all gld_rev
                where ctl.customer_trx_id = ct.customer_trx_id
                  and ctl.line_type = ''LINE''
                  and ctl.customer_trx_id = gld_rev.customer_trx_id
                  and ctl.customer_trx_line_id = gld_rev.customer_trx_line_id
                  and gld_rev.account_class = ''REV''
                  and gld_rev.account_set_flag = ''N''
                group by ctl.customer_trx_id, ctl.customer_trx_line_id,
                        ctl.accounting_rule_id, ctl.accounting_rule_duration
               having count(distinct gld_rev.original_gl_date) <> ctl.accounting_rule_duration) 
   and rownum <= 5
)',
      p_title                  => 'Discrepancy in Revenue Recognition Duration for a Credit Memo',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found credit memo(s) where UNEARN/REV pair record(s) is not equal to ACCOUNTING_RULE_DURATION.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [1917656/KB272045]</li>
<li>Please run the Transaction Analyzer in [2058269/KB157765] for the customer_trx_id values listed.</li></ul>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_TRX_ACCRULE_DUR_GLD_MISMATCH');



