  add_signature(
      p_sig_repo_id            => '23079',
      p_sig_id                 => 'MU_TRX_MISSING_PS',
      p_sig_sql                => 'select distinct ct.customer_trx_id CUSTOMER_TRX_ID, 
            ct.trx_number TRX_NUMBER, ct.trx_date TRX_DATE
    from   ra_customer_trx_all ct , 
           ra_cust_trx_types_all ctt ,
