and xe.entity_id = xte.entity_id
and xe.event_status_code <> ''P''
and xte.entity_code = ''TRANSACTIONS''
and xte.upg_batch_id is NULL
and not exists
(select ''x'' from ra_cust_Trx_line_gl_dist_all gld,
ra_customer_trx_all ct
where ct.customer_trx_id = xte.source_id_int_1
and gld.account_class = ''REC''
and gld.latest_rec_flag = ''Y''
and gld.account_set_flag = ''Y''
and ct.customer_trx_id = gld.customer_trx_id
and ct.complete_flag = ''Y''
)
and not exists
(select ''x'' from ra_cust_Trx_line_gl_dist_all
where customer_trx_id = xte.source_id_int_1
and posting_control_id = -3
and event_id = xe.event_id
union
select ''x'' from ar_receivable_applications_all
where customer_trx_id = xte.source_id_int_1
and posting_control_id = -3
and event_id = xe.event_id
union
select ''x'' from ar_receivable_applications_all
where applied_customer_trx_id = xte.source_id_int_1
and posting_control_id = -3
and event_id = xe.event_id
)
order by xe.event_id',
      p_title                  => 'Identified Orphan XLA Records for Transactions ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphan record in XLA_EVENTS for transactions.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [549020/KB627319]</li>
 <li>Please run the Transaction Analyzer in [2058269/KB157765] for the customer_trx_id values listed.</li>
</ul>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_00057_TRX_ORPHAN_XLA');



debug('begin add_signature: EBS_AR_MU_AR_RCT_REV_RECONCILED_CM');
   l_info('##MASK##USER_NAME'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25785',
      p_sig_id                 => 'EBS_AR_MU_AR_RCT_REV_RECONCILED_CM',
      p_sig_sql                => 'select cr.cash_receipt_id  CASH_RECEIPT_ID, 
       cr.receipt_number RECEIPT_NUMBER,
       cr.status STATUS,
       cr.reversal_category REVERSAL_CATEGORY,
       user_name USER_NAME  
from   ar_cash_receipts_all cr, 
       fnd_user users 
where  cr.created_by = users.user_id
and    status = ''REV''
and    REVERSAL_CATEGORY = ''REV''
and exists (select 1 
            from   CE_STATEMENT_RECONCILS_ALL csr, 
			       AR_CASH_RECEIPT_HISTORY_ALL crh
            where  csr.REFERENCE_TYPE =''RECEIPT''
            and    csr.REFERENCE_ID = crh.cash_receipt_history_id
            and    csr.STATUS_FLAG	=''M''
            and    csr.CURRENT_RECORD_FLAG=''Y''
            and    crh.cash_receipt_id = cr.cash_receipt_id )
and rownum <= 5',
      p_title                  => 'Receipt Reversed with REV Category with Reconciled Bank Statement Line',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Receipt Reversed with REV Category with Reconciled Bank statement line. It will cause reconciliation issue in Cash Management, and Bank statement.',
      p_solution               => '<ul><li>The analyzer has identified data corruption described in [2488932/KB776864].</li>
<li> <li>Please run the Receipt Analyzer in [2089720/KB160951] for the cash_receipt_id values listed.</li></li>
</ul>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_AR_MU_AR_RCT_REV_RECONCILED_CM');



