debug('begin add_signature: MU_SHIPPED_DELIVERY_DETAILS_OWNED_OPEN_DELIVERY_DTLS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23155',
      p_sig_id                 => 'MU_SHIPPED_DELIVERY_DETAILS_OWNED_OPEN_DELIVERY_DTLS',
      p_sig_sql                => 'SELECT wdd.SOURCE_HEADER_NUMBER "ORDER NUMBER",
           wdd.source_header_id "ORDER ID",
           wdd.source_line_id "LINE ID",
           wnd.delivery_id "DELIVERY ID",
           wnd.status_code "DELIVERY STATUS",
           wdd.delivery_detail_id "DEL DTL ID",
           decode (wdd.released_status, 
              ''Y'',''Staged'',            ''R'',''Ready to Release'',
              ''S'',''Rel to Warehouse'',  ''B'',''Backorder'',
              ''C'',''Shipped'', wdd.RELEASED_STATUS) "DEL DTL STATUS",
           to_char(wdd.creation_date, ''DD-MON-RR'') "DEL CREATED",
           to_char(wdd.last_update_date, ''DD-MON-RR'') "DEL LAST UPDATE"
      FROM wsh_delivery_details wdd, 
           wsh_delivery_assignments wda,
           wsh_new_deliveries wnd
      WHERE wdd.source_code = ''OE''
      AND wdd.last_update_date between sysdate-30 and sysdate
      AND wdd.delivery_detail_id = wda.delivery_detail_id
      AND wda.delivery_id = wnd.delivery_id
      AND wdd.released_status = ''C''
      AND wnd.status_code not in (''IT'', ''CL'')
      order by wdd.last_update_date DESC',
      p_title                  => 'Shipped Delivery Details Owned by an Open Delivery ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Shipped Deliveries still show as open.',
      p_solution               => 'Shipped deliveries that still show as open, may cause issues during Month End closing.
<br><br>A data fix SR will need to be logged with Oracle Support. Upload the output of Sales Order Analyzer [2038363/KB552468] of the order(s) to help administer faster processing of the issue.
',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: MU_SHIPPED_DELIVERY_DETAILS_OWNED_OPEN_DELIVERY_DTLS');



