debug('begin add_signature: FC_WIP_PENDING_MOVE_TNX');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '10468',
      p_sig_id                 => 'FC_WIP_PENDING_MOVE_TNX',
      p_sig_sql                => 'SELECT WE.WIP_ENTITY_NAME,
       WMTI.TRANSACTION_ID,
       WMTI.TRANSACTION_DATE,
       WMTI.REQUEST_ID,
       WMTI.GROUP_ID,
       DECODE(WMTI.PROCESS_PHASE,
              1,              ''MOVE VALDN'',
              2,              ''MOVE PROC'',
              3,              ''BF SETUP'',
              WMTI.PROCESS_PHASE) PROCESS_PHASE,
       DECODE(WMTI.PROCESS_STATUS,
              1,              ''PENDING'',
              2,              ''RUNNING'',
              3,              ''ERROR'',
              4,              ''COMPLETED'',
              5,              ''WARNING'',
              WMTI.PROCESS_STATUS) PROCESS_STATUS,
       WMTI.TRANSACTION_TYPE,       
       DECODE(WMTI.TRANSACTION_TYPE,
              1,              ''MOVE'',
              2,              ''COMPLETE'',
              3,              ''RETURN'',
              WMTI.TRANSACTION_TYPE) TRANSACTION_TYPE_MEANING,
       DECODE(WMTI.FM_INTRAOPERATION_STEP_TYPE,
              1,              ''QUEUE'',
              2,              ''RUN'',
              3,              ''TOMOVE'',
              4,              ''REJECT'',
              5,              ''SCRAP'',
              WMTI.FM_INTRAOPERATION_STEP_TYPE) FM_OP_STEP,
       WMTI.TO_OPERATION_CODE TO_OP_CODE,
       DECODE(WMTI.TO_INTRAOPERATION_STEP_TYPE,
              1,              ''QUEUE'',
              2,              ''RUN'',
              3,              ''TOMOVE'',
              4,              ''REJECT'',
              5,              ''SCRAP'',
              WMTI.TO_INTRAOPERATION_STEP_TYPE) TO_OP_STEP,
       WMTI.ORGANIZATION_ID ORG_ID,
       MP.ORGANIZATION_CODE,
       WMTI.ACCT_PERIOD_ID,
       WMTI.PRIMARY_ITEM_ID ITEM_ID,
       WTIE.ERROR_COLUMN,
       WTIE.ERROR_MESSAGE ERROR_MESSAGE
  FROM WIP_MOVE_TXN_INTERFACE    WMTI,
       WIP_TXN_INTERFACE_ERRORS  WTIE,
       WIP_SERIAL_MOVE_INTERFACE WSMI,
       WIP_ENTITIES              WE,
       MTL_PARAMETERS            MP
 WHERE WMTI.WIP_ENTITY_ID = WE.WIP_ENTITY_ID
   AND WMTI.ORGANIZATION_ID = MP.ORGANIZATION_ID
   AND WMTI.TRANSACTION_ID = WTIE.TRANSACTION_ID(+)
   AND WMTI.TRANSACTION_ID = WSMI.TRANSACTION_ID(+)
   AND ((WMTI.PROCESS_STATUS = 3) 
           OR (WMTI.PROCESS_STATUS in (1,2) 
           AND WMTI.CREATION_DATE < sysdate - 0.25 ))
 ORDER BY 1,2',
      p_title                  => 'WIP Pending Move Transactions',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are erred WIP move transaction and pending/running transactions that are not processed for more than 6 hours.',
      p_solution               => 'For records returning PROCESS_STATUS = ERROR, visit the following document: [457066/KB627612]
For records returning PROCESS_STATUS = PENDING, check if the Move Manager is active and visit the following document: [2102653/KB753608]
For records returning PROCESS_STATUS = ERROR and PROCESS_PHASE = BACKFLUSH SETUP, see Errors document attached in Note: [1311963/KB664314]',
      p_success_msg            => 'No erred WIP move transactions or pending/running transactions that are not processed for more than 6 hours.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: FC_WIP_PENDING_MOVE_TNX');



debug('begin add_signature: DMEF RES TXN - USER NAME NOT VALID. PLEASE RE-ENTER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '21008',
      p_sig_id                 => 'DMEF RES TXN - USER NAME NOT VALID. PLEASE RE-ENTER',
      p_sig_sql                => 'SELECT WE.WIP_ENTITY_NAME,
       MP.ORGANIZATION_CODE,
       DECODE(WCTI.PROCESS_STATUS,
              1, ''PENDING'',
