debug('begin add_signature: MU_PREPAYMENT_INCORRECTLY_ACCOUNTED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22943',
      p_sig_id                 => 'MU_PREPAYMENT_INCORRECTLY_ACCOUNTED',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai xte xe xah apph) */ ai.invoice_id invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_date,
          xe.event_id,
          xe.event_date,
          xe.event_type_code,
          xe.event_status_code,
          xe.process_status_code,
          xah.ledger_id,
          xe.budgetary_control_flag,
          apph.transaction_type,
          apph.prepay_history_id,
          apph.invoice_line_number,
          apph.prepay_invoice_id,
          apph.prepay_line_num,
          apph.related_prepay_app_event_id,
          apph.bc_event_id,
          apph.posted_flag,
          ai.set_of_books_id
FROM ( SELECT DISTINCT invoice_id FROM ap_invoice_distributions_all WHERE accounting_date BETWEEN (trunc(sysdate) - 7) 
AND (trunc(sysdate) + 3) ) invs, ap_invoices_all ai, xla_transaction_entities_upg xte, xla_events xe, xla_ae_headers xah, 
ap_prepay_history_all apph 
WHERE xe.application_id = 200 AND   xah.application_id = 200 AND   xte.application_id = 200 
AND   xte.entity_code = ''AP_INVOICES'' AND   xe.entity_id = xte.entity_id AND   xe.event_id = xah.event_id 
AND   xe.event_type_code IN (''PREPAYMENT APPLIED'',''PREPAYMENT UNAPPLIED'') AND   nvl(xe.budgetary_control_flag,''N'') = ''N'' 
AND   abs(ap_acctg_data_fix_pkg.GET_NET_PREPAY_APP(xe.event_id) - ap_acctg_data_fix_pkg.GET_NET_PREPAY_ACCT(xe.event_id, xah.ledger_id) - ap_acctg_data_fix_pkg.GET_NET_ADJ_ACCT(xe.event_id, xah.ledger_id)) > .01 
AND   xe.event_status_code = ''P'' AND   xah.upg_batch_id is null AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id 
AND   xte.ledger_id = ai.set_of_books_id AND   xah.event_id = apph.accounting_event_id 
AND   NOT EXISTS ( SELECT /*+ no_unnest */ 1 FROM ap_prepay_history_all apph2 
WHERE apph2.invoice_id = ai.invoice_id AND   apph2.related_prepay_app_event_id = xe.event_id 
AND   apph2.transaction_type = ''PREPAYMENT APPLICATION ADJ'' AND   apph2.posted_flag <> ''Y'') 
AND   ai.invoice_id = invs.invoice_id
AND rownum<1000
order by invoice_id',
      p_title                  => 'Prepayment Event Incorrectly Accounted ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Prepayment applications incorrectly accounted.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>25923912</br><strong>Note: </strong>[1349591/KB514647]</br><strong>Script Name: </strong>ApPrepayIncorrAcctgSel.sql</br></br>Apply the GDF patch following the instructions provided in [1349591/KB514647]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158].</br>',
      p_success_msg            => 'OK! No issue found',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: MU_PREPAYMENT_INCORRECTLY_ACCOUNTED');



